const int N = 55;
const int K = 14;
char s[N][N];
int p3[K];
int n, m, k;
int dp[(1 << K) + 3];
int c[K];

void calcRad(int x, int y) {
	for (int k = 0; k < K; k++)
		c[k] = 0;
	for (int i = 0; i < n; i++)
		for (int j = 0; j < m; j++) if (s[i][j] == '#') {
			int d = sqr(i - x) + sqr(j - y);
			for (int k = 1; k <= K; k++) if (d <= k * k)
				c[k - 1]++;
		}
}

void solve() {
	scanf("%d%d%d", &n, &m, &k);
	for (int mask = 0; mask < (1 << K); mask++)
		dp[mask] = 0;
	for (int i = 0; i < n; i++)
		scanf("%s", s[i]);
	while(k--) {
		int x, y, w;
		scanf("%d%d%d", &x, &y, &w);
		x--;y--;
		calcRad(x, y);
		for (int mask = 0; mask < (1 << K); mask++)
			for (int k = 0; k < K; k++) if ((mask >> k) & 1)
				dp[mask ^ (1 << k)] = max(dp[mask ^ (1 << k)], dp[mask] + w * c[k] - p3[k]);
	}
	printf("%d\n", dp[0]);
}

