const int M = 998244353;

inline int add(int a, int b) {
  a += b;
  if (a >= M) a -= M;
  return a;
}

void adds(int &a, int b) {
  a += b;
  if (a >= M) a -= M;
}

inline int mul(int a, int b) {
  return a * 1ll * b % M;
}

inline int sub(int a, int b) {
  a -= b;
  if (a < 0) a += M;
  return a;
}

map<ll, pair<vector<int>, vector<int>>> dp;
#define sz(v) (int)v.size()
pair<vector<int>, vector<int>> dfs(ll n) {
  if (n == 0) return {{}, {}};
  if (n == 1) return {{1}, {1}};
  if (dp.count(n)) return dp[n];
  ll lg = 1;
  while ((1ll << lg + 1) <= n) {
    ++lg;
  }
  lg += 1;
  ll lsz = min((1ll << (lg - 1)) - 1, n - (1ll << (lg - 2)));
  ll rsz = n - lsz - 1;
  auto [dpl, dpll] = dfs(lsz);
  auto [dpr, dprr] = dfs(rsz);
  vector<int> dp(lg);
  dp[0] = 1;
  for (int i = 0; i < sz(dpl); ++i) adds(dp[i + 1], dpl[i]);
  for (int i = 0; i < sz(dpr); ++i) adds(dp[i + 1], dpr[i]);
  vector<int> dpp(lg * 2);
  for (int i = 0; i < sz(dpl); ++i) {
    for (int j = 0; j < sz(dpr); ++j) {
      adds(dpp[i + j + 2], mul(dpl[i], dpr[j]));
    }
  }
  for (int i = 0; i < lg; ++i) adds(dpp[i], dp[i]);
  for (int i = 0; i < sz(dpll); ++i) adds(dpp[i], dpll[i]);
  for (int i = 0; i < sz(dprr); ++i) adds(dpp[i], dprr[i]);
  int c = 0, cc = 0;
  for (int x : dp) adds(cc, x);
  for (int x : dpp) adds(c, x);
  return ::dp[n] = {dp, dpp};
}
#undef sz(v)

int pw(ll a, ll b) {
  int ret = 1;
  a %= M;
  while (b > 0) {
    if (b & 1) ret = mul(ret, a);
    a = mul(a, a);
    b /= 2;
  }
  return ret;
}

void solve() {
  ll n, m;
  cin >> n >> m;
  auto [_, dp] = dfs(n);
  int ans = 0;
  int k = dp.size();
  vector<int> p(m + 1, 1);
  for (int i = 0; i < k; ++i) {
    dp[i] = mul(dp[i], pw(m, n - i - 1));
    int last = 0;
    for (int j = 1; j <= m; ++j) {
      p[j] = mul(p[j], j);
      ans = add(ans, mul(dp[i], mul(sub(p[j], last), j)));
      last = p[j];
    }
  }
  cout << ans << '\n';

}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int t = 1;
  cin >> t;
  while(t--) {
    solve();
  }
}

