  for (int &x : a) {
    cin >> x;
    ++counts[x];
  }
  vector<long long> ans(n + 1);
  stack<pair<int, long long>> st;
  long long cost = 0;
  bool ok = true;
  for (int i = 0; i <= n; ++i) {
    if (!ok) {
      ans[i] = -1;
      continue;
