class BProgulkaPoMassivu {
public:
    void solve() {
        int n = in.readInt();
        int k = in.readInt();
        int z = in.readInt();
        auto a = in.readIntArray(n);

        arr2d<int> answer(z + 1, k + 1, 0);
        answer(0, 0) = a[0];
        for (int i : range(1, k + 1)) {
            for (int j : range(z + 1)) {
                answer(j, i) = answer(j, i - 1) + a[i];
                if (j != z) {
                    maxim(answer(j + 1, i - 1), answer(j, i) + a[i - 1]);
                }
            }
        }
        int result = 0;
        for (int i : range(min(z + 1, k / 2 + 1))) {
            maxim(result, answer(i, k - 2 * i));
        }
        out.printLine(result);
    }
};


