void dfs(int x, int y){

	for (int i=l[x]; i; i=qn[i]){
		if (qd[i]!=y) dfs(qd[i], x);
	}

	int cnt = 0;
	for (int i=l[x]; i; i=qn[i]){
		if (qd[i]!=y) a[cnt++] = dp[qd[i]];
	}

	sort(a, a+cnt);
	dp[x]=0;
	if (y!=-1) b[x]--;

	for (int i=cnt-1; b[x]>0 && i>=0; i--){
		dp[x] += a[i] + 2;
		b[x]--;
	}

	for (int i=l[x]; i; i=qn[i]){
		if (qd[i]==y) continue;
		int t = min(b[x], b[qd[i]]);
		b[x] -= t;
		b[qd[i]] -= t;
		dp[x] += t*2;
	}

}


