int madd(int a, int b, int c = mod) {
  int res = a + b;
  return (res >= c ? res - c : res);
}
int mminus(int a, int b, int c = mod) {
  int res;
  if (abs(a - b) < c)
    res = a - b;
  else
    res = (a - b) % c;
  return (res < 0 ? res + c : res);
}
int mmul(int a, int b, int c = mod) {
  LL res = (LL)a * b;
  return (res >= c ? res % c : res);
}
int mmuln(int a, int b, int c = mod) {
  LL res = (LL)a * b;
  return ((res % c) + c) % c;
}
LL mmulmod(LL a, LL b, LL m = mod) {
  LL q = (LL)(((LDB)a * (LDB)b) / (LDB)m);
  LL r = a * b - q * m;
  if (r > m)
    r %= m;
  if (r < 0)
    r += m;
  return r;
}

