const int maxn = 2100;

int n, k;
int a[maxn];
int dp[maxn];
unsigned int delta[maxn][maxn];

inline int solve(unsigned int limit)
{
    for (int i = 0; i < n; i++)
    {
        dp[i] = i;
        unsigned int cur = limit;
        for (int j = i - 1; j >= 0; j--)
        {
            if (delta[i][j] <= cur && dp[i] > dp[j] + i - j - 1)
                dp[i] = dp[j] + i - j - 1;
            if (cur < 2000000000U)
                cur += limit;
        }
        if (dp[i] + n - i - 1 <= k)
            return 1;
    }
    return 0;
}

