    for (int i = 0; i < n; i++)
        cin >> a[i];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < i; j++)
            delta[i][j] = abs(a[i] - a[j]);
    unsigned int l = 0, r = 2000000000;
    while (l < r)
    {
        unsigned int c = (l + r) / 2;
        if (solve(c))
            r = c;
        else
            l = c + 1;
    }
    cout << l;
    return 0;
}

