long long s[100001];

long long f(int l,int r){
    if (l==0) return s[r];
    else return s[r]-s[l-1];
}

int main(){

    int n,m;
    //cin>>n>>m;
    scanf("%d%d",&n,&m);
    m++;
    a[0]=MP(0,0);
    for (int i=1; i<m; i++){
        int x,y;
        scanf("%d%d",&x,&y);
        a[i]=MP(y,x);
    }

    sort(a,a+m);

    if (a[m-1].first!=n){
        cout<<0<<endl;
        return 0;
    }

    d[0]=s[0]=1;

    int p=0;

    for (int i=1; i<m; i++){

        if (a[i].first!=a[i-1].first) p=i;

        int l=-1,r=i;

        int X=a[i].second;

        while(r-l>1){
            int m=(r+l)/2;
            if (a[m].first<X) l=m;
            else r=m;
        }

        if (r>=p){
            s[i]=s[i-1];
            d[i]=0;
            continue;
        }


        long long S=((f(r,p-1)%mod)+mod)%mod;
        d[i]=S;
        s[i]=((s[i-1]+S)%mod);


    }

    long long res=0;
    for (int i=0; i<m; i++){
        if (a[i].first==n) res+=d[i];
        res%=mod;
    }

    cout<<res<<endl;

    return 0;

}

