using namespace std;

typedef long long LL;

const int N = 2003;

int n, mod, f[N][N], g[N][N], C[N][N], pre[N], suf[N], h[N], ans[N];

vector<int> E[N];

void dfs(int x, int fa){

	for(int i = 0;i < E[x].size();++ i)

		if(E[x][i] == fa){E[x].erase(E[x].begin() + i); break;}

	for(int v : E[x]) dfs(v, x);

	int len = E[x].size(); memset(h, 0, len << 2);

	for(int i = 0;i < n;++ i){

		pre[0] = suf[len] = 1;

		for(int j = 0;j < len;++ j) pre[j + 1] = (LL)pre[j] * g[E[x][j]][i] % mod;

		for(int j = len - 1;j >= 0;-- j) suf[j] = (LL)suf[j + 1] * g[E[x][j]][i] % mod;

		f[x][i] = suf[0];

		for(int j = 0;j < len;++ j){

			f[x][i] = (f[x][i] + (LL)h[j] * f[E[x][j]][i]) % mod;

			h[j] = (h[j] + (LL)pre[j] * suf[j + 1]) % mod;

		}

	}

	g[x][0] = f[x][0];

	for(int i = 1;i < n;++ i)

		if((g[x][i] = f[x][i] + g[x][i - 1]) >= mod) g[x][i] -= mod;

}

int main(){

	ios::sync_with_stdio(0);

	cin >> n >> mod;

	for(int i = 1, u, v;i < n;++ i){

		cin >> u >> v;

		E[u].push_back(v); E[v].push_back(u);

	}

	for(int i = 1;i < n;++ i) ans[i] = 1;

	for(int v : E[1]){

		dfs(v, 1);

		for(int i = 1;i < n;++ i)

			ans[i] = (LL)ans[i] * g[v][i - 1] % mod;

	}

	for(int i = 0;i < n;++ i)

		for(int j = *C[i] = 1;j <= i;++ j)

			if((C[i][j] = C[i - 1][j] + C[i - 1][j - 1]) >= mod) C[i][j] -= mod;

	for(int i = n - 1;i;-- i){

		for(int j = i - 2;j > 0;j -= 2) ans[i] = (ans[i] + (LL)ans[j] * C[i][j]) % mod;

		for(int j = i - 1;j > 0;j -= 2) if((ans[i] -= (LL)ans[j] * C[i][j] % mod) < 0) ans[i] += mod;

	}

	for(int i = 1;i < n;++ i) cout << ans[i] << ' ';

	cout << '\n';

}

