void z_function(string &s, int *z) {
    int n = sz(s);
    int l = 0, r = -1;
    rep(i, 1, n) {
        z[i] = 0;
        if (i < r) {
            z[i] = min(r - i, z[i - l]);
        }
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
}

bool check(string &s, int p) {
    if (s[p] == '0' && s[p - 1] == '0' && s[p - 2] == '1' && s[p - 3] == '1') {
        return false;
    }
    if (s[p] == '0' && s[p - 1] == '1' && s[p - 2] == '0' && s[p - 3] == '1') {
        return false;
    }
    if (s[p] == '1' && s[p - 1] == '1' && s[p - 2] == '1' && s[p - 3] == '0') {
        return false;
    }
    if (s[p] == '1' && s[p - 1] == '1' && s[p - 2] == '1' && s[p - 3] == '1') {
        return false;
    }
    return true;
    //0011», «0101», «1110» и «1111
}

int z[N];
int dp[N + 1];

int solve(string s) {
    int n = sz(s);
    reverse(s.begin(), s.end());
    z_function(s, z);
    int b = 0;
    rep(i, 0, n) {
        setmax(b, z[i]);
    }
    //cout << "! " << b << endl;
    dp[0] = 1;
    rep(i, 1, n + 1) {
        dp[i] = 0;
        if (i >= 1) {
            add(dp[i], dp[i - 1]);
        }
        if (i >= 2) {
            add(dp[i], dp[i - 2]);
        }
        if (i >= 3) {
            add(dp[i], dp[i - 3]);
        }
        if (i >= 4 && check(s, i - 1)) {
            add(dp[i], dp[i - 4]);
        }
    }
    int res = 0;
    rep(i, b + 1, n + 1) {
        add(res, dp[i]);
    }
    return res;
}

