vi getprod(vi & v){
	if(v.empty()) return {1};
	if(v.size() == 1) return {1, v[0]};
	int mid = (v.size() + 1) >> 1;
	vi lft(v.begin(), v.begin() + mid);
	vi rgt(v.begin() + mid, v.end());
	return mul(getprod(lft), getprod(rgt));
}

