using namespace std;
const int INF= 1e9;
const int N = 6e3 + 100;
struct edge { int f, c, to, r;};
vector<edge> G[N];
int S, T, prv[N], prp[N], cur[N], vst[N];
int d[N];
bool fst = true;
bool SPFA(int S) {
	if (fst) {
		d[S] = 0;
		for (int i = 1; i <= T; ++ i) {
			d[i] = INF;
			int cnt = 0;
			for (edge e : G[i]) {
				if (!e.f) {
					if (d[e.to] - e.c < d[i]) {
						d[i] = d[e.to] - e.c;
						prv[i] = e.to;
						prp[i] = cnt;
					}
				}
				cnt ++;
			}
			//printf("d[%d]=%d---\n", i, d[i]);
		}
		fst = 0;
		return d[T] != INF;
	} else {
		fill(d, d + 1 + T, INF);
		priority_queue<pair<int, int>> pq;
		pq.push({0, S});
		d[S] = 0;
		while (1) {
			while (!pq.empty() && -pq.top().first != d[pq.top().second]) pq.pop();
			if (pq.empty()) break;
			int v = pq.top().second; pq.pop();
			int cnt = 0;
			for (edge e : G[v]) {
				if (e.f && d[e.to] > d[v] + e.c) {
					d[e.to] = d[v] + e.c; prv[e.to] = v;
					prp[e.to] = cnt; pq.push({-d[e.to], e.to});
				}
				cnt ++;
			}
		}
		return d[T] != INF;
	}
}
int aug(int v, int flow) {
	if (v == T) return flow;
	vst[v] = 1; int flow1 = flow;
	for (int &i = cur[v]; i < (int) G[v].size(); ++ i) {
		edge &e = G[v][i];
		if (e.f && d[v] + e.c == d[e.to] && !vst[e.to]) {
			int flow1 = aug(e.to, min(flow, e.f));
			flow -= flow1; e.f -= flow1;
			G[e.to][e.r].f += flow1;
		}
		if (flow == 0) {
			vst[v] = 0; return flow1 - flow;
		}
	}
	return flow1 - flow;
}
int mcmf() {
	int ans = 0, sT = 0;
	while (SPFA(S)) {
		sT += d[T];
		for (int i = 0; i <= T; ++ i) cur[i] = 0, vst[i] = 0;
		ans += sT * aug(S, INF);
		/*int f = INF;
		for (int v = T; v != S; v = prv[v]) {
			int u = prv[v];
			int j = prp[v];
			printf("%d\n", v);
			f = min(f, G[u][j].f);
		}
		for (int v = T; v != S; v = prv[v]) {
			int u = prv[v];
			int j = prp[v];
			G[u][j].f -= f;
			G[v][G[u][j].r].f += f;
		}
		sT += d[T];
		printf("f=%d  d[T]=%d\n", f, d[T]);
		ans += f * sT;*/
		for (int i = 0; i <= T; ++ i) {
			for (auto &e : G[i]) {
				e.c += d[i] - d[e.to];
			}
		}
	}
	return ans;
}
void ae(int u, int v, int f, int c) {
	G[u].push_back((edge) {f, c, v, (int) G[v].size()});
	G[v].push_back((edge) {0, -c, u, (int) G[u].size() - 1});
}
