const int N = 100005;
int D[N];
void calcPrimes(int n = N) {
	for (int i = 2; i * i < n; ++i) {
		if (D[i]) {
			continue;
		}
		for (int j = i * i; j < n; j += i) {
			D[j] = i;
		}
	}
}
bool isPrime(int x) {
	return x > 1 && D[x] == 0;
}
void factor(int n, vector<int> &v) {
	v.clear();
	while (n > 1) {
		if (!D[n]) {
			v.PB(n);
			break;
		}
		v.PB(D[n]);
		n /= D[n];
	}
	UNIQUE(v);
}

