double solve(int x, int y)

{

    if (x == 0)

        return 0;

    if (dp[x][y] != (double) -1)

        return dp[x][y];

    // take right

    double maxi = ((double)(x)/(x+y));

    double maxi3=0, maxi2=0;

    // take wrong

    if (y > 2)

        maxi2 = ((double)(y)/(x+y)) * ((double)(y-1)/(x+y-1)) * ((double)(y-2)/(x+y-2)) * solve(x,y-3);

    if (y > 1 && x > 0)

        maxi3 = ((double)(y)/(x+y)) * ((double)(y-1)/(x+y-1)) * ((double)(x)/(x+y-2)) * solve(x-1,y-2);



    return dp[x][y] = maxi + maxi2 + maxi3;

}



