struct Node {
    using T = int;
    T unit = INT_MAX;
    T f(T a, T b) {
        return min(a, b);
    }

    Node *l = 0, *r = 0;
    int lo, hi;
    int madd = 0;
    T val = 0;
    Node(int _lo,int _hi):lo(_lo),hi(_hi){ }
    T query(int L, int R) {
        if (R <= lo || hi <= L) return unit;
        if (L <= lo && hi <= R) return val;
        push();
        return f(l->query(L, R), r->query(L, R));
    }
    void add(int L, int R, int x) {
        if (R <= lo || hi <= L) return;
        if (L <= lo && hi <= R) {
            madd += x;
            val += x;
        }
        else {
            push(), l->add(L, R, x), r->add(L, R, x);
            val = f(l->val, r->val);
        }
    }
    int fzero(int L, int R) {
        if (val) return -1;
        if (lo >= R or L >= hi) return -1;
        if (lo+1 == hi) return lo;
        push();
        int res = l->fzero(L, R);
        if (res == -1) res = r->fzero(L, R);
        return res;
    }
    void push() {
        if (!l) {
            int mid = lo + (hi - lo)/2;
            l = new Node(lo, mid); r = new Node(mid, hi);
        }
        if (madd)
            l->add(lo,hi,madd), r->add(lo,hi,madd), madd = 0;
    }
};

int main()
{
    ios::sync_with_stdio(false); cin.tie(0);

    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        vector<int> a(n);
        for (int &x : a) cin >> x;

        vector pos(n+1, vector<int>());
        for (int i = 0; i < n; ++i) pos[a[i]].push_back(i);
        for (int i = 1; i <= n; ++i) pos[i].push_back(n);
        vector<int> ptr(n+1);

        Node *seg = new Node(0, n);
        for (int i = 1; i <= n; ++i) {
            if (pos[i].size() < 2) continue;
            int L = pos[i][0], R = pos[i][1];
            seg -> add(L, R, 1);
        }

        vector<int> till(n);
        for (int i = 0; i < n; ++i) {
            till[i] = seg -> fzero(i, n);
            if (till[i] == -1) till[i] = n;

            int u = ptr[a[i]];
            int L = pos[a[i]][u], R = pos[a[i]][u+1];
            seg -> add(L, R, -1);
            if (R == n) continue;
            ++ptr[a[i]];
            L = R;
            R = pos[a[i]][u+2];
            seg -> add(L, R, 1);    
        }

        vector<array<int, 2>> sorted;
        for (int i = 0; i < n; ++i)
            sorted.push_back({till[i], i});
        sort(begin(sorted), end(sorted));
        int ans = 0, reach = -1;
        for (auto [x, i] : sorted) {
            if (x == n) break;
            if (i <= reach) continue;
            ++ans;
            reach = x;
        }
        cout << ans << '\n';
    }
}

