    int m = (l + r)/2;
    init(i*2, l, m);
    init(i*2+1, m+1, r);
    T[i] = min(T[i*2], T[i*2+1]);
}

void upd(int i, int l, int r, int id, ll x) {
    if(l == r) {
        T[i] = x;
        return;
    }
    int m = (l + r)/2;
    if(id <= m) upd(i*2, l, m, id, x);
    else upd(i*2+1, m+1, r, id, x);

    T[i] = min(T[i*2], T[i*2+1]);
}

ll q(int i, int l, int r, int s, int e) {
    if(e < s) return n+1;
    if(e < l || r < s) return n+1;
    if(s <= l && r <= e) return T[i];
    int m = (l + r)/2;
    return min(q(i*2, l, m, s, e), q(i*2+1, m+1, r, s, e));
}

ll L[300002], R[300002];

void solve() {
    cin >> n;
    for(int i=1;i<=n;i++) cin >> a[i];
    vector<int> v;
    for(int i=1;i<=n;i++) v.push_back(a[i]);
    sort(v.begin(), v.end());
    for(int i=1;i<=n;i++) a[i] = lower_bound(v.begin(), v.end(), a[i]) - v.begin() + 1;

    for(int i=1;i<=n;i++) inv[a[i]] = i;

    init(1, 1, n);
    ll ans = 0;
    for(ll i=1;i<=n;i++) {
        ans += (i-1) * (n-i+1);
    }

    //cout << q(1, 1, n, 1, n).first << " " << q(1, 1, n, 1, n).second << "\n";

    stack<int> st;
    a[0] = INF;
    st.push(0);
    for(int i=1;i<=n;i++) {
        while(a[i] > a[st.top()]) st.pop();
        L[i] = st.top() + 1;
        st.push(i);
    }
    while(!st.empty()) st.pop();

    a[n+1] = INF;
    st.push(n+1);
    for(int i=n;i>=1;i--) {
        while(a[i] > a[st.top()]) st.pop();
        R[i] = st.top() - 1;
        st.push(i);
    }

    vector<int> V(n);
    for(int i=0;i<n;i++) V[i] = i+1;

    sort(V.begin(), V.end(), [](int a, int b){
        return R[a] > R[b];
    });

    int now = n;
    for(int j=0;j<n;j++) {

        int i = V[j];
        while(now > R[i]) {
            upd(1, 1, n, a[now], now);
            now--;
        }
        ll R2 = q(1, 1, n, 1, a[i]-1) - 1;

       // cout << L[i] << " " << R[i] << " " << R2 << "\n";

        ans -= (i - L[i] + 1) * (R2 - R[i]);
    }

    cout << ans << "\n";
}

int main()
{
    ios::sync_with_stdio(false); cin.tie(NULL);
    int t; cin >> t;
    while(t--) solve();
}

