				continue;
			}
			if(sz == 1){
				P[l][r] = dp[l][r] = adj[l][r];
				continue;
			}
			if(adj[l][r]){
				for(int j=l;j<r;++j){
					P[l][r] += 1ll * dp[l][j] * dp[j+1][r] % MOD;
