uint gcd(uint a, uint b) {
	return a ? gcd(b % a, a) : b;
}

uint n, p, q;
uint tmp[256] = {0U}, binom[256] = {0U};

int main() {
	cin >> n >> p >> q;
	p = min(p, n - 1U);

	// compute binom
	for (uint i = 0U; i < p; i++)
		tmp[i] = n - i;

	binom[0] = 1U;
	for (uint i = 1U; i <= p; i++) {
		uint v = i;

		for (uint j = 0U; j < i; j++) {
			uint d = gcd(tmp[j], v);
			tmp[j] /= d;
			v /= d;
		}
		assert(v == 1U);

		binom[i] = 1U;
		for (uint j = 0U; j < i; j++)
			binom[i] *= tmp[j];
	}

	uint ans = 0U;
	for (uint j = 1U; j <= q; j++) {
		uint ub = (j & 1U) ? p : 31;
		uint pow = 1U, value = 0U;

		for (uint k = 0U; k <= ub; k++) {
			value += binom[k] * pow;
			pow *= j;
		}

		ans ^= (j * value);
	}

	cout << ans << endl;

	return 0;
}

