		int q = g[cnt - 1][(i + 1) % sz(g[cnt - 1])];
		int x = f[p] + n - dist2(p, q);
		int y = f[q] + n - dist2(p, q);
		if (ans > x) {
			ans = x;
			r1 = p;
			r2 = q;
			dir = 1;
		}
		if (ans > y) {
			ans = y;
			r1 = q;
			r2 = p;
			dir = -1;
		}
