		pair<pi, int> p = rb[r1];
		r1 = p.fi.fi;
		r2 = p.fi.se;
		dir = p.se;
	}
	res.pb(r2); reverse(all(res));
	FOR(i, 0, sz(res) - 1) {
		if (res[i] <= res[i + 1] && res[i + 1] - res[i] == dist(res[i], res[i + 1])) printf("+");
