int main() {
	cin >> t >> l >> r;
	f[0]=f[1]=0;
	for (int i=2;i<=MaxN;++i) {
		if (!f[i]) {
			f[i]=(LL)i*(i-1)/2;
			prime[++tot]=i;
		}
		for (int j=1;j<=tot && i*prime[j]<=MaxN;j++) {
			//if (!f[i*prime[j]] || f[i]+f[prime[j]]*i<f[i*prime[j]])
			//	f[i*prime[j]]=f[i]+f[prime[j]]*i;
			f[i*prime[j]]=f[i]+f[prime[j]]*i;
