string n;
bigint B;

mi dp(string x, int a, int b, vpi v) {
	// ps("WUT",x,a,b,v);
	array<map<pair<pi,int>,mi>,3> dp;
	dp[1][{{0,0},0}] = 1;
	reverse(all(x)); x += '0';
	F0R(i,sz(x)) {
		array<map<pair<pi,int>,mi>,3> DP;
		F0R(q,10) F0R(j,3) {
			int ind = MOD;
			if (q > x[i]-'0') ind = 2;
			else if (q == x[i]-'0') ind = j;
			else ind = 0;
			trav(t,dp[j]) {
				int A = t.f.f.f+q*a;
				int B = t.f.f.s+q*b;
				int cur = t.f.s;
				F0R(z,sz(v)) {
					if (cur == -1) break;
					if (A%10 == v[z].f) cur |= 1<<(2*z);
					if (B%10 == v[z].s) cur |= 1<<(2*z+1);
					if (((cur>>(2*z))&3) == 3) cur = -1;
				}
				DP[ind][{{A/10,B/10},cur}] += t.s;
			}
		}
		swap(dp,DP);
	}
	mi ans = 0;
	trav(t,dp[1]) {
		assert(t.f.f == mp(0,0));
		if (t.f.s == -1) ans += t.s;
	}
	trav(t,dp[0]) {
		assert(t.f.f == mp(0,0));
		if (t.f.s == -1) ans += t.s;
	}
	// ps("HA",ans); exit(0);
	return ans;
}

mi solve(int a, int b) {
	if (a == b) return B%MOD;
	vpi v;
	for (int i = 1; i*b < 10; i++) v.pb({a*i,b*i});
	auto mx = B/b;
	return dp(str(mx),a,b,v);
}

int main() {
    setIO(); re(n); B = bigint(n);
	mi ans = 0;
    FOR(i,1,10) FOR(j,i,10) if (__gcd(i,j) == 1) {
    	// ps("??",i,j);
    	mi z = solve(i,j);
    	if (i != j) ans += 2*z;
    	else ans += z;
    	// ps("HUH",i,j,ans);
    }
    ps(ans);
}

