const int64_t mod = 998244353;

int64_t bp(int64_t a, int64_t n) {
    int64_t ans = 1;
    while (n) {
        if (n & 1) ans = ans * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    int n; cin >> n;
    vector <int64_t> fib(n + 1);
    fib[0] = 0; fib[1] = 1;
    for (int i = 2; i <= n; i++) fib[i] = (fib[i - 1] + fib[i - 2]) % mod;
    cout << fib[n] * bp(bp(2, n), mod - 2) % mod << '\n';
    return 0;
}

