ll dp[mx][mx], fact[mx], tcaf[mx], inv[mx];

void precomp (int n) {
    fact[0]=tcaf[0]=fact[1]=tcaf[1]=inv[1]=1;
    for (int i = 2; i <= n; ++i) {
        fact[i] = (i*fact[i-1])%mod;
        inv[i] = mod-mod/i*inv[mod%i]%mod;
        tcaf[i] = (inv[i]*tcaf[i-1])%mod;
    }
}


long long nCk (long long n, long long k) {
    if (k>n || k < 0) return 0;
    return fact[n]*tcaf[n-k]%mod*tcaf[k]%mod;
}

ll calc (ll n, ll x) {
    if (dp[n][x]) return dp[n][x];

    ll res = 1;
    rep (i,1,n) res = (res*min(n-1,x))%mod;

    if (x>n-1) {
        ll mult = 1;
        rep (i,0,n-2) {
            res = (res+mult*calc(n-i, x-n+1)%mod*nCk(n,i))%mod;
            mult = (mult*(n-1))%mod;
        }
    }

    dp[n][x] = res;
    return res;
}


