typedef long long ll;
using namespace std;

const ll MAX = 400007, MOD = 998244353;
ll P[MAX], Q[MAX];
//double L2[MAX];

struct BIT {
	ll T[MAX];
	void Clear(int i) {
		for (; i < MAX; i += i & -i) T[i] = 0;
	}
	void Update(int i, int v) {
		for (; i < MAX; i += i & -i) T[i] += v;
	}
	ll Query(ll L, ll R) {
		L = min(L, MAX - 1); R = min(R, MAX - 1);
		ll ret = 0; L--;
		L = max(L, 0LL); R = max(R, 0LL);
		for (; R; R -= R & -R) ret += T[R];
		for (; L; L -= L & -L) ret -= T[L];
		return ret;
	}
} T, T2;

int main() {
	//for (int i = 1; i < MAX; ++i) L2[i] = log2(i);

	ios::sync_with_stdio(0); cin.tie(0);
	int _T;
	cin >> _T;
	while (_T--) {
		ll N, K, ans = 0, inv = 0;
		cin >> N >> K;
		for (int i = 1; i <= N; ++i) cin >> P[i];
		for (int i = 0; i < K; ++i) {
			cin >> Q[i];
			Q[i]++;
			inv += T.Query(Q[i] + 1, MAX - 1);
			inv %= MOD;
			T.Update(Q[i], 1);
		}

		ans += inv * N;
		ans %= MOD;

		for (int i = N; i > 0; --i) {
			ll n = P[i], l = n, r = 2 * n - 1;
			ll t = K * (K - 1) / 2LL, p = K - 1;

			// Bigger than P[i]
			while (l < 2 * N) {
				ll s = T2.Query(l, r);
				ans += s * (t % MOD);
				ans %= MOD;

				l *= 2LL;
				r = 2 * l - 1;
				if (p) {
					t -= p;
					p--;
				}
			}

			// Smaller than P[i]
			t = K * (K + 1) / 2LL, p = K - 1;
			r = n, l = (r + 2) / 2LL;
			while (r) {
				ll s = T2.Query(l, r);
				ans += s * (t % MOD);
				ans %= MOD;

				r /= 2LL;
				l = (r + 2) / 2LL;
				if (p) {
					t += p;
					p--;
				}
			}

			T2.Update(P[i], 1);
		}

		cout << ans << '\n';
		for (int i = 1; i <= K; ++i) T.Clear(i);
		for (int i = 1; i <= N * 2; ++i) T2.Clear(i);
	}
	return 0;
}

