                        f[r] += p;
                    }
                }
            }
        }
        for (int i = 1; i < f.size(); i++) {
            f[i] += f[i - 1];
        }
        int pw = 1;
        auto ndp = dp;
        for (int i = 0; i < f.size() && pw <= f.back(); i++) {
            if (f[i] - pw > 0) {
                assert(1 <= i && i <= 12);
                for (int s = 0; s < (1 << 12); s++) {
                    if (s >> (i - 1) & 1) {
                        ndp[s] = std::max(ndp[s], dp[s ^ (1 << (i - 1))] + f[i] - pw);
                    }
                }
            }
            pw *= 3;
        }
        dp = std::move(ndp);
    }

    std::cout << dp.back() << "\n";
}

