ll pkt(ll a, ll b) {
 ll ret = 1;
 ll base = a;
 while (b) {
  if (b&1) ret = ret*base%MOD;
  base = base*base%MOD;
  b >>= 1;
 }
 return ret;
}

ll hitung(ll x) {
 ll cnt = 0;
 while (x != 1) {
  x = __builtin_popcount(x);
  cnt++;
 }
 return cnt;
}

