void Swap_(vector<int> &a, vector<int> &b, vector<pii> &ans, int l1, int l2) {
  if (a.empty()) a.push_back(0);
  if (b.empty()) b.push_back(0);
  vector<int> c, d;
  for (int i = 0; i < l1; ++i) {
    c.push_back(a.back());
    a.pop_back();
  }
  for (int i = 0; i < l2; ++i) {
    d.push_back(b.back());
    b.pop_back();
  }
  ans.push_back({a.back(), b.back()});
  int ab = a.back(), bb = b.back();
  for (int i = 0; i < l1; ++i) {
    c[i] -= ab;
  }
  for (int i = 0; i < l2; ++i) {
    d[i] -= bb;
  }
  a.pop_back();
  b.pop_back();
  swap(a, b);
  while (c.size()) {
    a.push_back(c.back() + bb);
    c.pop_back();
  }
  while (d.size()) {
    b.push_back(d.back() + ab);
    d.pop_back();
  }
}

#define Swap(i, j) Swap_(a, b, ans, i, j)

vector<pii> Solve(void) {
  vector<pii> ans;
  vector<int> a, b;
  s[n] = 'a';
  t[m] = 'b';
  for (int i = 0; i < n; ++i) {
    if (s[i] != s[i + 1]) a.push_back(i + 1);
  }
  for (int i = 0; i < m; ++i) {
    if (t[i] != t[i + 1]) b.push_back(i + 1);
  }

  while (true) {
    if (a.size() >= 2 && b.size() >= 2) {
      Swap(0, 0);
    } else if (a.size() >= 2) {
      if (a.size() >= 3) {
        Swap(2, 0);
      } else {
        Swap(0, 0);
      }
    } else if (b.size() >= 2) {
      if (b.size() >= 3) {
        Swap(0, 2);
      } else {
        Swap(0, 0);
      }
    } else {
      if (a.empty() && b.empty()) {
        break;
      } else {
        Swap(0, 0);
      }
    }
  }

  return ans;
}

