// O(N * log(N))

// beautiful
// max flow = min cut, which is "discrete" (take or don't take rather than how much flow)

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 5e5 + 1;

long long t[4*MAXN][2][2];

int n, q;
long long a[MAXN], b[MAXN], c[MAXN];

void update(int i, int v=1, int tl=1, int tr=n) {
    if (tl == tr) {
        t[v][0][0] = a[i];
        t[v][1][1] = b[i];
    }
    else {
        int tm = (tl + tr) / 2;

        if (i <= tm) {
            update(i, 2*v, tl, tm);
        }
        else {
            update(i, 2*v+1, tm+1, tr);
        }

        for (int j = 0; j < 2; j++) {
            for (int k = 0; k < 2; k++) {
                t[v][j][k] = 1e18;
                for (int m1 = 0; m1 < 2; m1++)
                    for (int m2 = 0; m2 < 2; m2++) {
                        t[v][j][k] = min(t[v][j][k],
                                         t[2 * v][j][m1] + t[2 * v + 1][m2][k]
                                         + c[tm] * (m1 == 1 and m2 == 0));
                    }
            }
        }
    }
}

int main() {
    cin.tie(0)->sync_with_stdio(0);

    memset(t, 0x1f, sizeof(t));

    cin >> n >> q;

    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    for (int i = 1; i <= n; i++) {
        cin >> b[i];
    }
    for (int i = 1; i < n; i++) {
        cin >> c[i];
    }

    for (int i = 1; i <= n; i++) {
        update(i);
    }

    while (q--) {
        long long p, x, y, z; cin >> p >> x >> y >> z;

        a[p] = x;
        b[p] = y;
        c[p] = z;
        update(p);

        cout << min({t[1][0][0], t[1][0][1], t[1][1][0], t[1][1][1]}) << '\n';
    }
}

