					dp[i + 1][nm][nf] = max(dp[i + 1][nm][nf], w);
				}
			}
	int ans = -INF;
	for (int x = 0; x < K; x++)
		for (int f = 0; f < 2; f++)
			ans = max(ans, dp[n][x][f]);
