#define MAXN 200010
using namespace std;
int n;
int dep[MAXN],fa[MAXN],seq[MAXN];
int cover[MAXN];
int head[MAXN],tot;
struct edge {
	int next,to;
} e[MAXN<<1];
inline void addEdge(int u,int v) {
	e[++tot]=(edge){head[u],v};
	head[u]=tot;
}
void bfs() {
	int ord=1;
	queue<int> q;
	q.push(1);
	seq[1]=1;
	dep[1]=1;
	while (!q.empty()) {
		int u=q.front();
		q.pop();
		for (register int i=head[u];i;i=e[i].next) {
			int v=e[i].to;
			if (v!=fa[u]) {
				fa[v]=u;
				dep[v]=dep[u]+1;
				seq[++ord]=v;
				q.push(v);
			}
		}
	}
}
int main() {
	scanf("%d",&n);
	for (int i=1;i<n;i++) {
		int u,v;
		scanf("%d%d",&u,&v);
		addEdge(u,v);
		addEdge(v,u);
	}
	bfs();
	int ans=0;
	for (int i=n;i>=1;i--) {
		if (cover[seq[i]]) continue;
		if (dep[seq[i]]<=3) break;
		cover[fa[seq[i]]]=true;
		//printf("find %d  %d\n",seq[i],fa[seq[i]]);
		for (int j=head[fa[seq[i]]];j;j=e[j].next) {
			int v=e[j].to;
			cover[v]=true;
		}
		ans++;
	}
	printf("%d\n",ans);
	return 0;
}

