		memset(F, 0, sizeof(F));
		for(int i = 1; i <= f[x]; i++)
			for(int j = c[x]; j >= 0; j--)
				for(int t = 0; t <= j && t <= k ; t++)
					F[j] = max(F[j], F[j - t] + h[t]);
		int	cnt = 0;
		for(int i = 0; i <= c[x]; i++)
			cnt = max(cnt, F[i]);
		ans += cnt;
	}
	printf("%d\n", ans);
	return 0;
}

