int solve(int n, long long l, long long r, vector<long long>& a) {
    int max_wins = 0;
    long long sum = 0;
    int left = 0;

    for (int right = 0; right < n; right++) {
        sum += a[right];
        while (sum > r) {
            sum -= a[left];
            left++;
        }
        if (sum >= l) {
            max_wins++;
            sum = 0;
            left = right + 1;
        }
    }

    return max_wins;
}

