template <typename T>
inline void writeVector(const std::vector<T> &vec, const std::string& sep, const std::string& end) {
    bool isFirst = true;
    for (const T &elem : vec) {
        if (!isFirst) {
            write(sep);
        }
        write(elem);
        isFirst = false;
    }
    write(end);
}

template <typename ...Types>
inline void writeln(const Types &...tail) {
    write(tail...);
    write('\n');
}

