vector <vector<long long>  >  mult (vector <vector<long long>  > a, vector <vector<long long>  > b)
{
    vector <vector<long long>  > c = {};
    vector <long long> temp  = {0,0,0};
    for(int i = 0; i < 3; i++)
        c.push_back(temp);
    for(int  i = 0; i < 3; i++)
    {
        for(int  j = 0; j < 3; j++)
        {
            for(int  k = 0; k < 3; k++)
            {
                c[i][k] += ( (a[i][j]*b[j][k]) % degMOD );
                c[i][k] %= degMOD;
            }
        }
    }
    return c;
}

vector <vector<long long>  > binpowM (vector <vector<long long>  > a, long long  n) {
	if (n == 0)
		return Id;
	if (n % 2 == 1)
		return mult(binpowM (a, n-1), a);
	else {
		auto b = binpowM (a, n/2);
		return mult(b , b);
	}
}



