struct Ec
{
    int a; ll b;
    ll operator() (int x)
    {
        return (ll) a * x + b;
    }
};
Ec interv[Nmax];

class Batch
{
    vector<Ec> v;

    double intersect(Ec A, Ec B)
    {
        return (double) (A.b - B.b) / (B.a - A.a);
    }

    bool bad(Ec a, Ec b, Ec c)
    {
        return intersect(a, c) >= intersect(a, b);
    }

public:
    void clear()
    {
        v.clear();/// v.shrink_to_fit();
    }

    void add(Ec ec)
    {
      //  for(auto it : v) cerr << it.a << ' ' << it.b << ' '; cerr << '\n';

        while(v.size() >= 2 && bad(v[v.size()-2], v.back(), ec)) v.pop_back();
        v.push_back(ec);

     //   cerr << v.size() << "@\n";
       // for(auto it : v) cerr << it.a << ' ' << it.b << ' '; cerr << '\n';
    }

    ll query(int x)
    {
        if(v.empty()) return inf;

      //  cerr << x << '\n';
     //   for(auto it : v) cerr << it.a << ' ' << it.b << ' '; cerr << '\n';
    //    int i;
      //  for(i=0; i<v.size()-1; ++i) cerr << intersect(v[i], v[i+1]) << ' '; cerr << "#\n";

        while(v.size() >= 2 && intersect(v[v.size()-2], v.back()) <= x) v.pop_back();
        return v.back()(x);
    }
};


class SegmentTree
{
    Batch a[Nmax<<2];
public:
    void update1(int node, int st, int dr, int pos, Ec ec)
    {
        a[node].add(ec);
        if(st == dr) return;

        if(pos <= mid) update1(left_son, st, mid, pos, ec);
            else update1(right_son, mid+1, dr, pos, ec);
    }

    void update2(int node, int st, int dr, int L, int R, Ec ec)
    {
        if(L <= st && dr <= R)
        {
            a[node].add(ec);
            return;
        }

        if(L <= mid) update2(left_son, st, mid, L, R, ec);
        if(mid < R) update2(right_son, mid+1, dr, L, R, ec);
    }

    ll query1(int node, int st, int dr, int L, int R, int p)
    {
        if(L <= st && dr <= R) return a[node].query(p);

        ll x = inf, y = inf;
        if(L <= mid) x = query1(left_son, st, mid, L, R, p);
        if(mid < R) y = query1(right_son, mid+1, dr, L, R, p);
        return min(x, y);
    }

    ll query2(int node, int st, int dr, int pos, int p)
    {
        ll x = a[node].query(p);
        if(st == dr) return x;

        if(pos <= mid) x = min(x, query2(left_son, st, mid, pos, p));
            else x = min(x, query2(right_son, mid+1, dr, pos, p));
        return x;
    }

    void clear()
    {
        int i;
        for(i=1; i<=((n+1)<<2); ++i) a[i].clear();
    }

} aint;

void solve()
{
    int i;

    aint.clear();
    for(i=n; i>=0; --i)
        aint.update1(1, 0, n, i, {-i, old[i]});

    nr = 0; st[0] = 0;
    for(i=1; i<=n; ++i)
    {
        while(nr && A[i] >= A[st[nr]]) --nr;
        st[++nr] = i;
        interv[i] = {A[i], aint.query1(1, 0, n, st[nr-1], st[nr] - 1, A[i])};
    }

    aint.clear();
    for(i=n; i>=1; --i)
        aint.update2(1, 0, n, i, nextBigger[i] - 1, interv[i]);

    for(i=1; i<=n; ++i)
        dp[i] = aint.query2(1, 0, n, i, i);
}

int main()
{
    int i, j;
    cin >> n >> k;
    for(i=1; i<=n; ++i) cin >> A[i];

    nr = 0; st[0] = n+1;
    for(i=n; i; --i)
    {
        while(nr && A[i] > A[st[nr]]) --nr;
        nextBigger[i] = st[nr];
        st[++nr] = i;
    }

    old[0] = 0;
    for(i=1; i<=n; ++i) old[i] = inf;

    for(i=1; i<=k; ++i)
    {
        for(j=1; j<=n; ++j) dp[j] = inf; dp[0] = 0;
        solve();
        for(j=1; j<=n; ++j) old[j] = dp[j];
    }

    cout << dp[n] << '\n';
    return 0;
}

