    for (int d = 2; d <= 16; ++d) {
        static int dp[SIZE];
        static int a0[MAXN];
        int bnd = 0, bndlen;

        for (int i = 0; i < N; ++i) {
            int x = 0, base = 1, t = i, len = 0;
            do {
                x += t % d * base;
                t /= d;
                base *= d + 1;
                ++len;
            } while (t > 0);

            // printf("i=%d, x=%d\n", i, x);

            a0[i] = x;
            if (chkmax(bnd, base))
                bndlen = len;
        }

        // printf("bnd=%d, bndlen=%d\n", bnd, bndlen);

        static int pos[SIZE];

        memset(pos, -1, sizeof(*pos) * bnd);

        for (int i = 0; i < bnd; ++i) {
            int t = i, base = 1;
            do {
                t /= d + 1;
                base *= d + 1;
            } while (t > 0);

            for (t = i; base > 1; t %= base) {
                base /= d + 1;
                int x = t / base;
                if (x == d) {
                    pos[i] = base;
                    break;
                }
            }
        }

        static int tgt[MAXM];

        std::fill(tgt + 1, tgt + M + 1, -1);

        for (int i = 1; i <= M; ++i) {
            if (D[i] == d) {
                int p = L[i];
                for (; p > bndlen; --p) {
                    if (S[i][p] != d && S[i][p] != 0)
                        goto LOOP_END;
                }
                int t = 0;
                for (int j = p; j >= 1; --j) {
                    t = t * (d + 1) + S[i][j];
                }
                tgt[i] = t;

                // printf("tgt[%d]=%d\n", i, tgt[i]);
            }
          LOOP_END:;
        }

        for (int pid = 0; pid < TOT_PRIMES; ++pid) {
            int P = PRIMES[pid];

            std::fill(dp, dp + bnd, 1);
            for (int i = 0; i < N; ++i) {
                dp[a0[i]] = A[i] % P;
            }

            for (int i = 0; i < bnd; ++i) {
                if (pos[i] != -1) {
                    int base = pos[i];
                    for (int j = 0; j < d; ++j) {
                        (dp[i] *= dp[i - (d - j) * base]) %= P;
                    }
                }
            }

            for (int i = 1; i <= M; ++i) {
                if (ans[i] == -1 && tgt[i] != -1) {
                    if ((dp[tgt[i]] + C[i]) % P == 0)
                        ans[i] = P;
                }
            }
        }
    }

    for (int i = 1; i <= M; ++i) {
        write(ans[i]); putchar('\n');
    }
}

