{
  //  freopen("in.txt", "r", stdin);
    while(cin>>n>>m>>k)
    {
        for(int i=0; i<n; i++)
            for(int j=0; j<m; j++)
            {
                cin>>maz[i][j];
                g[i][j]='.';
            }
        nn=n*m;
        mm=1<<k;
        memset(hash1,0,sizeof(hash1));
        memset(visit,false,sizeof(visit));
        for(int i=0; i<nn; i++)
            for(int j=0; j<mm; j++)
                dp[i][j]=inf;

        for(int i=0,a,b; i<k; i++)
        {
            cin>>a>>b;
            a--,b--;
            int u=a*m+b;
            hash1[u]=1<<i;
            update(u,hash1[u],maz[a][b],-1);
        }
        solve();
    }
}

