		tmp[I][m - 1] = tmp[J][m - 1] + calc(i + 1, m - 1);

		for(int j = m - 2; j >= 0; j --) {

			tmp[I][j] = max(tmp[J][j] + calc(i + 1, j), tmp[I][j + 1] + calc(i, j + 1));

		}

		if(i % B == 0) {

			for(int j = 0; j < m; j ++) g[cnt][j] = tmp[I][j];

