		for(int i = hi - 1; i > lo; i --) {

			f[hi - i][m - 1] = f[hi - i - 1][m - 1] + calc(i + 1, m - 1);

			for(int j = m - 2; j >= 0; j --) {

				f[hi - i][j] = max(f[hi - i][j + 1] + calc(i, j + 1), f[hi - i- 1][j] + calc(i + 1, j));

