ll mod_exp(ll x, ll y, ll mod) {

    ll res = 1;

    while(y > 0) {

        if(y & 1) res = res*x % mod;

        y >>= 1;

        x = x*x % mod;

    }

    return res;

}



ll get(int i, int j, int k) {

  if(j >= 0) return dp[i][j][k];

  return 0;

}



void dfs(int cur, int prev) {

  bool leaf = true;

  for(int c : adj[cur]) {

    if(c == prev) continue;

    leaf = false;

    dfs(c, cur);

    for(int i = 1; i <= b; i++) {

      dp[c][i][0] = (dp[c][i][0] + dp[c][i - 1][0]) % MOD;

      dp[c][i][1] = (dp[c][i][1] + dp[c][i - 1][1]) % MOD;

    }

  }



  if(leaf) {

    dp[cur][b][0] = 1;

    dp[cur][0][1] = 1;

    return;

  }



  dp[cur][b][0] = 1;

  for(int c : adj[cur]) {

    if(c == prev) continue;

    ll mult = (dp[c][b][0] + dp[c][b][1]) % MOD;

    dp[cur][b][0] = (dp[cur][b][0] * mult) % MOD;

  }



  FOR(j,b) {

    ll p1 = 1, p2 = 1;

    for(int c : adj[cur]) {

      if(c == prev) continue;

      ll c1 = (get(c, j - 1, 1) + get(c, j + 1, 0)) % MOD;

      ll c2 = (get(c, j - 1, 1) + get(c, j, 0)) % MOD;

      p1 = (p1 * c1) % MOD;

      p2 = (p2 * c2) % MOD;

    }

    dp[cur][j][0] = (p1 - p2 + MOD) % MOD;

  }



  FOR(j,b) {

    ll p1 = 1, p2 = 1;

    for(int c : adj[cur]) {

      if(c == prev) continue;

      if(j) {

        ll c1 = (get(c, j - 1, 1) + get(c, j, 0)) % MOD;

        ll c2 = (get(c, j - 2, 1) + get(c, j, 0)) % MOD;

        p1 = (p1 * c1) % MOD;

        p2 = (p2 * c2) % MOD;

      }

      else {

        p1 = (p1 * dp[c][0][0]) % MOD;

      }

    }

    dp[cur][j][1] = j ? ((p1 - p2 + MOD) % MOD) : p1;

  }

}



