inline ll quick_pow(ll a,ll b)
{
    ll res=1;
    while(b)
    {
        if(b&1)res=1LL*res*a%mod;
        a=1LL*a*a%mod;
        b>>=1;
    }
    return res;
}
ll fac[MAXM],ifac[MAXM],inv[MAXM],n,tot,E[MAXM],X[MAXM],Y[MAXM],SQ[MAXM];
struct data
{
