    read(r),read(c);
    sort(A+1,A+tot+1);
    fac[0]=ifac[0]=inv[0]=1;
    for(register int i=1;i<=tot;i++)
        fac[i]=1LL*fac[i-1]*i%mod;
    ifac[tot]=quick_pow(fac[tot],mod-2);
    for(register int i=tot-1;i;i--)
        ifac[i]=1LL*ifac[i+1]*(i+1)%mod;
    for(register int i=1;i<=tot;i++)
        inv[i]=1LL*fac[i-1]*ifac[i]%mod;
    int pre=0;
    for(register int i=1;i<=tot;i++)
