       // cout<<A[i].val<<" "<<pre<<endl;
        A[i].E+=(((1LL*A[i].x*A[i].x%mod+1LL*A[i].y*A[i].y%mod)%mod)+
        (1LL*(-2LL*A[i].x%mod*X[pre]%mod-2LL*A[i].y%mod*Y[pre]%mod+SQ[pre])%mod+E[pre])%mod*inv[pre]%mod)%mod;
        X[i]=(X[i-1]+A[i].x)%mod,Y[i]=(Y[i-1]+A[i].y)%mod,
        SQ[i]=(SQ[i-1]+1LL*A[i].x*A[i].x%mod+1LL*A[i].y*A[i].y%mod)%mod;
        if(pre==0)A[i].E=0;
        E[i]=(E[i-1]+A[i].E)%mod;
