	}
	vector pr(n, vector(32, 0));
	vector dp(n, vector(32, false));
	vector sz(n, 1);
	auto dfs = [&](int v, auto &dfs) -> void {
		dp[v][0] = 1;
		for (int u: g[v]) {
			dfs(u, dfs);
			sz[v] ^= sz[u];
			a[v] ^= a[u];
