int work(int lc,int ld)
{
    fill(dp+1,dp+ld+1,0);
    int curc=0,curd=0;
    for (int i=1;i<=ld;++i)
    {
        while (curc+1<=lc && c[curc+1]<=d[i]) ++curc;
        while (d[i]-d[curd]+1>curc && curd<i) ++curd;
        dp[i]=max(dp[i-1]+(c[curc]==d[i]),i-curd+(curc!=0));
    }
    return dp[ld];
}

