#include <bits/stdc++.h>

int N, Q;
long long A[510000], B[510000], C[510000];
long long ans[510000 * 4], water[510000 * 4], magic[510000 * 4],
    cap[510000 * 4];

void update(int n, int l, int r) {
    long long fill = std::min(water[n << 1], magic[n << 1 | 1]);
    ans[n] = ans[n << 1] + ans[n << 1 | 1] + fill;
    long long watert = std::min(cap[n << 1 | 1], water[n << 1] - fill);
    water[n] = watert + water[n << 1 | 1];
    long long magict = std::min(cap[n << 1], magic[n << 1 | 1] - fill);
    magic[n] = magic[n << 1] + magict;
    cap[n] = std::min(cap[n << 1] - magict, cap[n << 1 | 1] - watert);
}

void build(int n, int l, int r) {
    if (l == r) {
        ans[n] = std::min(A[l], B[l]);
        water[n] = std::min(C[l], A[l] - ans[n]);
        magic[n] = B[l] - ans[n];
        cap[n] = C[l] - water[n];
        return;
    }
    int m = l + r >> 1;
    build(n << 1, l, m);
    build(n << 1 | 1, m + 1, r);
    update(n, l, r);
    // printf("%d %d %d %lld %lld %lld\n", n, l, r, ans[n], water[n], magic[n]);
}

void modify(int n, int l, int r, int d) {
    if (l == r) {
        ans[n] = std::min(A[l], B[l]);
        water[n] = std::min(C[l], A[l] - ans[n]);
        magic[n] = B[l] - ans[n];
        cap[n] = C[l] - water[n];
        return;
    }
    int m = l + r >> 1;
    if (d <= m)
        modify(n << 1, l, m, d);
    else
        modify(n << 1 | 1, m + 1, r, d);
    update(n, l, r);
    // printf("%d %d %d %lld %lld %lld\n", n, l, r, ans[n], water[n], magic[n]);
}

int main() {
    scanf("%d%d", &N, &Q);
    for (int i = 1; i <= N; ++i)
        scanf("%lld", &A[i]);
    for (int i = 1; i <= N; ++i)
        scanf("%lld", &B[i]);
    for (int i = 1; i <= N - 1; ++i)
        scanf("%lld", &C[i]);
    build(1, 1, N);
    for (int i = 0; i < Q; ++i) {
        long long p, a, b, c;
        scanf("%lld%lld%lld%lld", &p, &a, &b, &c);
        // printf("%lld\n", b);
        A[p] = a, B[p] = b, C[p] = c;
        modify(1, 1, N, p);
        printf("%lld\n", ans[1]);
    }
}

#include <bits/stdc++.h>
constexpr int P = 998244353;
int power(int a, int b) {
    int res = 1;
    for (; b; b /= 2, a = int64_t(a) * a % P)
        if (b % 2 == 1) res = int64_t(res) * a % P;
    return res;
}
int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) std::cin >> a[i];
    std::sort(a.begin(), a.end());
    std::vector<int> cnt(n);
    for (int i = 0, j = 0; i < n; ++i) {
        while (j < n && 2 * a[j] <= a[i]) ++j;
        cnt[i] = n - j;
    }
    std::vector<int> dp(n), suf(n + 1), fac(n + 1), invFac(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; ++i) fac[i] = int64_t(fac[i - 1]) * i % P;
    invFac[n] = power(fac[n], P - 2);
    for (int i = n - 1; i >= 0; --i) invFac[i] = int64_t(invFac[i + 1]) * (i + 1) % P;
    int ans = 0;
    for (int i = n - 1, j = n; i >= 0; --i) {
        while (a[j - 1] >= 2 * a[i]) --j;
        if (cnt[i] == 1) dp[i] = 1;
        else if (j < n) dp[i] = int64_t(suf[j]) * fac[cnt[i] - 2] % P;
        suf[i] = (suf[i + 1] + int64_t(dp[i]) * invFac[cnt[i] - 1]) % P;
        ans = (ans + int64_t(dp[i]) * fac[n - 1] % P * invFac[cnt[i] - 1]) % P;
    }
    std::cout << ans << "\n";

    return 0;
}

