const ll M = 1e9 + 7;

ll pw(ll a, ll n = M - 2) {
    ll ret = 1;
    while (n) {
        if (n & 1) ret = ret * a % M;
        a = a * a % M;
        n >>= 1;
    }
    return ret;
}

int sz;

vvl operator * (const vvl &a, const vvl &b) {
    vvl ret(sz, vl(sz, 0));
    fori (i, sz) fori (j, sz) fori (k, sz) ret[i][j] = (ret[i][j] + a[i][k] * b[k][j]) % M;
    return ret;
}

vl operator * (const vl &a, const vvl &b) {
    vl ret(sz, 0);
    fori (j, sz) {
        fori (i, sz) {
            ret[j] = (ret[j] + a[i] * b[i][j]) % M;
        }
    }
    return ret;
}

vvl pow_mat(vvl a, ll n) {
    vvl ret(sz, vl(sz, 0));
    fori (i, sz) ret[i][i] = 1;
    while (n) {
        if (n & 1) ret = ret * a;
        a = a * a;
        n >>= 1;
    }
    return ret;
}

