using mn = modnum<int(998244353)>;

using vmn = vector<mn>;

using vvmn = vector<vmn>;



mn solve_k1(int N) { // number of multisets summing to <= N

    vmn dp(N + 1);

    dp[0] = 1;

    FORd (v, 1, N + 1) {

        F0R (sum, N - v + 1) {

            dp[sum + v] += dp[sum];

        }

    }

    return accumulate(all(dp), mn(0)) - 1;

}



mn solve_k2(int N) { // number of multisets s.t. dot prod with [1,2,....] <= N

    /*

     * used * (used + 1) / 2 <= N

     * used * (used + 1) <= 2 * N

     * used <= sqrt(2 * N)

     */

    int max_used = ceil(sqrt(2 * N)) + 1;



    vvmn dp(max_used, vmn(N + 1));

    dp[0][0] = 1;



    FORd (v, 1, N + 1)

        F0R (used, max_used - 1)

            F0R (sum, N - (used + 1) * v + 1)

                dp[used + 1][sum + (used + 1) * v] += dp[used][sum];



    mn ans = 0;

    FOR (used, 1, max_used)

        FOR (sum, 1, N + 1)

            ans += dp[used][sum];

    return ans;

}



const int MAXS = 2021;



vi vals[MAXS];



int cost(int level) {

    int tot = accumulate(all(vals[level]), 0);

    if (level == 1) return tot;

    if (tot >= MAXS) return MAXS;



    vals[level - 1].clear();



    F0R (i, sz(vals[level]))

        F0R (j, vals[level][i])

            vals[level - 1].pb(i + 1);



    reverse(all(vals[level - 1]));



    return cost(level - 1);

};



int ct[MAXS];



int go(int level) {

    vi &v = vals[level];



    int ans = 0;

    while (1) {

        int cur_cost = cost(level);

        if (cur_cost < MAXS) {

            ct[cur_cost]++;

        } else break;



        {

            v.pb(1);

            go(level);

            v.pop_back();

        }



        if (sz(v) == 1 || v.back() < v[sz(v) - 2])

            v.back()++;

        else break;

    }



