#define N_MAX 200002
mint inv[N_MAX],fac[N_MAX],finv[N_MAX];

void init(){
    fac[0]=1;fac[1]=1;
    finv[0]=1;finv[1]=1;
    inv[1]=1;
    for(int i=2;i<N_MAX;i++){
        inv[i]=mint(MOD)-inv[MOD%i]*(MOD/i);
        fac[i]=fac[i-1]*(ll) i;
        finv[i]=finv[i-1]*inv[i];
    }
}

mint comb(ll n, ll r){
    if(r < 0) return mint(0);
    if(n < r){
        return mint(0);
    }else{
        return fac[n]*finv[r]*finv[n-r];
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    init();
    int n; cin >> n;
    vector<int> a(n), b(n);
    for(int i = 0; i < n; i++) cin >> a[i] >> b[i];
    int sum = 1;
    vector<mint> ans = {mint(1)};
    for(int i = 0; i < n; i++){
        vector<mint> v;
        int sum_nx = sum+a[i]-b[i];
        int l = 1-sum;
        int r = sum_nx-1;
        for(int j = l; j <= r; j++){
            v.push_back(comb(a[i]+b[i], j+b[i]));
        }
        auto u = atcoder::convolution(ans, v);
        ans.clear();
        for(int j = 0; j < u.size(); j++){
            int idx = j-sum+2;
            if(1 <= idx && idx <= sum_nx) ans.push_back(u[j]);
        }
        sum = sum_nx;
    }
    cout << accumulate(ans.begin(), ans.end(), mint(0)) << endl;
}

