void calc(int l, int r, vector<vll> &a, vll &tot, vll cur, ll &ans, int k)

{

    if (l + 1 == r)

    {

        ans = max(ans, cur[k]);

        ll q = 0;

        for (int cnt = 0; cnt < a[l].size(); cnt++)

        {

            q += a[l][cnt];

            ans = max(ans, q + cur[k - cnt - 1]);

        }

        return;

    }

    ll m = (l + r) / 2;

    vll D = cur;

    for (int i = l; i < m; i++)

    {

        for (int e = k - a[i].size(); e >= 0; e--)

        {

            D[e + a[i].size()] = max(D[e + a[i].size()], D[e] + tot[i]);

        }

    }

    calc(m, r, a, tot, D, ans, k);

    D = cur;

    for (int i = r - 1; i >= m; i--)

    {

        for (int e = k - a[i].size(); e >= 0; e--)

        {

            D[e + a[i].size()] = max(D[e + a[i].size()], D[e] + tot[i]);

        }

    }

    calc(l, m, a, tot, D, ans, k);

}



