const int N = 3e5 + 5;

struct edge_t { int u, v, next; } G[N << 1];

int head[N], deg[N], f[N];
int T, n, tot, ans;

inline void addedge(int u, int v) {
    G[++tot] = (edge_t) {u, v, head[u]}, head[u] = tot;
    G[++tot] = (edge_t) {v, u, head[v]}, head[v] = tot;
}

void dfs1(int u, int fa) {
    int mx1 = 0, mx2 = 0, now = deg[u] + 1;
    for(register int i = head[u]; i; i = G[i].next) {
        int v = G[i].v;
        if(v == fa) continue;
        dfs1(v, u);
        if(f[v] > mx1) {
            mx2 = mx1;
            mx1 = f[v];
        } else if(f[v] > mx2) mx2 = f[v];
    }
    ans = max(ans, mx1 + mx2 + now);
    f[u] = mx1 + deg[u] - 1;
}

int main() {
    read(T);
    while(T--) {
        read(n); tot = ans = 0;
        for(register int i = 1; i <= n; i++) head[i] = deg[i] = 0;
        for(register int i = 1; i < n; i++) {
            int u, v;
            read(u); read(v);
            addedge(u, v); ++deg[u]; ++deg[v];
        }
        dfs1(1, 0); print(ans, '\n');
    }
    return 0;
}

