string s;
int a, b, t, n, ans;

void solve()
{
    int time = 0;

    for (int i = 0; i < s.length(); ++i)
    {
        time += a + (s[i] == 'h' ? 1 : b+1);
    }
    time -= a;

    int current = n;
    int i = s.length()-1;
    int j = s.length()-1;

    for (;i >= 0; --i)
    {
        while (j > i)
        {
            int extra = 2*a + (s[j] == 'h' ? 1 : b+1);
            if (time + extra > t)
                break;
            ++current;
            time += extra;
            --j;
        }

        if (time <= t)
            ans = max(ans, current);

        --current;
        time -= a + (s[i] == 'h' ? 1 : b+1);
    }
}

