void solve() {

	int64_t n, m, q, a, b, rez = 0, sum = 0, l, r, t, k, tl, tr, zeros;



	cin >> n;

	vector<int64_t> arr(n);

	vector<int64_t> sums(n + 1);

	vector<int64_t> mxdp(2);



	set<pair<int, cut>> que;



	mxdp[0] = 1e10;



	for (int i = 0; i < arr.size(); i++) {

		cin >> arr[i];

		sums[i + 1] = sums[i] + arr[i];

	}



	for (int i = n; i >= 0; i--) {

		while (que.begin() != que.end() && que.begin()->first == -i) {

			if (mxdp.size() == que.begin()->second.first)

				mxdp.push_back(que.begin()->second.second);

			else mxdp[que.begin()->second.first] = max(que.begin()->second.second, mxdp[que.begin()->second.first]);

			que.erase(que.begin());

		}



		k = min((int)mxdp.size(), i);

		t = 1;



		if (i == 0)

			break;



		if (sums[i] - sums[i - 1] > mxdp[1]) {

			mxdp[1] = sums[i] - sums[i - 1];

			continue;

		}



		if (sums[i] - sums[i - k] < mxdp[k - 1]) {

			if (k == mxdp.size() || mxdp[k] < sums[i] - sums[i - k])

				que.insert(pair<int, cut>(-i + k, cut(k, sums[i] - sums[i - k])));

			continue;

		}



		while (k - t > 1) {

			r = (k + t) / 2;



			if (sums[i] - sums[i - r] < mxdp[r - 1])

				t = r;

			else k = r;

		}



		k = t;

		if (sums[i] - sums[i - k] < mxdp[k - 1]) {

			if (k == mxdp.size() || mxdp[k] < sums[i] - sums[i - k])

				que.insert(pair<int, cut>(-i + k, cut(k, sums[i] - sums[i - k])));

			continue;

		}

	}



	//for (int i = 0; i <= n; i++)

	//	cout << sums[i] << " ";



	cout << mxdp.size() - 1 << endl;

}



