const int ML = 1005, MN = 105, Sig = 26;
const int nInf = 0xc0c0c0c0;

int N;
char C[ML], S1[MN], S2[MN];

int ch[MN][Sig], fail[MN], sum[MN], cnt;

inline void Insert(char *s, int v) {
	int now = 0;
	for (; *s; ++s) {
		if (!ch[now][*s - 'a']) ch[now][*s - 'a'] = ++cnt;
		now = ch[now][*s - 'a'];
	} sum[now] += v;
}

int que[MN], l, r;
void BuildAC() {
	fail[0] = -1;
	que[l = r = 1] = 0;
	while (l <= r) {
		int u = que[l++];
		for (int i = 0; i < Sig; ++i) {
			if (ch[u][i]) {
				if (~fail[u]) fail[ch[u][i]] = ch[fail[u]][i];
				que[++r] = ch[u][i];
			}
			else if (~fail[u]) ch[u][i] = ch[fail[u]][i];
		}
	}
	for (int i = 2; i <= r; ++i)
		sum[que[i]] += sum[fail[que[i]]];
}

int f[ML][MN];

int main() {
	scanf("%s%s%s", C, S1, S2), N = strlen(C);
	Insert(S1, 1);
	Insert(S2, -1);
	BuildAC();
	memset(f, 0xc0, sizeof f);
	f[0][0] = 0;
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j <= cnt; ++j) {
			if (f[i][j] == nInf) continue;
			for (int k = 0; k < Sig; ++k) {
				if (C[i] != '*' && C[i] != k + 'a') continue;
				int nx = ch[j][k];
				f[i + 1][nx] = std::max(f[i + 1][nx], f[i][j] + sum[nx]);
			}
		}
	}
	int Ans = nInf;
	for (int j = 0; j <= cnt; ++j) Ans = std::max(Ans, f[N][j]);
	printf("%d\n", Ans);
	return 0;
}

