unsigned n, m, s, t;

vector<unsigned> edges[200001];
unsigned d[200001];
bool visited[200001];

constexpr unsigned long long P = 1000000007ull;

bool caled[200001][2];
unsigned long long dp[200001][2];

unsigned long long cal(unsigned at, bool has) {
    if (caled[at][has]) return dp[at][has];
    if (at == t) return 1ull;
    caled[at][has] = true;
    unsigned long long ret = 0;
    for (unsigned to : edges[at]) {
        if(d[to] == d[at] - 1) {
            ret += cal(to, has);
            ret %= P;
        } else if(d[to] == d[at]) {
            if(has) {
                ret += cal(to, false);
                ret %= P;
            }
        }
    }
    dp[at][has] = ret;
    return ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    unsigned T;
    cin >> T;
    for(unsigned TE = 1; TE <= T; ++TE) {
        cin >> n >> m >> s >> t;
        for(unsigned i = 1; i <= n; ++i) edges[i].clear(), visited[i] = false, caled[i][0] = caled[i][1] = false;
        for(unsigned i = 1; i <= m; ++i) {
            unsigned u, v;
            cin >> u >> v;
            edges[u].push_back(v);
            edges[v].push_back(u);
        }
        d[t] = 0;
        visited[t] = true;
        queue<unsigned> q;
        // BFS
        q.push(t);
        while(!q.empty()) {
            unsigned u = q.front();
            q.pop();
            for(unsigned i = 0; i < edges[u].size(); ++i) {
                unsigned v = edges[u][i];
                if(!visited[v]) {
                    visited[v] = true;
                    d[v] = d[u] + 1;
                    q.push(v);
                }
            }
        }
        cout << cal(s, true) << endl;
    }

    return 0;
}

