int MOD = 998244353;
int add(int x) { return x; }
template<typename... T> int add(int a, T... b) { a += add(b...); return a >= MOD ? a - MOD : a; }
template<typename... T> int _add(int &a, T... b) { return a = add(a, b...); }
inline int sub(const int a, const int b) { return (a - b < 0) ? (a - b + MOD) : (a - b); }
