int binPow(int b, lli p) {
	int r = 1;
	while (p) {
		if (p & 1) r = mul(r, b);
		b = mul(b, b);
		p >>= 1;
	}
	return r;
}
int gcdex(int a, int b, int &x, int &y) {
	if (!b) return x = 1, y = 0, a;
	int px, py, res = gcdex(b, a % b, px, py);
	return x = py, y = px - a / b * py, res;
}
int inv(const int a) { // a and MOD must be coprime
	int x, y;
	int g = gcdex(a, MOD, x, y);
	assert(g == 1);
	x = (x % MOD + MOD) % MOD;
	return x;
}
inline int dvd(const int a, const int b) { // b and MOD must be coprime
	int rev = inv(b);
	return mul(a, inv(b));
} // b != 0
inline void _dvd(int &a, const int b) { a = dvd(a, b); } // b and MOD must be coprime
inline int convert(int x) {
	int tx = x % MOD + MOD;
	return tx >= MOD ? tx - MOD : tx;
};
