void solve() {
	int  dp[MAXV + 1][2] = { 0 };
	int sdp[MAXV + 1][2] = { 0 };

	if (a[0] == -1)
		for (int i = 1; i <= MAXV; i++)
			dp[i][0] = 1;
	else dp[a[0]][0] = 1;

	for (int i = 1; i <= MAXV; i++)
		for (int b = 0; b < 2; b++)
			sdp[i][b] += sdp[i - 1][b] + dp[i][b];

	for (int l = 1; l < n; l++) {
		int ndp[MAXV + 1][2] = { 0 };
		int nsdp[MAXV + 1][2] = { 0 };

		for (int j = 1; j <= MAXV; j++) {
			if (a[l] != -1 && j != a[l]) continue;
			ndp[j][1] = add(sub(sdp[MAXV][1], sdp[j - 1][1]), dp[j][0]);
			ndp[j][0] = add(sdp[j - 1][0], sdp[j - 1][1]);
		}

		for (int i = 1; i <= MAXV; i++)
			for (int b = 0; b < 2; b++)
				_add(nsdp[i][b], nsdp[i - 1][b] + ndp[i][b]);

		memcpy(dp, ndp, sizeof(ndp));
		memcpy(sdp, nsdp, sizeof(nsdp));
	}

	printf("%d\n", sdp[MAXV][1]);
}

