void trim(int v) {
	w[v] = 0;
	int prev = v;
	v = g[v][0];
	while (g[v].size() == 2) {
		w[v] = 0;
		if (prev != g[v][0]) {
			prev = v;
			v = g[v][0];
		}
		else {
			prev = v;
			v = g[v][1];
		}
	}
}

void farthest(int v, int prev, ll d, ll &mx, int &node) {
	if (mx < d) {
		mx = d;
		node = v;
	}
	for (const auto &i : g[v])
		if (i != prev)
			farthest(i, v, d + w[i], mx, node);
}

void dfs2(int v, int prev, int d, int &mx, int &node) {
	if (mx < d) {
		mx = d;
		node = v;
	}
	for (const auto &i : g[v])
		if (i != prev)
			dfs2(i, v, 1 + d, mx, node);
}

