namespace spencer {

struct modintM61 {
    using u32 = uint32_t;
    using u64 = uint64_t;
    using i64 = int64_t;
    using mint = modintM61;

  public:
    static constexpr i64 mod() { return i64(M61); }

    modintM61() : _v(0) {}
    modintM61(i64 x) {
        assert(-mod() <= x && x < mod());
        if (x < 0) x += mod();
        _v = u64(x);
    }

    i64 val() const { return _v; }

    mint& operator++() {
        _v++;
        if (_v == M61) _v = 0;
        return *this;
    }
    mint& operator--() {
        if (_v == 0) _v = M61;
        _v--;
        return *this;
    }
    mint operator++(int) {
        mint result = *this;
        ++*this;
        return result;
    }
    mint operator--(int) {
        mint result = *this;
        --*this;
        return result;
    }

    mint& operator+=(const mint& rhs) {
        _v += rhs._v;
        if (_v >= M61) _v -= M61;
        return *this;
    }
    mint& operator-=(const mint& rhs) {
        _v -= rhs._v;
        if (_v >= M61) _v += M61;
        return *this;
    }
    mint& operator*=(const mint& rhs) {
        u64 l1 = u32(_v), h1 = _v >> 32, l2 = u32(rhs._v), h2 = rhs._v >> 32;
        u64 l = l1 * l2, m = l1 * h2 + l2 * h1, h = h1 * h2;
        _v = (l & M61) + (l >> 61) + (h << 3) + (m >> 29) + (m << 35 >> 3) + 1;
        _v = (_v & M61) + (_v >> 61);
        _v = (_v & M61) + (_v >> 61);
        _v -= 1;
        return *this;
    }
    mint& operator/=(const mint& rhs) { return *this = *this * rhs.inv(); }

    mint operator+() const { return *this; }
    mint operator-() const { return mint() - *this; }

    mint pow(long long n) const {
        assert(0 <= n);
        mint x = *this, r = 1;
        while (n) {
            if (n & 1) r *= x;
            x *= x;
            n >>= 1;
        }
        return r;
    }
    mint inv() const {
        return pow(M61 - 2);
    }

    friend mint operator+(const mint& lhs, const mint& rhs) {
        return mint(lhs) += rhs;
    }
    friend mint operator-(const mint& lhs, const mint& rhs) {
        return mint(lhs) -= rhs;
    }
    friend mint operator*(const mint& lhs, const mint& rhs) {
        return mint(lhs) *= rhs;
    }
    friend mint operator/(const mint& lhs, const mint& rhs) {
        return mint(lhs) /= rhs;
    }
    friend bool operator==(const mint& lhs, const mint& rhs) {
        return lhs._v == rhs._v;
    }
    friend bool operator!=(const mint& lhs, const mint& rhs) {
        return lhs._v != rhs._v;
    }

  private:
    u64 _v;
    static constexpr u64 M61 = (1ull << 61) - 1;
};

