namespace spencer {

template <class X, auto op, auto id, auto add_edge, auto add_vertex>
struct reroot {
    static_assert(std::is_convertible_v<decltype(op), std::function<X(X, X)>>,
                  "op must work as X(X, X)");
    static_assert(std::is_convertible_v<decltype(id), std::function<X()>>,
                  "id must work as X()");
    static_assert(std::is_convertible_v<decltype(add_edge),
                                        std::function<X(int, int, int, X)>>,
                  "add_edge must work as X(int, int, int, X)");
    static_assert(
        std::is_convertible_v<decltype(add_vertex), std::function<X(int, X)>>,
        "add_vertex must work as X(int, X)");

  public:
    static std::vector<X> solve(int N,
                                const std::vector<std::pair<int, int>>& edges) {

        std::vector<std::vector<std::pair<int, int>>> g(N);
        for (int i = 0; i < N - 1; i++) {
            auto [a, b] = edges[i];
            g[a].push_back({2 * i, b});
            g[b].push_back({2 * i + 1, a});
        }

        std::vector<X> dp(N);
        auto dfs = [&](auto rec, int v, int p) -> void {
            X x = id();
            for (auto [e, c] : g[v]) {
                if (c != p) {
                    rec(rec, c, v);
                    x = op(x, add_edge(e ^ 1, c, v, dp[c]));
                }
            }
            dp[v] = add_vertex(v, x);
        };
        dfs(dfs, 0, -1);

        std::vector<X> answer(N);
        auto reroot = [&](auto rec, int v, int p, const X& sp) -> void {
            std::vector<X> xs;
            for (auto [e, c] : g[v]) {
                xs.push_back(add_edge(e ^ 1, c, v, c == p ? sp : dp[c]));
            }

            const int n = int(g[v].size());
            std::vector<X> head(n + 1, id());
            for (int i = 0; i < n; i++) {
                head[i + 1] = op(head[i], xs[i]);
            }
            std::vector<X> tail(n + 1, id());
            for (int i = n - 1; i >= 0; i--) {
                tail[i] = op(xs[i], tail[i + 1]);
            }

            answer[v] = add_vertex(v, head[n]);

            for (int i = 0; i < n; i++) {
                auto [e, c] = g[v][i];
                if (c != p) {
                    rec(rec, c, v, add_vertex(v, op(head[i], tail[i + 1])));
                }
            }
        };
        reroot(reroot, 0, -1, id());
        return answer;
    }
};

} // namespace spencer


