const int mod =1000000007, G = 3;
const int N = bin(19) + 15;

inline int qpow(int x, int n) {
	int ans = 1;
	while (n) {
		if (n & 1) ans = (ll) ans * x % mod;
		x = (ll) x * x % mod;
		n >>= 1;
	}
	return ans;
}
inline int inc(int x, int y) {
	return x + y >= mod ? x + y - mod : x + y;
}
inline int dec(int x, int y) {
	return x - y < 0 ? x - y + mod : x - y;
}

class FFT_Worker {
private : 
	int w[2][N], Len;
	void FFT(int a[], int n, int w[]) {
		for (int i = 0, j = 0; i < n; ++i) {
			if (i < j)  swap(a[i], a[j]);
			for (int l = n >> 1; (j ^= l) < l; l >>= 1);
		}
		for (int i = 2, m = 1, h = Len >> 1; i <= n; m = i, i <<= 1, h >>= 1) {
			for (int j = 0; j < n; j += i) for (int k = 0; k < m; ++k) {
				int t = (ll) a[j + k + m] * w[h * k] % mod;
				a[j + k + m] = dec(a[j + k], t);
				a[j + k] = inc(a[j + k], t);
			}
		}
	}
public : 
	int g[N];
	void init(int n) {
		Len = n;
		int x = qpow(G, (mod - 1) / n);
		w[0][0] = 1;
		rep (i, 1, n - 1)
			w[0][i] = (ll) w[0][i - 1] * x % mod;
		memcpy(w[1], w[0], sizeof(w[1]));
		reverse(w[1] + 1, w[1] + n);
	}
	inline void DFT(int a[], int n) {
		FFT(a, n, w[0]);
	}
	inline void IDFT(int a[], int n) {
		FFT(a, n, w[1]);
		int r = qpow(n, mod - 2);
		rep (i, 0, n-1)
			a[i] = (ll) a[i] * r % mod;
	}
	void convol(int a[], int n, int b[], int m, int c[]) {
