} my;

int fac[N], inv[N];

void init(int n) {
	fac[0] = 1;
	rep (i, 1, n) fac[i] = (ll) fac[i - 1] * i % mod;
	inv[n] = qpow(fac[n], mod - 2);
	down (i, n, 1) inv[i - 1] = (ll) inv[i] * i % mod;
	int L = 1;
	while (L <= n * 2) L *= 2;
	my.init(L);
}

inline int binom(int n, int m) {
	return n < m ? 0 : (ll) fac[n] * inv[m] % mod * inv[n - m] % mod;
}

int tmpA[N], tmpB[N];

int col[N], bak[N];
int ans[N];

int solve(int l, int r, int b[], int m) {
	if (l == r) {
		int v = col[l];
		rep (i, 1, m) b[i] = (ll) binom(v - 1, i) * inv[v - i] % mod;
		return inv[v];
	}
	int tl = l, tr = r, sa = 0, sb = 0;
	memcpy(bak + 1, col + l, sizeof(int) * (r - l + 1));
	down (i, r - l + 1, 1) {
		if (sa < sb || tl == l) {
			col[tl++] = bak[i];
			sa += bak[i] - 1;
		} else {
			col[tr--] = bak[i];
			sb += bak[i] - 1;
		}
	}
	reverse(col + l, col + tl);
	int ta = solve(l, tl - 1, b, sa);
	int tb = solve(tr + 1, r, b + sa, sb);
	tmpA[0] = ta;
	memcpy(tmpA + 1, b + 1, sizeof(int) * sa);
	tmpB[0] = tb;
	memcpy(tmpB + 1, b + sa + 1, sizeof(int) * sb);
	my.convol(tmpA, sa, tmpB, sb, tmpA);
	memcpy(b + 1, tmpA + 1, sizeof(int) * m);
	return tmpA[0];
}

void calcAns(int l, int r, int c[]) {
	if (l == r) return ;
	int mid = (l + r) / 2, rl = r - mid;
	calcAns(mid + 1, r, c);
	memcpy(tmpA, c + mid + 1, sizeof(int) * rl);
	reverse(tmpA, tmpA + rl);
	my.convol(tmpA, rl - 1, inv, r - l + 1, tmpA);
	rep (i, l, mid) c[i] = dec(c[i], tmpA[r - i]);
	calcAns(l, mid, c);
}
