constexpr int Max=1e5+100;
int head[Max],to[Max*2],nxt[Max*2],en=0;
inline void add_edge(int u,int v)
{
	to[++en]=v,nxt[en]=head[u],head[u]=en;
}
int n,o,p,q,len;
int f1[Max],f2[Max],f3[Max],g[Max],a[Max],b[Max],fa[Max],depth[Max],seq[Max];
bool can[Max],tag[Max];
void init1(int u)
{
	depth[u]=depth[fa[u]]+1;
	for(int i=head[u],v;i;i=nxt[i])
		if((v=to[i])!=fa[u])
		{
			fa[v]=u;
			init1(v);
			if(f1[v]+1>f1[u])
				f3[u]=f2[u],f2[u]=f1[u],f1[u]=f1[v]+1;
			else
				if(f1[v]+1>f2[u])
					f3[u]=f2[u],f2[u]=f1[v]+1;
				else
					chmax(f3[u],f1[v]+1);
		}
}
void init2(int u)
{
	for(int i=head[u],v;i;i=nxt[i])
		if((v=to[i])!=fa[u])
		{
			g[v]=max(g[u],f1[v]+1==f1[u]?f2[u]:f1[u])+1;
			init2(v);
		}
}
void dfs(int u)
{
	for(int i=head[u],v;i;i=nxt[i])
		if(!can[v=to[i]])
		{
			can[v]=true;
			if(!tag[v])
				dfs(v);
		}
}
bool vis[Max][2];
pii s[Max*2];
int st,ed;
inline void trans(int x,int y)
{
	if(x<0)
	{
		trans(0,y);
		return;
	}
	if(x>len)
	{
		trans(len,y);
		return;
	}
	if(!vis[x][y])
		vis[x][y]=true,s[ed++]=pii(x,y);
}
void solve()
{
	cin>>n>>p>>q;
	for(int i=1,u,v;i<n;++i)
		cin>>u>>v,add_edge(u,v),add_edge(v,u);
	init1(1),init2(1);
	for(int u=p,v=q;o=u,u!=v;++len)
		if(depth[u]>depth[v])
			u=fa[u];
		else
			v=fa[v];
	for(int i=1;i<=n;++i)
		can[i]=f1[i]>=len&&f2[i]>=len&&max(f3[i],g[i])>=len;
	for(int u=p,cnt=0;u!=o;u=fa[u])
		seq[cnt++]=u;
	for(int v=q,cnt=0;v!=o;v=fa[v])
		seq[len-cnt++]=v;
	for(int i=0;i<=len;++i)
		if(!seq[i])
			seq[i]=o;
	for(int i=0,u,v;i<=len;++i)
	{
		u=seq[i],v=i==len?0:seq[i+1];
		a[i]=fa[u]==v?f1[u]:max(f1[v]+1==f1[u]?f2[u]:f1[u],g[u]);
		v=!i?0:seq[i-1];
		b[i]=fa[u]==v?f1[u]:max(f1[v]+1==f1[u]?f2[u]:f1[u],g[u]);
		tag[u]=true;
		chmin(a[i],len),chmin(b[i],len);
	}
	for(int i=1;i<=n;++i)
		if(!tag[i]&&can[i])
			dfs(i);
	st=ed=0;
	trans(0,0),trans(len,1);
	while(st<ed)
	{
		int i=s[st].fir,k=s[st].sec;
		++st;
		if(!k)
		{
			if(i)
				trans(i-1,0);
			trans(len-a[i]+i,1);
		}
		else
		{
			if(i<len)
				trans(i+1,1);
			trans(b[i]+i-len,0);
		}
	}
	bool flag=false;
	for(int i=0;i<=len;++i)
		if((vis[i][0]||vis[i][1])&&can[seq[i]])
		{
			flag=true;
			break;
		}
	if(flag)
		cout<<"YES\n";
	else
		cout<<"NO\n";
	for(int i=1;i<=n;++i)
		head[i]=0,tag[i]=can[i]=false,depth[i]=0,fa[i]=0,f1[i]=f2[i]=f3[i]=g[i]=0;
	for(int i=0;i<=len;++i)
		vis[i][0]=vis[i][1]=false,a[i]=b[i]=0,seq[i]=0;
	len=0,en=0;
}
signed main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr),cout.tie(nullptr);
	int t;
	cin>>t;
	while(t--)
		solve();
	return 0;
}

