    dfs2(1, -1);
    sort(firstMax+1,firstMax+n+1);
    for (int k=1;k<=n;k++)
    {
        auto it=lower_bound(firstMax,firstMax+n,k);
        cout<<it-firstMax<<' ';
    }
}

