namespace sg

{

	struct tn{ int ls,rs,dt,cl; }t[W+W];

	int tot = 1, rt = 1, ql, qr, qv;

	inline void pd(tn &o){ if(o.cl) o.cl = 0, t[o.ls].cl = t[o.rs].cl = 1, t[o.ls].dt = t[o.rs].dt = 0; }

	void change(int &p,int l,int r)

	{

		if(!p) p = ++tot; else pd(t[p]);

		if(l==r){ t[p].dt = qv; return; }

		int m = (l+r)>>1; 

		if(ql<=m) change(t[p].ls,l,m);

		else      change(t[p].rs,m+1,r);

		t[p].dt = (t[t[p].ls].dt+t[t[p].rs].dt)%MO;

	}

	void clr(int p,int l,int r)

	{

		if(!p) return; pd(t[p]);

		if(ql<=l&&r<=qr){ t[p].dt = 0; t[p].cl = 1; return; }

		int m = (l+r)>>1;

		if(ql<=m) clr(t[p].ls,l,m);

		if(qr>m ) clr(t[p].rs,m+1,r);

		t[p].dt = (t[t[p].ls].dt+t[t[p].rs].dt)%MO;

	}

	int query(int p,int l,int r)

	{

		if(!p) return 0; pd(t[p]);

		if(ql<=l&&r<=qr) return t[p].dt;

		int m = (l+r)>>1, s = 0;

		if(ql<=m) s += query(t[p].ls,l,m);

		if(qr>m ) s += query(t[p].rs,m+1,r);

		return s%MO;

	}

	inline int query(int l,int r){ if(l>r) return 0; ql = l, qr = r; return query(rt,1,m); }

	inline void change(int l,int v){ ql = l, qv = v; change(rt,1,m); }

	inline void clr(int l,int r){ ql = l, qr = r; clr(rt,1,m); }

}

bool cmp(const eg &a,const eg &b){ if(a.x!=b.x) return a.x<b.x; if(a.l!=b.l) return a.l<b.l; return a.b<b.b; }

