struct Matrix {
    int n, m;
    vector<vector<Int>> vec;

    Matrix(int n, int m) : n{n}, m{m}, vec(n, vector<Int>(m)) {}
};

Matrix operator*(Matrix &x, Matrix &y) {
    Matrix z(x.n, y.m);
    for (int i = 0; i < x.n; ++i)
        for (int j = 0; j < x.m; ++j)
            for (int k = 0; k < y.m; ++k)
                z.vec[i][k] += x.vec[i][j] * y.vec[j][k] % p;
    for (int i = 0; i < z.n; ++i)
        for (int j = 0; j < z.m; ++j)
            z.vec[i][j] %= p;
    return z;
}


