            x = ch[x][c];
        }
        is_end[x] = 1;
    }
    vector<pair<int, int>> vec;
    for (int i = 1; i <= cnt; i++)
        for (int j = 1; j <= cnt; j++) {
            for (int x = i, y = j; x; x = fa[x], y = fa[y])
                if (val[x] != val[y] || !y) goto loop;
            vec.emplace_back(i, j);
            loop:;
        }
    n = (int) vec.size();
    Matrix X(n, n);
    for (int i = 0; i < n; ++i) {
        int x = vec[i].first;
        int y = vec[i].second;
        for (int c = 0; c < 26; ++c) {
            if (ch[x][c] && ch[y][c])
                X.vec[i][lower_bound(vec.begin(), vec.end(), pair(ch[x][c], ch[y][c])) - vec.begin()] = 1;
            if (ch[0][c] && ch[y][c] && is_end[x])
                X.vec[i][lower_bound(vec.begin(), vec.end(), pair(ch[0][c], ch[y][c])) - vec.begin()] = 1;
            if (ch[x][c] && ch[0][c] && is_end[y])
                X.vec[i][lower_bound(vec.begin(), vec.end(), pair(ch[0][c], ch[x][c])) - vec.begin()] = 1;
            if (ch[0][c] && is_end[x] && is_end[y])
                X.vec[i][lower_bound(vec.begin(), vec.end(), pair(ch[0][c], ch[0][c])) - vec.begin()] = x == y ? 1 : 2;
        }
    }
    Matrix A(n, n);
    for (int i = 0; i < n; ++i) A.vec[i][i] = 1;
    for (; m; m >>= 1) {
        if (m & 1)
            A = X * A;
        X = X * X;
    }
    Int ans = 0;
    for (int i = 0; i < n; ++i) {
        int x = vec[i].first;
        int y = vec[i].second;
        if (is_end[x] && is_end[y])
            ans += A.vec[n - 1][i] * (x == y ? 1 : 2);
    }
    cout << ans % p << endl;
    return 0;
}

