ll binpow(ll a,ll b){
  a=a%M;
  ll ans=1;
  while(b>0)
  {
    if(b%2!=0)
    {
      ans=(ans*a)%M;
    }
    a=(a*a)%M;
    b=b>>1;
  }
  return ans;
}

