long long bfs() {

    long long ans = 1e18;

    deque<pair<pair<int, int>, int>> q;

    vector<vector<bool>> vis(m + 10, vector<bool>(g + 10));

    q.push_back({{0, 0}, g});

    vis[0][0] = 1;

    while(!q.empty()){

        int x = q.front().first.first, path = q.front().first.second, rem = q.front().second;

        q.pop_front();

        if(x == m - 1){

            ans = min(ans, (long long)path);

            continue;

        }

        for(auto i : adj[x]){

            if(!(rem - i.second) && !vis[i.first][g]){

                vis[i.first][g] = 1;

                q.push_back({{i.first, path + rem + (i.first == m - 1? 0 : r)}, g});

            }

            else if(rem - i.second > 0 && !vis[i.first][rem - i.second]){

                vis[i.first][rem - i.second] = 1;

                q.push_front({{i.first, path + i.second}, rem - i.second});

            }

        }

    }

    return ans == 1e18? -1 : ans;

}



