ll gcd(ll a, ll b) {
	return b ? gcd(b, a % b) : a;
}
ll lcm(ll a, ll b) {
	return a / gcd(a, b) * b;
}
ll qpow(ll a, ll n, ll p) {
	ll res = 1; a %= p;
	while (n) {
		if (n & 1) res = res * a % p;
		a = a * a % p; n >>= 1;
	}
	return res;
}
ll qpow(ll a, ll n) {
	ll res = 1;
	while (n) {
		if (n & 1) res = res * a;
		a = a * a; n >>= 1;
	}
	return res;
}
ll inv(ll x) {
	return qpow(x, mod - 2, mod);
}

