	priority_queue< pair<int,int>,deque< pair<int,int> >,greater< pair<int,int> > >q;

	memset(has,0,sizeof(has));

	for (int i=1;i<=n;++i) q.push({dis[i],i});

	while (!q.empty()){

		int x=q.top().second;

		q.pop();

		if (has[x]) continue;

		has[x]=1;

		for (auto [v,w]:a[x])

			if (dis[v]>dis[x]+w){

				dis[v]=dis[x]+w;

				q.push({dis[v],v});

			}

	}

}

inline void work(int l,int r,int L,int R){

	// [l,r] [L,R]

	if (l>r) return;

	int res=9e18,resw=0;

	for (int i=L;i<=R;++i){

		int now=dis[i]+sqr(i-mid);

		if (now<res) res=now,resw=i;

	}

	s[mid]=res;

	work(l,mid-1,L,resw);

	work(mid+1,r,resw,R);

}

signed main(){

	ios::sync_with_stdio(false);

	cin.tie(0),cout.tie(0);

	int m,k;cin>>n>>m>>k;

	while (m--){int u,v,w;cin>>u>>v>>w;a[u].push_back({v,w}),a[v].push_back({u,w});}

	memset(dis,0x3f,sizeof(dis));dis[1]=0;

	solve();

	while (k--){

		work(1,n,1,n);

		for (int i=1;i<=n;++i) dis[i]=s[i];

		solve();

	}

	for (int i=1;i<=n;++i) cout<<dis[i]<<' ';

	cout<<'\n';

	return 0;

}

