	init((k+1)*2);
	solve(n);
	rep(i,0,tn) {
		a[i+1]=(a[i+1]+b[i])%mod;
		a[i]=(a[i]+b[i])%mod;
	}
	rep(i,1,k+1) printf("%d ",a[i]);
}

