uint normalize(uint p) {
    while (true) {
        bool update = false;
        for (int i = 0; i < 32; i++) {
            if (!(p & (1U << i))) continue;
            for (int j = i + 1; j < 32; j++) {
                if (!(p & (1U << j))) continue;
                int k = i ^ j;
                if (p & (1U << k)) continue;
                update = true;
                p |= (1U << k);
            }
        }
        if (!update) break;
    }
    return p;
}

uint merge(uint p, int x) {
    if (p == 1 || x == 0 || p & (1U << x)) return 1;
    return normalize(p | (1U << x));
}

uint merge2(uint p, uint q) {
    if (p == 1 || q == 1) return 1;
    if (p & q) return 1;
    return normalize(p | q);
}

set<uint> st;
void dfs(uint p) {
    if (st.count(p)) return;
    st.insert(p);
    for (int i = 0; i < 32; i++) {
        if (p & (1U << i)) continue;
        dfs(merge(p, i));
    }
}

