            ndp[merge_two[ba][j]] += dp[j];
        }
        dp = ndp;
    }

    Mint sm = 0;
    for (int i = 0; i < M; i++) {
        if (i == 1) continue;
        sm += dp[i];
    }
    pr.writeln(sm.v);
    return 0;
}

