            amts.pb(make_pair(-a,i+1));
            if (a > mx) mx = a;
        }
        sort(amts.begin(), amts.end());

        int lo = 0;
        int hi = 1023;
        while (hi > lo){
            int n = lo + (hi - lo)/2;

            if (m <= n * n - (n/2)*(n/2) && mx <= n * (n - n/2)){
                hi = n;
            }
            else{
                lo = n+1;
            }
        }

        int n = lo;
        cout << n << '\n';

        vector<vector<int>> board;
        for(int i = 0; i < n; i++){
            vector<int> nw (n, 0);
            board.pb(nw);
        }

        int c1 = (n / 2) * (n - n/2);
        int c2 = (n / 2) * (n - n/2);
        int c3 = (n - n / 2) * (n - n/2);

        assert (c1 + c2 + c3 + (n/2)*(n/2) == n * n);

        for(int i = 0; i < k; i++){
            auto p = amts[i];
            int ct = -p.first;
            int ind = p.second;
