using namespace std;
struct R{int v,z;}e[1111111];
int K[555555],ce;
void ins(int a,int b)
{
	e[++ce]=(R){b,K[a]};
	K[a]=ce;
}
long long res;
long long f[555555];
int siz[555555];
void dfs(int u,int pa=0)
{
	siz[u]=1;
	for(int i=K[u];i;i=e[i].z)if(e[i].v!=pa)
	{
		dfs(e[i].v,u);
		siz[u]+=siz[e[i].v];
	}
	f[u]=1ll*siz[u]*siz[u];
	for(int i=K[u];i;i=e[i].z)if(e[i].v!=pa)
	{
		int v=e[i].v;
		long long qwq=f[v]+1ll*(siz[u]-siz[v])*(siz[u]-siz[v]);
		if(qwq<f[u])f[u]=qwq;
	}
}
struct P
{
	int i;
	long long x,y;
	long long operator()(int p){return y-x*p;}
}p[555555],stk[555555];
int cs,cp;
inline bool operator<(const P&a,const P&b)
{
	if(a.x==b.x)return a.y<b.y;
	return a.x<b.x;
}
long long operator*(const P&a,const P&b){return a.x*b.y-a.y*b.x;}
P operator-(const P&a,const P&b){return (P){0,a.x-b.x,a.y-b.y};}
void append(P x)
{
	for(;cs>1&&(stk[cs]-stk[cs-1])*(x-stk[cs])<=0;--cs);
	stk[++cs]=x;
}
long long query(int x)
{
	if(cs==0)return 1e18;//boom
	int l=1,r=cs;
	for(;l<r;)
	{
		int mid=(l+r)>>1;
		if(stk[mid](x)<stk[mid+1](x))r=mid;
		else l=mid+1;
	}
	return stk[l](x);
}
int n;
void dp(int u,int pa=0)
{
	cp=0;
	for(int i=K[u];i;i=e[i].z)if(e[i].v!=pa)
	{
		int v=e[i].v;
		p[cp++]=(P){v,-2*siz[v],f[v]+siz[v]*(siz[v]-2ll*n)};
	}
	sort(p,p+cp);
	cs=0;
	for(int i=0;i<cp;++i)
	{
		int w=p[i].i;
		res=min(res,query(siz[w])+f[w]+siz[w]*(siz[w]-2ll*n));
		append(p[i]);
	}
	for(int i=K[u];i;i=e[i].z)if(e[i].v!=pa)
	{
		dp(e[i].v,u);
	}
}
