using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef pair <int, int> pii;

struct Edge {
  int v, w;
  Edge(int v, int w) : v(v), w(w) {}
};

const int P = int(1e9) + 7;

int diff(int a, int b) {
  if ((a -= b) < 0) {
    a += P;
  }
  return a;
}

int sum(int a, int b) {
  if ((a += b) >= P) {
    a -= P;
  }
  return a;
}

int &subtract(int & a, int b) {
  return a = diff(a, b);
}

int &add(int & a, int b) {
  return a = sum(a, b);
}

int prod(int a, int b) {
  return ll(a) * b % P;
}

int power(int a, int n) {
  int b = 1;
  while (n) {
    if (n & 1) {
      b = prod(a, b);
    }
    a = prod(a, a);
    n /= 2;
  }
  return b;
}

int inverse(int a) {
  return power(a, P - 2);
}

pii dfs(int s, int p, const vector <vector<Edge>> & ed) {
  int deg = int(ed[s].size());
  if (deg == 1) { return pii(0, 0); }

  pii res(deg, 0);
  for (const auto & e : ed[s]) {
    add(res.second, e.w);
    if (e.v == p) { continue; }
    pii cur = dfs(e.v, s, ed);
    subtract(res.first, cur.first);
    add(res.second, cur.second);
  }
  dbg("%d * a[%d] = %d + a[%d]\n", res.first, s, res.second, p);
  int inv = inverse(res.first);
  res = pii(inv, prod(res.second, inv));
  dbg("a[%d] = %d + %d * a[%d]\n", s, res.second, res.first, p);
  return res;
}

int main() {
  int n;
  scanf("%d", &n);
  vector<vector<Edge>> ed(n);
  for (int i = 0; i < n - 1; ++i) {
    int u, v, w;
    scanf("%d%d%d", &u, &v, &w);
    ed[u].push_back(Edge(v, w));
    ed[v].push_back(Edge(u, w));
  }
  pii res(int(ed[0].size()), 0);
  for (const auto & e : ed[0]) {
    add(res.second, e.w);
    pii cur = dfs(e.v, 0, ed);
    subtract(res.first, cur.first);
    add(res.second, cur.second);
  }
  //res.second = diff(0, res.second);
  dbg("%d/%d\n", res.second, res.first);
  printf("%d\n", prod(res.second, inverse(res.first)));
  return 0;
}

