void bfs()
{
    ans[1]=0;
    queue<int>nh;
    nh.push(1);
    while(!nh.empty())
    {
        int now=nh.front();
        nh.pop();
        for(int i=0;i<q[now].size();i++)
        {
            if(ans[q[now][i]]==-1)
            {
               ans[q[now][i]]=ans[now]+1;
               nh.push(q[now][i]);
            }
        }
    }
}
int dfs(int num)
{
    if(a[num]!=1e9) return a[num];
    int minn=ans[num];
    for(int i=0;i<q[num].size();i++)
    {
        if(ans[q[num][i]]<=ans[num])
        {
            minn=min(minn,ans[q[num][i]]);
        }
        else minn=min(minn,dfs(q[num][i]));
    }
    a[num]=minn;
    return minn;
}
