using namespace std;
typedef long long ll;

const int maxn=2e5+5, Log=17;

vector < int > ms[maxn];

int n, k, c;
int dist[maxn];
int parent[maxn][Log];

void dfs(int x, int prosl, int d){
	dist[x]=d;
	parent[x][0]=prosl;
	for(int i=0; i<(int)ms[x].size(); i++){
		if(ms[x][i]!=prosl){
			dfs(ms[x][i], x, d+1);
		}
	}
}

void precompute(){
	for(int i=1; i<Log; i++){
		for(int j=0; j<n; j++){
			parent[j][i]=parent[parent[j][i-1]][i-1];
		}
	}
}

void digni(int &x, int &y){
	int raz=dist[x]-dist[y];
	for(int i=0; i<Log; i++){
		if(raz&(1<<i)){
			x=parent[x][i];
		}
	}
}

int lca(int x, int y){
	if(dist[x]<dist[y]){
		swap(x, y);
	}
	digni(x, y);
	if(x==y){
		return x;
	}
	for(int i=Log-1; i>-1; i--){
		if(parent[x][i]!=parent[y][i]){
			x=parent[x][i];
			y=parent[y][i];
		}
	}
	return parent[x][0];
}

int udaljenost(int x, int y){
	return dist[x]+dist[y]-2*dist[lca(x, y)];
}

void solve(){
	cin >> n >> k >> c;
	int a, b;
	for(int i=0; i<n-1; i++){
		cin >> a >> b;
		a--;
		b--;
		ms[a].push_back(b);
		ms[b].push_back(a);
	}
	dfs(0, 0, 0);
	int maxd=0;
	int ind=0;
	for(int i=0; i<n; i++){
		if(maxd<dist[i]){
			maxd=dist[i];
			ind=i;
		}
	}
	dfs(ind, ind, 0);
	int maxd1=0;
	int ind1=0;
	for(int i=0; i<n; i++){
		if(maxd1<dist[i]){
			maxd1=dist[i];
			ind1=i;
		}
	}
	dfs(0, 0, 0);
	precompute();
	ll sol=0;
	for(int i=0; i<n; i++){
		sol=max(sol, (ll)max(udaljenost(i, ind1), udaljenost(i, ind))*k-(ll)dist[i]*c);
	}
	cout << sol << '\n';
	for(int i=0; i<n; i++){
		ms[i].clear();
	}
}

