  rep(i,5){
    int b=uniform_int_distribution<int>(255,P-1)(rng);
    base[i]=(b%2?b:b-1);
  }
}
inline Hash add(Hash x,Hash y){
  Hash z;
  rep(i,5)z[i]=(x[i]+y[i])%P;
  return z;
}
inline Hash subt(Hash x,Hash y){
