  rep(i,5)z[i]=(x[i]-y[i]+P)%P;
  return z;
}
inline Hash mult(Hash x){
  Hash z;
  rep(i,5)z[i]=(x[i]*1ll*base[i])%P;
  return z;
}
inline int pwr(ll x,ll y){
  int ret=1;
  for(;y;y>>=1,x=(x*1ll*x)%P)
    if(y&1)ret=(ret*1ll*x)%P;
  return ret;
}
