Hash sbt[N+5],hsh[N+5];
void get_subt(int v,int p=-1){
  for(int u:g[v])if(u!=p){
    get_subt(u,v);
    sbt[v]=add(sbt[v],sbt[u]);
  }
  sbt[v]=mult(sbt[v]);
  rep(i,5)sbt[v][i]=(sbt[v][i]+1)%P;
}
void get_hash(int v,int p=-1){
  for(int u:g[v])if(u!=p){
    hsh[u]=add(mult(subt(hsh[v],mult(sbt[u]))),sbt[u]);
    get_hash(u,v);
  }
}
