void dfs(int x, int fa){
    val[x] = a[x];
    for(int i = head[x]; i; i = edges[i].next){
        int y = edges[i].to;
        if(y == fa) continue;
        d[y] = d[x] + 1;
        dfs(y, x);
        val[x] += val[y];
    }
}

void init(){
    for(int i = 2; i <= n; i ++)
        dp[1] += 1LL * d[i] * a[i];
}

void tree_dp(int x, int fa){
    for(int i = head[x]; i; i = edges[i].next){
        int y = edges[i].to;
        if(y == fa) continue;
        dp[y] = dp[x] + val[1] - 2LL * val[y];
        tree_dp(y, x);
    }
}

