void update(int u) {
    rep(a, 0, 1) rep(b, 0, 1) p[u].val[a][b] = INF;
    rep(a, 0, 1) rep(b, 0, 1) rep(c, 0, 1) rep(d, 0, 1) {
        int sum = v[2 * p[u << 1].r + 1 - b] + v[2 * p[u << 1 | 1].l + c];
        if (sum < mn) sum = INF;
        p[u].val[a][d] = min(p[u].val[a][d], max(max(p[u << 1].val[a][b], p[u << 1 | 1].val[c][d]), sum));
    }
}

void build(int u, int l, int r) {
    p[u].l = l; p[u].r = r;
    if (l == r) {
        rep(a, 0, 1) rep(b, 0, 1) p[u].val[a][b] = (a == b ? 0 : INF);
        return;
    }
    int mid = (l + r) >> 1;
    build(u << 1, l, mid);
    build(u << 1 | 1, mid + 1, r);
    update(u);
}

void modify(int u, int x) {
    if (p[u].l == p[u].r) return;
    int mid = (p[u].l + p[u].r) >> 1;
    if (mid >= x) modify(u << 1, x);
    else modify(u << 1 | 1, x);
    update(u);
}

