void gen(int cur, int gk, int k, int x)
{
	if (cur == -1)
	{
		if (gk == 1)
		{
			ans += k * val[x];
			val[x] ++;
		}
		else
		{
			val[x] --;
			ans += k * val[x];
		}
		return;
	}
	gen(cur - 1, gk, k, x);
	gen(cur - 1, gk, -k, x * p[cur] );
}

void add(int i, int k)
{
	psz = 0;
	while (i != 1)
	{
		if (psz == 0 || p[psz - 1] != d[i] )
			p[psz++] = d[i];
		i /= d[i];
	}
	gen(psz - 1, k, k, 1);
}


