int e[M], ne[M], h[N], idx;

void add(int a, int b) {

    e[idx] = b, ne[idx] = h[a], h[a] = idx ++ ;

}

int in[N];

int dfs(int u, int fa) {

    int sum = 0, x = 0;

    for (int i = h[u]; ~i; i = ne[i]) {

        int j = e[i];

        if (j == fa) continue;

        int t = dfs(j, u);

        sum += t;

        x += (t == 0);

    }

    return sum + max(x - 1, 0);

}

