void sieve(int n)
{
    for(int i = 1; i <= n; i++) p[i] = i;
    for(int i = 2; i <= n; i++)
    {
        if(p[i] != i) continue;
        for(int k = i+i; k <= n; k+=i)
            p[k] = i;
    }
}

int pf[30], pp[30], d[300], dz;

int divs(int n)
{
    int pz = 0;
    while(n > 1)
    {
        int prime = p[n];
        int c = 0;
        while(n > 1 && n % prime == 0)
        {
            n /= prime;
            c++;
        }
        pf[pz] = prime;
        pp[pz++] = c;
    }
    return pz;
}

void go(int n, int idx)
{
    if(idx < 0)
    {
        d[dz++] = n;
        return ;
    }
    int x = 1;
    FOR(i,0,pp[idx])
    {
        go(n*x, idx-1);
        x *= pf[idx];
    }
}

LL f[MAX]={0}, b[300];

void update(int n)
{
    dz = 0;
    int x = divs(n);
    go(1, x-1);
    FOR(i,0,dz-1)
        b[i] = 1 + f[ d[i]+1 ];
    FOR(i,0,dz-1)
    {
        f[ d[i] ] += b[i];
        if(f[ d[i] ] > MOD) f[ d[i] ] %= MOD;
    }
}

