  dfs(1, -1);
  for (auto [col, v] : mp) {
    if (v.size() <= 1) continue;
    total++; 
    sort(v.begin(), v.end(), [&](int i, int j) { return in[i] < in[j]; });
    for (int i : v) mark[i] = true;
    int sz = v.size();
    for (int i = 1; i < sz; i++) {
      v.push_back(lca(v[i], v[i - 1]));
    }
    sort(v.begin(), v.end(), [&](int i, int j) { return in[i] < in[j]; });
    v.erase(unique(v.begin(), v.end()), v.end());
    stack<int> s;
    for (int i : v) {
      while (!s.empty() && !(in[s.top()] <= in[i] && out[i] <= out[s.top()])) s.pop();
      if (!s.empty()) g[s.top()].push_back(i);
      s.push(i);
    }
    dfs1(v[0]);
    dfs2(v[0]);
    if (max_val > 2) {
      cout << "0\n";
      return;
    }
    if (mark[v[0]]) {
      for (int i : g[v[0]]) {
        int gg = get(i, v[0]);
        update(1, 1, n, in[gg], out[gg], 1);
      }
    }
    else update(1, 1, n, 1, n, 1);
    for (int i : v) {
      if (!mark[i] || i == v[0]) continue;
      update(1, 1, n, in[i], out[i], -1);
    }
    for (int i : v) {
      g[i].clear();
      mark[i] = 0;
      val[i][0] = val[i][1] = 0;
    }
    max_val = 0;
  }
  int ans = 0;
  for (int i = 1; i <= n; i++) {
    if (query(1, 1, n, in[i]) + add[i] == total) ans++;
  }
  cout << ans << "\n";
}
