const int N = 510;
char mat[N][N];
int rem[N];
ll pd[N][N];
int n;
ll mod;

ll solve(int l0, int l1)
{
	if (l0 < 0 or l1 < 0)
		return 0LL;

	if (l0 == 0 and l1 == 0)
		return 1LL;

	if (pd[l0][l1] != -1)
		return pd[l0][l1];

	ll &ret = pd[l0][l1];

	ll ll0 = l0, ll1 = l1;
	ll l0c2 = ((ll0 * (ll0-1LL)/2LL))%mod;
	ll l1c2 = ((ll1 * (ll1-1LL)/2LL))%mod;

	ret = (l0c2*solve(l0-2, l1+2))%mod + (l1c2*solve(l0, l1-2))%mod + (ll1*ll0*solve(l0-1, l1))%mod;
	ret %= mod;
	return ret;	
}

