int n, k, ans;

const int N = 200200; 

vector<vector<int> > graph; 

vector<int> s;

int dp[N][2]; 

void dfs(int u, int num) {

	int nc = graph[u].size();

	if(nc == 0) {

		dp[u][0] = s[u] * num;

		dp[u][1] = s[u] * (num + 1);

		return;

	}	

	int paths = num / nc;

	int min_ = 0, max_ = 0;

	vector<int> diffs; 

	for(int v : graph[u]) {

		dfs(v, paths);

		min_ += dp[v][0];

		diffs.push_back(dp[v][1] - dp[v][0]);

	}

	sort(diffs.rbegin(), diffs.rend());

	int extra = num % nc;

	max_ = min_;

	for(int i = 0; i < extra; i++) min_ += diffs[i];

	extra++;

	for(int i = 0; i < extra; i++) max_ += diffs[i];

	dp[u][0] = min_  + num * s[u]; 

	dp[u][1] = max_ + (num + 1) * s[u];	

}

