vector<vector<int> > g;

ll ans = 0;
ll dfs(int u, int p = -1) // maximalna hodnota ak rodica nemazeme
{
    vector<ll> ch;
    for (int v : g[u]) if (v != p) ch.push_back(dfs(v, u));
    sort(ch.begin(), ch.end(), greater<ll>());

    // je list
    ll has = a[u], hasnot = a[u]; // ma rodica, nema rodica
    if (ch.size()) upd(hasnot, ch[0] + a[u]);

    // nechame mu aspon troch susedov 
    if (ch.size() >= 3)
    {
        ll sum = ch[0] + ch[1] + ch[2];
        for (int i = 3; i < ch.size(); i++) sum += max(0ll, ch[i]);
        upd(hasnot, sum + a[u]);
    }
    if (ch.size() >= 2)
    {
        ll sum = ch[0] + ch[1];
        for (int i = 2; i < ch.size(); i++) sum += max(0ll, ch[i]);
        upd(has, sum + a[u]);
    }

    // bude mat prave dvoch susedov
    if (ch.size() >= 2) upd(hasnot, ch[0] + ch[1]);
    if (ch.size()) upd(has, ch[0]);

    upd(ans, hasnot);
    return has;
}

