int T, n, k, ans, a[100001];
bool flag;
std::vector<int> g[100001];
int Gcd(int x, int y) { return !y ? x : Gcd(y, x % y); }
int Dfs(int u, int fa) {
  if (!flag) return 0;
  int tot = g[u].size();
  for (auto &&v : g[u])
    if (v != fa) tot -= Dfs(v, u);
  if (tot % k && (tot - 1) % k) flag = false;
  if (!(tot % k)) {
    ans = Gcd(ans, tot);
    return 1;
  } else {
    ans = Gcd(ans, tot - 1);
    return 0;
  }
}
void Solve() {
  std::cin >> n;
  for (int i = 1; i < n; i++) {
    int u, v;
    std::cin >> u >> v;
    g[u].emplace_back(v), g[v].emplace_back(u);
  }
  int tmp = n - 1;
  for (int i = 2; i * i <= tmp; i++)
    if (!(tmp % i)) {
      flag = true;
      ans = 0;
      k = i;
      Dfs(1, 0);
      if (flag) a[ans] = 1;
      while (!(tmp % i)) tmp /= i;
    }
  if (tmp > 1) {
    flag = true;
    ans = 0;
    k = tmp;
    Dfs(1, 0);
    if (flag) a[ans] = 1;
  }
  a[1] = Ksm(2, n - 1);
  for (int i = 2; i <= n; i++) Sub(a[1], a[i]);
  for (int i = 1; i <= n; i++) std::cout << a[i] << " \n"[i == n];
  for (int i = 1; i <= n; i++) std::vector<int>().swap(g[i]);
  std::memset(a + 1, 0, 4 * n);
}
