const int mod2 = 998244353;



void solve() {

    int n,k; cin>>n>>k;

    vector<int> dp(n+1),dp2(n+1),ans(n+1); dp[0]=1;

    for(int i=0;(i*(k+k+i-1))<=(2*n);i++){

        for(int j=0;j<=n;j++){

            if((j-(i+k))>=0){

                dp[j]=(dp[j]+dp[j-i-k])%mod2;

                dp2[j]=dp[j-i-k];

            }

        }

        for(int j=0;j<=n;j++){

            ans[j]=(ans[j]+dp2[j])%mod2;

            dp[j]=dp2[j];

            dp2[j]=0;

        }

    }

    ans.erase(ans.begin());

    cout<<ans;

}



