#include <cstdio>
using namespace std;
const int N = 2e5 + 1;

int n, u, v, d[N], c[N], head[N], nxt[N << 1], to[N << 1], eid = 1;
void addedge(int u, int v){
    to[eid] = v;
    nxt[eid] = head[u];
    head[u] = eid++;
}

int ans[N][2], sum[N][2];
void color(int i, int f){
    if(c[i]){
        for(int e = head[i]; e; e = nxt[e]) if(to[e] != f){
            c[to[e]] = 0;
            color(to[e], i);
        }
    }else{
        for(int e = head[i]; e; e = nxt[e]) if(to[e] != f){
            if(ans[to[e]][0] > ans[to[e]][1] || (ans[to[e]][0] == ans[to[e]][1] && sum[to[e]][0] < sum[to[e]][1]))
                c[to[e]] = 0;
            else c[to[e]] = 1;
            color(to[e], i);
        }
    }
}

void dfs(int i, int f){
    ans[i][1]++;
    sum[i][1] += d[i];
    sum[i][0]++;
    for(int e = head[i]; e; e = nxt[e]) if(to[e] != f){
        dfs(to[e], i);
        ans[i][1] += ans[to[e]][0];
        sum[i][1] += sum[to[e]][0];
        if(ans[to[e]][0] > ans[to[e]][1] || (ans[to[e]][0] == ans[to[e]][1] && sum[to[e]][0] < sum[to[e]][1])){
            ans[i][0] += ans[to[e]][0];
            sum[i][0] += sum[to[e]][0];
        }else{
            ans[i][0] += ans[to[e]][1];
            sum[i][0] += sum[to[e]][1];
        }
    }
}

int main(){
    scanf("%d", &n);
    if(n == 2){
        printf("2 2\n1 1 ");
        return 0;
    }
    for(int i = 1; i < n; i++){
        scanf("%d%d", &u, &v);
        d[u]++;
        d[v]++;
        addedge(u, v);
        addedge(v, u);
    }
    dfs(1, 0);
    if(ans[1][0] > ans[1][1] || (ans[1][0] == ans[1][1] && sum[1][0] < sum[1][1])){
        printf("%d %d\n", ans[1][0], sum[1][0]);
        c[1] = 0;
        color(1, 0);
    }else{
        printf("%d %d\n", ans[1][1], sum[1][1]);
        c[1] = 1;
        color(1, 1);
    }
    for(int i = 1; i <= n; i++)
        printf("%d ", c[i] ? d[i] : 1);
    return 0;
}

