	for(int i=1;i<=n;i++){

		cin>>chart[i];

	}

	stack<int> s;

	pair<long long,long long> dp[1+n];

	memset(dp,0,sizeof(dp));

	s.push(1);

	dp[1].first=0; 

    for(int i=2;i<=n;i++){

    	dp[i].first=dp[i-1].first;

    	while(!s.empty()&&chart[i]-(i-s.top())<=chart[s.top()]){

    		int t=s.top();

    		s.pop();

    		if(!s.empty()) dp[i].first+=(t-s.top())*(chart[t]+chart[t]-(t-s.top()-1))/2;

    		else{

    			if(chart[t]>=t) dp[i].first+=(2*chart[t]-t+1)*t/2;

    			else dp[i].first+=(chart[t]+1)*chart[t]/2;

			}

	    }

		if(!s.empty())

			dp[i].first-=(chart[i]*2-(i-s.top()-1))*(i-s.top())/2; 

		else{

    		if(chart[i]>=i) dp[i].first-=(chart[i]*2-(i-1))*i/2;

    		else dp[i].first-=(chart[i]+1)*chart[i]/2;

        }

        dp[i].first+=chart[i]; 

		s.push(i);

	}

	while(!s.empty()) s.pop();

	s.push(n);

	dp[n].second=0;

	for(int i=n-1;i>=1;i--){

		dp[i].second=dp[i+1].second;

		while(!s.empty()&&chart[i]-(s.top()-i)<=chart[s.top()]){

			int t=s.top();

			s.pop();

			if(!s.empty()) dp[i].second+=(s.top()-t)*(chart[t]+chart[t]-(s.top()-t-1))/2;

			else{

				if(chart[t]>=n-t+1) dp[i].second+=(2*chart[t]-(n-t))*(n-t+1)/2;

				else dp[i].second+=(chart[t]+1)*chart[t]/2;

			}

		}

		if(!s.empty())

			dp[i].second-=(chart[i]*2-(s.top()-i-1))*(s.top()-i)/2;

		else{

	        if(chart[i]>=n-i+1) dp[i].second-=(chart[i]*2-(n-i))*(n-i+1)/2;

	        else dp[i].second-=(chart[i]+1)*chart[i]/2;

	    }

	    dp[i].second+=chart[i];

	    s.push(i);

	}

	long long mn=10000000000000000;

	for(int i=1;i<=n;i++){

		mn=min(mn,dp[i].first+dp[i].second+chart[i]);

	}

	cout<<mn<<'\n';

} 

