void process(int x) {
    for (int i = 2; i*i <= x; ++i) if (x % i == 0) {
        int f = 0;
        while (x % i == 0) x /= i, f++;
        fac[i] |= 1<<f;
    }   
    if (x != 1) fac[x] |= (1<<1);
}

int get(int x) {
    if (x == 0) return 0;
    if (vals.count(x)) return vals[x];
    set<int> cur;
    FOR(i,1,30) if ((1<<i) <= x) {
        int x1 = (x%(1<<i))|(x>>i);
        if (x1&1) x1 ^= 1;
        cur.insert(get(x1));
    }
    for (int i = 0;;++i) if (cur.find(i) == cur.end()) return vals[x] = i;
}

