using namespace std;

const int N=25007,INF=1e9,L=3777;

vector<int> g[N];
int dp[N][L];//dp[i][j]表示以i为根节点排除j的最小值 
int a[N];

void dfs(int v)
{
	for(auto item:g[v]) dfs(item);
	//叶子节点
	if(g[v].size()==0)
	{
		for(int i=1;i<=L;i++)
		{
			if(i==a[v]) 
			{
				dp[v][i]=INF;
				continue;
			}
			else dp[v][i]=i;
		}
		return;
	}
	//只有一个子节点
	int u=g[v][0];

	int minu=INF,minw=INF;

	for(int i=1;i<=L;i++)
	{
		if(i==a[v]) continue;
		minu=min(minu,dp[u][i])	;
	}	 

	if(g[v].size()==1)
	{
		for(int i=1;i<=L;i++)
		{
			if(i==a[v]) {
			dp[v][i]=INF;
			continue;
			}
			dp[v][i]=min(dp[u][i],i*(v>1)+minu);
		}
		return;
	}

	//有两个节点
	int w=g[v][1];
	for(int i=1;i<=L;i++)
	{
		if(i==a[v]) continue;
		minw=min(minw,dp[w][i]); 
	}
	//合并两条路径
	{
		int mina=INF;
		for(int i=1;i<=L;i++)
		{
			if(i==a[v]) continue;
			mina=min(mina,dp[u][i]+dp[w][i]-i);
		}	
		for(int i=1;i<=L;i++)
		{
			if(i==a[v]) {dp[v][i]=INF;continue;}
			dp[v][i]=mina+i*(v>1);
		}
	} 
	//以v为点扩展
	{
		for(int i=1;i<=L;i++)
		{
			if(i==a[v]) continue;
			dp[v][i]=min(dp[v][i],dp[u][i]+dp[w][i]+i*(v>1));	
		}	
	} 
	//以u为点
	{
		for(int i=1;i<=L;i++)
		{
			if(i==a[v]) continue;
			dp[v][i]=min(dp[v][i],dp[w][i]+minu);	
		}	
	} 
	//以w为点
	{
		for(int i=1;i<=L;i++)
		{
			if(i==a[v]) continue;
			dp[v][i]=min(dp[v][i],dp[u][i]+minw);		
		}	
	} 
}

void solve()
{
	int n;
	cin>>n;
	for(int i=1;i<=n;i++)
	{
		g[i]={};
	}
	for(int i=1;i<=n;i++) cin>>a[i];
	vector<int> p(N+1);
	for(int i=2;i<=n;i++) cin>>p[i];
	for(int i=2;i<=n;i++) g[p[i]].push_back(i);
	dfs(1);
	int ans=INF;
	for(int i=1;i<=L;i++)
	{
		ans=min(ans,dp[1][i]);
	}
	printf("%d\n",ans);
}

int main()
{
	int t;
	cin>>t;
	while(t--)
	{
		solve();
	}
	return 0;
}

