#define N 51000
using namespace std;

int n, m, ed, R, x, y, cnt;
int f[N], dp[N], l[N], a[N], qd[N+N], qn[N+N];
LLD ret;

void bd(int x, int y){
	qd[++ed] = y, qn[ed] = l[x], l[x] = ed;
}

void Center(int x, int y, int n){
	int e = 1;
	dp[x] = 1;
	for (int i=l[x]; i; i=qn[i]){
		if (qd[i] == -1 || qd[i] == y) continue;
		Center(qd[i], x, n);
		dp[x] += dp[qd[i]];
		if (dp[qd[i]] > (n>>1)) e = 0;
	}
	if (n - dp[x] > (n>>1)) e = 0;
	if (e) R = x;
}

void dfs(int x, int y, int d){
	a[cnt++] = d;
	for (int i=l[x]; i; i=qn[i]){
		if (qd[i] == -1 || qd[i] == y) continue;
		dfs(qd[i], x, d + 1);
	}
}

void Cal(int x){
	int mx = 0;
	for (int i=l[x]; i; i=qn[i]){
		if (qd[i] == -1) continue;
		cnt = 0;
		dfs(qd[i], x, 1);
		dp[qd[i]] = cnt;
		FOR(j,0,cnt)
		if (a[j] < m) ret += f[m-a[j]];
		FOR(j,0,cnt) f[a[j]]++, mx = max(mx, a[j]);
	}
	ret += f[m];
	FOE(i,0,mx) f[i] = 0;

	for (int i=l[x]; i; i=qn[i]){
		if (qd[i] == -1) continue;
		int t = qd[i];
		qd[i] = qd[i^1] = -1;
		Center(t, -1, dp[t]);
		Cal(R);
	}
}


int main(){
	scanf("%d%d", &n, &m);
	ed = 1;
	FOR(i,1,n) scanf("%d%d", &x, &y), bd(x, y), bd(y, x);

	ret = 0;
	Center(1, -1, n);
	Cal(R);

	printf("%I64d\n", ret);
	return 0;
}

