map<int, char> f;

int calcSG(int i)
{
	if(f.count(i)) return f[i];

	int sg = 0;

	for(int j = 0; j <= 30; j++)
		if(i >> j)
		{
			sg |= (1 << (calcSG((i >> (j + 1)) | (i & ((1 << j) - 1)))));
		}

	for(int j = 0; ;j++)
		if(((sg >> j) & 1) == 0)
		{
			return f[i] = j;
		}
}

map<int, int> factor_table;

void record(int p, int k)
{
	if(k >= 1 && p > 1) factor_table[p] |= (1 << (k - 1));

	// printf("r %d %d\n", p, k);
}

void factor(long long x)
{
	for(long long i = 2; i * i <= x; i++)
	{
		if(x % i == 0)
		{
			int cnt = 0;
			for(;;)
			{
				x /= i;
				cnt += 1;
				if(x % i != 0) break;
			}

			record(i, cnt);
		}
	}

	if(x > 1) record(x, 1);
}

