        if (rem_minus < 0 or rem_plus < 0) continue;

        // if (rem_plus and !rem_minus) continue;

        const mint cat = mint(k * 2 - 6).nCr(k - 1) - mint(k * 2 - 6).nCr(k);
        const mint rem_ncr = mint(rem_minus + rem_plus).nCr(rem_plus);
        const mint good_way = mint(k).nCr(5);
        ret += cat * rem_ncr * good_way;
        // dbgif(N <= 8, make_tuple(k, cat, rem_ncr, good_way, ret));
    }

    if (A < C) {
