        const mint good_way = mint(A + 5).nCr(5);
        ret += cat * good_way;
    }

    const mint den = mint(A + C + 5).nCr(A + C) * mint(A + C).nCr(A);
    dbg(den);

    // const mint bcoeff = mint(N).nCr(B);

    return ret / den;
}

