int sub_solution(const vector<int> &a) {

  if (int(a.size()) == 1) {

    return 1;

  }

  int k = 1 << __lg(a[0] ^ a.back());

  auto m = partition_point(a.begin(), a.end(), [&](int x) {

    return (x & k) == 0;

  });

  return 1 + max(sub_solution(vector<int>(a.begin(), m)), sub_solution(vector<int>(m, a.end())));

}



