ii line[N];

int top = 0;

void init()

{

    cin >> n >> m >> k;

    for(int i = 1; i <= m; i++)

    {

        int x, y, w;

        cin >> x >> y >> w;

        adj[x].pb(ii(y, w));

        adj[y].pb(ii(x, w));

    }

}

void dijkstra()

{

    priority_queue<ii, vec<ii>, greater<ii>> q;

    for(int i = 1; i <= n; i++) if(dist[i] < INF) q.push(ii(dist[i], i));

    while(!q.empty())

    {

        int u = q.top().se;

        ll du = q.top().fi;

        q.pop();

        if(dist[u] != du) continue;

        for(ii v : adj[u]) if(minimize(dist[v.fi], du + v.se)) q.push(ii(dist[v.fi], v.fi));

    }

}

ll getVal(ll x, int i)

{

    return line[i].fi * x + line[i].se;

}

bool bad(ii l1, ii l2, ii l3)

{

    return (l3.se - l1.se) * (l1.fi - l2.fi) > (l2.se - l1.se) * (l1.fi - l3.fi);

}

ll getMin(ll x)

{

    int l = 1, r = top - 1;

    ll res = getVal(x, l);

    while(l <= r)

    {

        int mid = (l + r) >> 1;

        ll v1 = getVal(x, mid);

        ll v2 = getVal(x, mid + 1);

        if(v1 < v2)

            r = mid - 1;

        else

            l = mid + 1;

        res = min({res, v1, v2});

    }

    res = min(res, getVal(x, top));

    return res;

}

void addLine(ii newLine)

{

    while((top >= 2)&&(bad(line[top], line[top - 1], newLine))) --top;

    line[++top] = newLine;

}

