void solve() {
    cin >> n >> m >> k;
    vector<vector<int>> b(n, vector<int>(m, 0));
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        for (int j = 0; j < m; j++) {
            b[i][j] = (a[i][j] == '#');
        }
    }
    auto gett = [&] (int i, int j, vector<vector<int>>& v) {
        if (0 <= i && i < n && 0 <= j && j < m) {
            return v[i][j];
        }
        return 0;
    };
    vector<vector<int>> ld(n, vector<int>(m, 0));
    vector<vector<int>> ru(n, vector<int>(m, 0));
    vector<vector<int>> r(n, vector<int>(m, 0));
    vector<vector<int>> d(n, vector<int>(m, 0));
    int ans = 0;
    for (int t = 0; t < 4; t++) {
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                ld[i][j] = gett(i + 1, j - 1, ld) + b[i][j] - gett(i + k + 1, j - k - 1, b);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = m - 1; j >= 0; j--) {
                ru[i][j] = gett(i - 1, j + 1, ru) + b[i][j] - gett(i - k - 1, j + k + 1, b);
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                r[i][j] = gett(i, j + 1, r) + b[i][j] - gett(i, j + k + 1, b);
                d[i][j] = gett(i + 1, j, d) + b[i][j] - gett(i + k + 1, j, b);
            }
        }
        int cs = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i + j > k) {
                    break;
                }
                cs += b[i][j];
            }
        }
        ans = max(ans, cs);
        for (int i = 0; i < n; i++) {
            int ps = cs;
            for (int j = 0; j < m; j++) {
                ans = max(ans, ps);
                if (j == m - 1) {
                    break;
                }
                ps -= d[i][j];
                if (j + 1 + k >= m) {
                    int dlt = min(i + k, n - 1) - i;
                    if (j + 1 + (k - dlt) < m) {
                        ps += gett(i + dlt, j + 1 + (k - dlt), ru);
                    }
                } else {
                    ps += gett(i, j + 1 + k, ld);
                }
            }
            if (i == n - 1) {
                break;
            }
            cs -= gett(i, 0, r);
            if (k >= m) {
                int dlt = min(i + 1 + k, n - 1) - (i + 1);
                if (k - dlt < m) {
                    cs += gett(i + 1 + dlt, k - dlt, ru);
                }
            } else {
                cs += gett(i + 1, k, ld);
            }
        }
        if (t == 1) {
            reverse(all(b));
        }
        for (int i = 0; i < n; i++) {
            reverse(all(b[i]));
        }
    }
    cout << ans << '\n';
}

