struct chel {
    int mn, mx, who;
    chel(){};
    chel(int mn, int mx, int who): mn(mn), mx(mx), who(who){};

    bool operator < (chel &other) const {
        if (other.mn != mn) {
            return mn < other.mn;
        }

        return mx < other.mx;
    }
};

void solve() {

    int n; cin >> n;
    vector <chel> a(n);
    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;

        if (x > y) {
            swap(x, y);
        }
        a[i] = chel(x, y, i);
    }

    sort(a.begin(), a.end());
    int lowest_mx = 1e9 + 2, lowest_prev = 1e9 + 2;

    vector <int> ans(n);
    ans[a[0].who] = -1;
    lowest_mx = a[0].mx;
    int pos_of = a[0].who, pos_prev = a[0].who;
    for (int i = 1; i < n; ++i) {
        if (a[i].mn != a[i - 1].mn) {
            lowest_prev = lowest_mx;
            pos_prev = pos_of;
        }
        if (a[i].mx < lowest_mx) {
            pos_of = a[i].who;
            lowest_mx = a[i].mx;
        }

        if (a[i].mx > lowest_prev) {
            ans[a[i].who] = pos_prev + 1;
        } else {
            ans[a[i].who] = -1;
        }
    }

    for (auto &i: ans) {
        cout << i << ' ';
    }
    cout << '\n';

}

