	int ans=ksm(a,b/2);
	ans=ans*ans%mod;
	if(b&1) ans=ans*a%mod;
	return ans;
}
void Init(int n){
	f[0]=1;
	for(int i=1;i<=n;i++) f[i]=f[i-1]*i%mod;
	inf[n]=ksm(f[n],mod-2);
	for(int i=n-1;~i;i--) inf[i]=inf[i+1]*(i+1)%mod;
}
int C(int a,int b){
    if(a<b) return 0;
    if(b<0) return 0;
	return f[a]*inf[b]%mod*inf[a-b]%mod;
}
int c(int a,int b){
	return C(a,b)*C(a,b)%mod*f[b]%mod;
}
