int ggcd(int x,int y){

    return (y)?ggcd(y,x%y):x;

}

unsigned int gcd(unsigned int u, unsigned int v) {

    int shift;

    if (u == 0)

        return v;

    if (v == 0)

        return u;

    shift = __builtin_ctz(u | v);

    u >>= __builtin_ctz(u);

    do {

        unsigned m;

        v >>= __builtin_ctz(v);

        v -= u;

        m = (int)v >> 31;

        u += v & m;

        v = (v + m) ^ m;

    } while (v != 0);

    return u << shift;

}

int calc(int x,int y){

    int g=gcd(x,y);

    return x*y/g/g;

}

vector<int>gr[A];

struct block{

    int sz;

    int ara[B],arb[B];

    int prec[A];

    int ans,lsv;

    int&operator[](int i){return ara[i];}

    void set_all(int x){

        ans=prec[lsv=x];

    }

    void push(){

        if(~lsv) {

            for (int a = 0; a < sz; ++a) {

                ara[a] = lsv;

            }

            lsv=-1;

        }

    }

    void recompute(){

        ans=LONG_LONG_MAX;

        for(int a=0;a<sz;++a){

            ans=min(ans,calc(ara[a],arb[a]));

        }

    }

};

void precompute(block&x){

    int*dp=x.prec;

    for(int a=1;a<A;++a){

        dp[a]=INT_MAX;

    }

    for(int a=0;a<x.sz;++a){

        dp[x.arb[a]]=1;

    }

    for(int a=A-1;a>0;--a){

        for(auto b:gr[a]){

            dp[a/b]=min(dp[a/b],dp[a]*b);

        }

    }

    for(int a=1;a<A;++a){

        for(auto b:gr[a]){

            dp[a]=min(dp[a],dp[a/b]*b);

        }

