							ret = min(ret, (p[v + i+1] - p[v]) - (p[n - u] - p[n - u - i-2]) + d[i+2][j+1][v + i+1]);
						d[i][j][v] = max(d[i][j][v], ret);
					}
				}
			}

	cout << d[1][0][0] << "\n";
	return 0;
}

