void solve() {
  int n;
  scanf("%d", &n);
  std::vector<std::string> u(n);
  std::map<std::string, int> id;
  for (int i = 0; i < n; i++) {
    char s[11];
    scanf("%s", s);
    u[i] = s;
    id[s] = i;
  }
  int m;
  scanf("%d\n", &m);
  std::vector<std::vector<bool> > c(m, std::vector<bool>(n, true));
  std::vector<std::string> st(m);
  for (int i = 0; i < m; i++) {
    char s[101];
    gets(s);
    st[i] = s;
    bool known = (s[0] != '?');
    for (char *p = s; *p != 0; p++) {
      if (!(*p >= 'A' && *p <= 'Z' || *p >= 'a' && *p <= 'z' || *p >= '0' && *p <= '9')) {
        *p = ' ';
      }
    }
    char *p = strtok (s," ");
    if (known) {
      for (int j = 0; j < n; j++) {
        c[i][j] = false;
      }
      c[i][id[p]] = true;
    } else {
      while (p != 0) {     
       if (id.count(p) > 0) {
         c[i][id[p]] = false;
       }
       p = strtok (0, " ");
      }    
    }
  }

  std::vector<std::vector<bool> > dp(m, std::vector<bool>(n, false));
  dp[0] = c[0];
  for (int i = 1; i < m; i++) {
    int count = 0;
    for (int j = 0; j < n; j++) {
      if (dp[i - 1][j]) count++;
    }
    for (int j = 0; j < n; j++) {
      if (c[i][j] && (count > 1 || count == 1 && !dp[i - 1][j])) {
        dp[i][j] = true;
      }
    }
  }
  int pos = -1;
  for (int j = 0; j < n; j++) {
    if (dp[m - 1][j]) {
      pos = j;
      break;
    }
  }
  if (pos < 0) {
    puts("Impossible");
    return;
  }
  std::vector<int> ans(m);
  ans[m - 1] = pos;
  for (int i = m - 2; i >= 0; i--) {
    for (int j = 0; j < n; j++) {
      if (dp[i][j] && ans[i + 1] != j) {
        ans[i] = j;
        break;
      }
    }
  }
  for (int i = 0; i < m; i++) {
    if (st[i][0] == '?') {
      printf("%s%s\n", u[ans[i]].c_str(), st[i].c_str() + 1);
    } else {
      puts(st[i].c_str());
    }
  }
}

