    for(i=0; i<k; ++i) cin >> e[i];

    for(i=0; i<L; ++i)
        for(j=0; j<L; ++j)
            M[0][i][j] = inf;
    create_states();
    compute_powers();

    ll cnt = 0;
    for(i=1; i<=m; ++i)
    {
        int nr;
        cin >> piatra >> nr;
        val[piatra] = nr;
        if(piatra > n-x)
        {
            cnt += nr;
            continue;
        }
        special.push_back(piatra);
    }

    sort(special.begin(), special.end());
    special.erase( unique(special.begin(), special.end()), special.end() );

    for(i=0; i<L; ++i) ans[i] = inf;
    ans[code[(1<<x)-1]] = 0;

    pos = 1;
    for(auto curr : special)
    {
        advance(curr - pos);
        for(auto state : states)
            if(state & 1) ans[code[state]] += val[curr];
        pos = curr;
    }

    advance((n-x+1) - pos);
    cout << ans[code[(1<<x)-1]] + cnt << '\n';
    return 0;
}

