#define f first
#define s second
#define mp make_pair
using namespace std;


bool byLength(string l, string r) {
	return l.size() < r.size();
}


int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	string s;
	vector<string> subStrings;

	cin >> n;

	for(int c=0;c<n;c++) {
		cin >> s;

		vector<string> curSubStrings;

		for(int i=0;i<(int)s.size();i++)
			for(int j=i+1;j<=(int)s.size();j++)
				curSubStrings.push_back(s.substr(i, j-i) );

		sort(curSubStrings.begin(), curSubStrings.end() );
		curSubStrings.resize(unique(curSubStrings.begin(), curSubStrings.end() ) - curSubStrings.begin() );

		subStrings.insert(subStrings.end(), curSubStrings.begin(), curSubStrings.end() );
	}

	vector<int> cnt;
	{
		vector<string> tmp = subStrings;

		subStrings.push_back("");
		sort(subStrings.begin(), subStrings.end() );
		subStrings.resize(unique(subStrings.begin(), subStrings.end() ) - subStrings.begin() );
		cnt.resize(subStrings.size(), 0);

		for(auto c : tmp)
			cnt[ lower_bound(subStrings.begin(), subStrings.end(), c) - subStrings.begin() ]++;
	}



	//Create the nodes and process them
	vector<pair<bool, pair<int, int> > > best(subStrings.size() );

	{
		vector<string> bySize = subStrings;
		sort(bySize.begin(), bySize.end(), byLength );
		reverse(bySize.begin(), bySize.end() );


		//Go over appearing substrings
		for(auto cStr : bySize) {
			int i = lower_bound(subStrings.begin(), subStrings.end(), cStr) - subStrings.begin();

			best[i] = mp(true, mp(cnt[i], 0) );
			int mx = 0;
			for(auto c : cStr)
				mx = max(mx, c - 'a' + 1);

			for(auto c : cStr)
				best[i].s.f += (c - 'a' + 1) * mx;

			pair<bool, pair<int, int> > other = mp(false, mp(0, 0) );

			//First add to front
			{
				string next = "a" + cStr;
				while(next[0] <= 'z') {
					int j = lower_bound(subStrings.begin(), subStrings.end(), next) - subStrings.begin();
					if(j != (int)subStrings.size() && subStrings[j] == next )
						other = max(other, best[j]);

					next[0]++;
				}
			}

			//Next add to the back
			{
				string next = cStr + "a";
				while(next.back() <= 'z') {
					int j = lower_bound(subStrings.begin(), subStrings.end(), next) - subStrings.begin();
					if(j != (int)subStrings.size() && subStrings[j] == next)
						other = max(other, best[j]);

					next.back()++;
				}
			}

			//Finally update best
			best[i].f = !other.f;
			best[i].s.f -= other.s.s;
			best[i].s.s -= other.s.f;
		}


	}


	//And finally output the result
	if(best[0].f)
		cout << "Second\n";
	else
		cout << "First\n";

	cout << -best[0].s.s << ' ' << best[0].s.f << '\n';

	return 0;
}

