const ll LINF = (ll)1e18;

const int IINF = (int)1e9;

#define int ll





void solve(){

    int n;

    cin >> n;



    vector<int> arr(n);

    for(int i = 0;i < n;i++)

        cin >> arr[i];



    int ans = 0;

    for(int z = 0;z < 2;z++){

        pair<int,int> maxel = {-1, -1};

        for(int i = 0;i < n;i++) maxel = max(maxel, {arr[i], i});

        int idx = maxel.second;



        bool can = true;

        pair<int,int> cur = {0, 0};

        for(int i = 0;i <= idx && can;i++){

            if(cur.first < arr[i]) cur.first = arr[i];

            else if(cur.second < arr[i]) cur.second = arr[i];

            else can = false;

        }

        if(!can){

            reverse(all(arr));

            continue;

        }



        pair<int,int> c2 = {0, 0};

        vector<pair<int,int>> pre(n);

        for(int i = n-1;i > idx;i--){

            if(c2.first < arr[i]) c2.first = arr[i];

            else if(c2.second < arr[i]) c2.second = arr[i];

            else c2 = {LINF, LINF};

            pre[i] = c2;

        }



        vector<pair<int,int>> ops;

        ops.push_back(cur);

        for(int i = idx+1;i < n;i++){

            for(auto it:ops){

                if(pre[i].first == LINF) break;

                int oth = (pre[i].first == arr[i]) ? pre[i].second : pre[i].first;

                if(it.second < arr[i] && it.first > oth){

                    ans++;

                    break;

                }

            }



            int mn = LINF;

            int mx = -1;



            for(auto it:ops){

                if(it.second < arr[i]){

                    mx = max(mx, it.first);

                }

                if(it.first > arr[i]){

                    mn = min(mn, it.second);

                }

            }



            ops.clear();

            if(mn != LINF) ops.push_back({arr[i], mn});

            if(mx != -1) ops.push_back({mx, arr[i]});

        }



        reverse(all(arr));

    }

    cout << ans << "\n";

}





signed main(){

