using namespace std;

const int MAXN = 1123456;
vector<int> chd[MAXN];
int n, k;

pair<pair<int, int>, int> dfs(int p, int d) {
   if (chd[p].empty()) {
      return {{1, d - k,}, 1};
   }

   int max_not_back = 0;
   int sum_back = 0;
   int top = n;
   int fwd = 0;

   int fix = -n;
   for (int q : chd[p]) {
      auto sub = dfs(q, d + 1);

      if (sub.first.second <= d) {
         sum_back += sub.first.first;
         top = min(top, sub.first.second);
         fix = max(fix, sub.second - sub.first.first);
      } else {
         max_not_back = max(max_not_back, sub.second);
      }
      fwd = max(fwd, sub.second);
   }

   fwd = max(fwd, sum_back + fix);


   return {{sum_back, top}, max(fwd, sum_back + max_not_back)};
}

