	solve(1), solve2(1);

	for (root = 1; root <= n && count[root] < 3; ++root);

	if (root > n) {cout << "NO\n"; return;}

	zigzag::init(root), c = zigzag::LCA(a, b),

	cout << (zigzag::check(a, b, c) || zigzag::check(b, a, c) ? "YES\n" : "NO\n");

}



