      *--p = '0';

    } else {

      bool is_negative = false;

      if (n < 0) {

        is_negative = true;

        n = -n;

      }

      while (n > 0) {

        *--p = (char) ('0' + n % 10);

        n /= 10;

      }

      if (is_negative) {

        *--p = '-';

      }

    }

    return p;

  }



