    using P = pair<ll, ll>;
    V<P> st;
    st.push_back(P{TEN(9), 0});
    ll ans = 0;
    ll bk = 0, ma = 0, now = 0;
    for (int ph = 1; ph <= n; ph++) {
        char c = s[ph - 1];

        if (c == '0') {
            bk = ph;
        } else {
            ma = max(ma, ph - bk);

            P p = {ph - bk, ph};
            while (st.back().first < p.first) {
                P q0 = st.back();
                st.pop_back();
                P q1 = st.back();
                now -= (q0.second - q1.second) * q0.first;
            }
            P q = st.back();
            now += (p.second - q.second) * p.first;
            st.push_back(p);
        }

        ll val = now - ma * (ma - 1) / 2;
                            ;
        ans += val;
    }

    pr.writeln(ans);
    return 0;
}

