void solve()
{
    ll N, Q; cin >> N >> Q;
    vector<array<ll, 26>> psum1(N+1), psum2(N+1);

    string a, b; cin >> a >> b;
    for(ll i = 0; i < N; i++)
    {
        for(ll j = 0; j < 26; j++)
        {
            psum1[i+1][j] = psum1[i][j] + ((a[i] - 'a') == j);
            psum2[i+1][j] = psum2[i][j] + ((b[i] - 'a') == j);
        }
    }

    for(ll q = 0; q < Q; q++)
    {
        ll l, r; cin >> l >> r;
        ll ans = 0;
        for(ll j = 0; j < 26; j++)
        {
            ans += abs((psum1[r][j] - psum1[l - 1][j]) - (psum2[r][j] - psum2[l - 1][j]));
        }

        cout << ans/2 << endll;
    }
}

