const int mod = 1000000007;
void add(int &a, int b) {
	a = ((a+b >= mod) ? (a+b-mod) : (a+b));
}
void add(int &a, long long b) {
	a = (a+b)%mod;
}
int main(){
	int n,totlim;
	scanf("%d%d",&n,&totlim);
	vector<int> a(n);
	for (int i = 0; i < n; i++)
		scanf("%d",&a[i]);
	sort(a.begin(),a.end());

	dt[0][0][0] = 1;
	for (int i = 0; i < n; i++) {
		int ci = i % 2;
		int li = 1 - ci;
		int inc = 0;
		if (i) inc = (a[i] - a[i-1]);
		memset(dt[li], 0, sizeof(dt[li]));
		for (int j = 0; j <= i && j + j <= n; j++) {
			for (int k = 0; k+inc*j <= totlim; k++) {
				int nk = k+inc*j;
				int cur = dt[ci][j][k];
				if (dt[ci][j][k] == 0) continue;
				/* open */
				add(dt[li][j+1][nk], cur);
				/* open & close */
				add(dt[li][j][nk], cur);
				/* close */
				if (j > 0) add(dt[li][j-1][nk], cur * (long long)j);
				/* assign */
				add(dt[li][j][nk], cur * (long long)j);
			}
		}
	}
	long long ans = 0;
	for (int i = 0; i <= totlim; i++)
		ans += dt[n%2][0][i];
	ans %= mod;
	printf("%lld\n", ans);
	return 0;
}

