	pt(){}
	pt(int x, int y): x(x),y(y){}
	inline pt operator+(pt p){return {x+p.x, y+p.y};}
	inline pt operator-(pt p){return {x-p.x, y-p.y};}
	inline pt operator*(int p){return {p*x, p*y};}
	inline int operator^(pt p){return x*p.y - y*p.x;}
	inline int operator*(pt p){return x*p.x + y*p.y;}
	inline pt operator/(int p){return {x/p, y/p};}
	inline bool operator==(pt p){
		return p.x==x &&p.y==y;
	}
};
inline bool up(pt p) {
  return p.y > 0 or (p.y == 0 and p.x >= 0);
}
bool operator < (const pt &a,const pt &b){return up(a) == up(b) ? a.x * b.y > a.y * b.x : up(a) < up(b);}



inline int dist2(pt a, pt b) {return (a - b)*(a - b); }
inline int norm2(pt a)	{ return a*a; }
pt rot(pt a) { return pt(-a.y, a.x); }

struct line{
    pt p;
    pt pq;
    line(){}
    line(pt a,pt b){
        pq=b-a;
        p=a;
    }
};
bool operator < (const line &a,const line &b){return a.pq<b.pq;}

bool onLeft(line l,pt a){return (l.pq^(a-l.p))>0;}


inline pt proj(line l, pt r){return l.p+l.pq*((r-l.p)*l.pq/norm2(l.pq));}
inline pt refl(line l, pt r){return proj(l,r)*2-r;}
pt intersect(line a,line b){
	int alpha = ((b.p - a.p) ^b.pq) / (a.pq ^b.pq);
  return a.p + (a.pq * alpha);
}
int ccw(pt a, pt b, pt c){
	return a.x*b.y + b.x*c.y + c.x*a.y - a.y*b.x - b.y*c.x - c.y*a.x > 0; //equal if not strict
}
int cw(pt a, pt b, pt c){
	return a.x*b.y + b.x*c.y + c.x*a.y - a.y*b.x - b.y*c.x - c.y*a.x < 0;
}
int align(pt a, pt b, pt c){
	return a.x*b.y + b.x*c.y + c.x*a.y - a.y*b.x - b.y*c.x - c.y*a.x == 0;
}
int between(pt p, pt q, pt r){ 
    if (q.x <= max(p.x, r.x) && q.x >= min(p.x, r.x) && 
        q.y <= max(p.y, r.y) && q.y >= min(p.y, r.y)) 
       return 1; 
    return 0; 
} 

//not tested
bool strict_intersect(pt a, pt b, pt c, pt d){
	if(!cw(a,b,c) && !cw(a,b,d))return 0;
	if(!ccw(a,b,c) && !ccw(a,b,d))return 0;
	if(!cw(c,d,b) && !cw(c,d,a))return 0;
	if(!ccw(c,d,b) && !ccw(c,d,a))return 0;
	return (cw(a,b,c) && ccw(a,b,d)) || (ccw(a,b,c) && cw(a,b,d));
}
bool nonstrict_intersect(pt a, pt b, pt c, pt d){
	return strict_intersect(a,b,c,d) || between(a,b,c) || between(a,b,d) || between(c,d,a) || between(c,d,b);
}

ld f(ld ang){ while(ang>=2*PI)ang-=2*PI; while(ang<0)ang+=2*PI; return min(abs(2*PI-ang),ang); }
ld angle(pt a, pt b, pt c){ pt x1 = a-b; pt x2 = c-b; return f(atan2(x1.y,x1.x)-atan2(x2.y,x2.x)); }


int power(int a, int b){
	if(b==0)return 1;
	if(b%2)return a*power(a,b-1)%MOD;
	return power(a*a%MOD,b/2);
}
int inv(int a){
	return power(a,MOD-2);
}







vector<pt> convexhull(vector<pt>v){
	int n =	v.size();
	sort(v.begin(),v.end(),[](pt a, pt b){
		return a.x<b.x || (a.x==b.x && a.y<b.y);
	});
	pt A = v[0];
	pt B = v.back();
	vector<pt>up(1,A);
	vector<pt>down(1,A);
	for(int i = 1;i<n;i++){
		if(i==v.size()-1 || !ccw(A,v[i],B)){
			while(up.size()>=2 && ccw(up[up.size()-2],up[up.size()-1],v[i]))up.pop_back();
			up.push_back(v[i]);

		}
		if(i==v.size()-1 || !cw(A,v[i],B)){
			while(down.size()>=2 && cw(down[down.size()-2],down[down.size()-1],v[i]))down.pop_back();
			down.push_back(v[i]);
		}
	}
	vector<pt>ans;
	for(int i = 0;i<down.size()-1;i++){
		ans.push_back(down[i]);
	}
	reverse(up.begin(),up.end());
	for(int i = 0;i<up.size()-1;i++){
		ans.push_back(up[i]);
	}
	return ans;
}
int n;
vector<pt>ch;

int get(int l, int r){
	if(l==r)return -1;
	if((l+1)%n==r)return -1;
	int bestidx = -1;
	ld bestang = INF;
	if(l<r){
		for(int i = l+1;i<r;i++){
			ld ang = angle(ch[l],ch[i],ch[r]);
			assert(ang<=PI);
			if(ang<bestang){
				bestang = ang;
				bestidx = i;
			}
		}
		return bestidx;
	}
	for(int i = l+1;i<n+r;i++){
		ld ang = angle(ch[l],ch[i%n],ch[r]);
		assert(ang<=PI);
		if(ang<bestang){
			bestang = ang;
			bestidx = i%n;
		}
	}
	return bestidx;
}

int C(int n, int k){
	if(k<0 || k>n)return 0;
	if(k==0)return 1;
	return n*C(n-1,k-1)%MOD*inv(k)%MOD;
}

int solve(int l, int r){
	if((l+1)%n==r)return 1;
	int i = get(l,r);
	int dp1 = solve(l,i);
	int dp2 = solve(i,r);
	int cnt1 = i-l-1;
	if(i<l)cnt1 = i+n-l-1;
	int cnt2 = r-i-1;
	if(i>r)cnt2 = r+n-i-1;
	return dp1*dp2%MOD* C(cnt1+cnt2,cnt1)%MOD;
}
