    vector<int> queries;

    Input() = default;
    void gen();
    void scan();
    Output solve();
    Output brute();
  };

  bool Output::check_valid(Input inp) const
  {
    return true;
  }
  void Input::gen()
  {
    n = rand() % 3  +2;
    a.assign(n + 1, -1);
    for (int i = 1; i <= n; i++)
      a[i] = rand() % n + 1;

    q = n - 1;
    queries.resize(q);
    for (int i = 2; i <= n; i++)
      queries[i - 2] = i;
  }
  Output Input::brute()
  {
    Output out;
    out.ans.resize(q);

    sort(a.begin(), a.end());


    for (int idx = 0; idx < q; idx++)
    {
      int k = queries[idx];
      int ret = 0;
      vector<int> assignment(n + 1, 0);

      auto bt = [&](int idx, auto&& bt) -> void
      {
        if (idx == n + 1)
        {
          bool bad = false;
          int cur = 0;
          for (int i = 1; i <= k; i++)
          {
            vector<int> people_read;
            for (int j = 1; j <= n; j++)
            {
              if (assignment[j] == i)
                people_read.push_back(j);
            }
            bad |= people_read.empty();

            for (int u: people_read)
            {
              cur += a[u] <= people_read.size();
            }
          }
          if (not bad)
            ret = max(ret, cur);
          return;
        }
        for (int i = 1; i <= k; i++)
        {
          assignment[idx] = i;
          bt(idx + 1, bt);
        }
      };

      bt(1, bt);
      out.ans[idx] = ret;
    }

    return out;
  }

