Output Input::solve()
{
  Output out;
  sort(a.begin(), a.end());

  vector<int> dp(n + 2, -1e9);
  vector<int> ans(n + 2, 0);
  dp[0] = 0;

  auto upd = [&](int max_groups, int ppl)
  {
    if (max_groups <= 0)
      return;
    max_groups = min(max_groups, n);
    ans[max_groups] = max(ans[max_groups], ppl);
  };

  for (int i = 1; i <= n; i++)
  {
    if (i - a[i] >= 0)
    {
      dp[i] = dp[i - a[i]] + 1;
      upd(dp[i] + n - i, i);
    }
    else
    {
      upd(n - a[i] + 1, i);
    }
    dp[i] = max(dp[i - 1], dp[i]);
  }

  for (int i = n; i >= 0; i--)
  {
    ans[i] = max(ans[i], ans[i + 1]);
  }


  out.ans.resize(q);
  for (int i = 0; i < q; i++)
  {
    out.ans[i] = ans[queries[i]];
  }

  return out;
}


