typedef long long ll;

struct mfriend {
  int s, b, i;
};

void solve(int n) {
  vector<mfriend> f(n);
  vector<int> ans(n, -1);
  for (int i = 0; i < n; i++) {
    scanf("%d%d", &f[i].s, &f[i].b);
    if (f[i].s > f[i].b) swap(f[i].s, f[i].b);
    f[i].i = i;
  }
  sort(f.begin(), f.end(), [&](const mfriend& le, const mfriend& ri) {
    return le.s < ri.s || (le.s == ri.s && le.b < ri.b);
  });
  int b_min = f[0].b, bi = f[0].i;
  int i = 1, j = 0;
  while (f[i].s == f[i-1].s) i++;
  for (; i < n; i++) {
    for (; j < i && f[j].s < f[i].s; j++) {
      if (b_min > f[j].b) {
        b_min = f[j].b;
        bi = f[j].i;
      }
    }
    if (b_min < f[i].b) {
      ans[f[i].i] = bi + 1;
    }
  }
  for (int i = 0; i < n; i++) {
    printf(i ? " %d" : "%d", ans[i]);
  }
  printf("\n");
}

