struct node {
  int x, s, p;
  node *l, *r;
   node(int x):x(x), l(0), r(0), p((rand() << 16) ^ rand()) {
  } node(node * p) {
    x = p->x;
    s = p->s;
    this->p = p->p;
    l = p->l;
    r = p->r;
  }
  ~node() {
    del(l);
    del(r);
  }
};

struct treap {
  node *root = nullptr;

  ~treap() {
    del(root);
  } int sz(node * p) {
    return p ? p->s : 0;
  }

  void u(node * p) {
    if (p)
      p->s = sz(p->l) + 1 + sz(p->r);
  }

  node *rtl(node * p) {
    auto c = p->r;
    if (c->p > p->p)
      return p;
    p->r = c->l;
    c->l = p;
    u(p);
    u(c);
    return c;
  }

  node *rtr(node * p) {
    auto c = p->l;
    if (c->p > p->p)
      return p;
    p->l = c->r;
    c->r = p;
    u(p);
    u(c);
    return c;
  }

  node *insert(node * p, int x) {
    if (!p)
      return new node(x);
    else if (x > p->x)
      p->r = insert(p->r, x), u(p), p = rtl(p);
    else if (x < p->x)
      p->l = insert(p->l, x), u(p), p = rtr(p);
    return p;
  }

  void insert(int x) {
    root = insert(root, x);
  }

  int print(node * p, int h) {
    int l = p->l ? print(p->l, h + 1) : h;
    put(p->x);
    int r = p->r ? print(p->r, h + 1) : h;
    return max(l, r);
  }

  int print() {
    return root ? print(root, 0) : 0;
  }
};

