const int MAXN = 3030;
vector<int> g[MAXN];
ll w[MAXN];
ll dp[MAXN][MAXN];
int par[MAXN];
int n;

int dfs(int v, int p = -1) {
    w[v] = 1;
    par[v] = p;
    for (int u : g[v]) {
        if (u == p) {
            continue;
        }
        w[v] += dfs(u, v);
    }
    return w[v];
}


vector<int> dfs_calc(int v, int p = -1) {
    vector<int> subtree = {v};
    for (int u : g[v]) {
        if (u == p) {
            continue;
        }
        vector<int> cur = dfs_calc(u, v);
        for (int t : cur) {
            dp[v][t] = max(dp[u][t], dp[v][par[t]]) + (n - w[u]) * w[t];
            dp[t][v] = dp[v][t];
        }
        for (int s : subtree) {
            if (s == v) {
                continue;
            }
            for (int t : cur) {
                dp[s][t] = max(dp[s][par[t]], dp[t][par[s]]) + w[s] * w[t];
                dp[t][s] = dp[s][t];
            }   
        }
        for (int t : cur) {
            subtree.push_back(t);
        }
    }
    return subtree;
}


