const int N = 5005;

ll inf = 1<<30;

int n , h[N] , to[N << 1] , ne[N << 1] , w[N << 1] , e;

void link(int u,int v,int w){

    to[e] = v , ne[e] = h[u] , ::w[e] = w;h[u] = e++;

}



int sz[N],Sz;

ll Min,Sum,dis[N];

void dfs(int c,int fa){

    sz[c] = 1;dis[c] = 0;

    for(int k=h[c],t;~k;k=ne[k]) if((t=to[k]) != fa){

        dfs(t , c);

        sz[c] += sz[t];

        dis[c] += dis[t] + (ll)sz[t] * w[k];

    }

}

void dfs2(int c,int fa){

    if(dis[c] < Min) Min = dis[c];

    Sum += dis[c];

    for(int k=h[c],t;~k;k=ne[k]) if((t=to[k]) != fa){

        dis[t] = dis[c] + (ll)(Sz - 2 * sz[t]) * w[k];

        dfs2(t , c);

    }

}

pair<ll,pair<int,ll> > solve(int c,int fa){

    dfs(c , fa);

    Min = inf;Sum = 0;Sz = sz[c];

    dfs2(c , fa);

    return make_pair(Sum/2,make_pair(Sz,Min));

}



