const int maxn=3e3+5,maxm=1e4+5;
int n,dfs[maxn],efs[maxn],son[maxn],tot,f[maxn];
long long dp[maxn][maxn];
bool vis[maxn]; 
long long ans;
int head[maxn],nume;
struct edge { int v,w,c,next; } e[maxm];  // v顶点,w权值,c花费
inline void init_edge() { memset(head,-1,sizeof head); nume=0; } // !!!
inline void add_edge(int u,int v,int w=0,int c=0) {
    e[nume].v=v; e[nume].w=w; e[nume].c=c;
    e[nume].next=head[u]; head[u]=nume++;
}
vector<pair<int,int> > vec[maxn];
void Dfs(int u)
{
	vis[u]=true;
	dfs[u]=++tot;
	son[u]=1;
	for(int i=head[u];~i;i=e[i].next)
	{
		int v=e[i].v;
		if(!vis[v])
		{
			f[v]=u;
			Dfs(v);
			son[u]+=son[v];
			vec[u].push_back(make_pair(-son[v],v));
		}
	}
	sort(vec[u].begin(),vec[u].end());
	efs[u]=tot;
}
long long DP(long long u,long long v)
{
	if(u==v) return 0;
	if(dp[u][v]) return dp[u][v];
	if(dfs[u]<=dfs[v]&&efs[u]>=efs[v])
	{
		int x;
		for(int i=0;;i++)
		{
			if(dfs[vec[u][i].second]<=dfs[v]&&efs[vec[u][i].second]>=efs[v])
			{
				x=vec[u][i].second;
				break;
			}
		}
		dp[v][u]=dp[u][v]=max(DP(u,f[v]),DP(x,v))+son[v]*(n-son[x]);
		return dp[u][v];
	}
	if(dfs[v]<=dfs[u]&&efs[v]>=efs[u])
	{
		int x;
		for(int i=0;;i++)
		{
			if(dfs[vec[v][i].second]<=dfs[u]&&efs[vec[v][i].second]>=efs[u])
			{
				x=vec[v][i].second;
				break;
			}
		}
		dp[v][u]=dp[u][v]=max(DP(v,f[u]),DP(x,u))+son[u]*(n-son[x]);
		return dp[u][v];
	}
	dp[v][u]=dp[u][v]=max(DP(u,f[v]),DP(f[u],v))+son[u]*son[v];
	return dp[u][v];
}
int main()
{
	int u,v;
	init_edge();
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		scanf("%d%d",&u,&v);
		add_edge(u,v);
		add_edge(v,u);
	} 
	Dfs(1);
	for(int i=1;i<n;i++)
	for(int j=i+1;j<=n;j++)
	{
		ans=max(ans,DP(i,j));
	}
	printf("%I64d\n",ans);
}

