int count(int *arr, int l, int r, int k) {

  // return the number of 0s in arr[l: r]

  int ret = 0;

  for (int i = l; i <= r; i++) {

    if (!(arr[i] & (1 << k))) ++ret;

  }

  return ret;

}



void partition(int *arr, int l, int r, int k) {

  // sort arr[l: r], 0 -> 1

  int pl = l, pr = r;

  for (int i = l; i <= r; i++) {

    if (arr[i] & (1 << k)) tmp[pr--] = arr[i];

    else tmp[pl++] = arr[i];

  }

  assert(pl - 1 == pr);

  for (int i = l; i <= r; i++) arr[i] = tmp[i];

}



