int dep[maxn], fa[maxn], deg[maxn], cnt[maxn], mdeg[maxn], mdep[maxn];

bool vis[maxn];

void dfs(int u){
    mdep[u]=dep[u];
    mdeg[u]=deg[u];
    for(int i=0;i<G[u].size();i++){
        int v=G[u][i];
        if(v==fa[u]) continue;
        dep[v]=dep[u]+1;
        fa[v]=u;
        dfs(v);
        mdep[u]=max(mdep[u],mdep[v]);
        mdeg[u]=max(mdeg[u],mdeg[v]);
    }
}

int rt2;

void dfs2(int u){
    vis[u]=1;
    rt2=u;
    for(int i=0;i<G[u].size();i++){
        int v=G[u][i];
        if(v==fa[u]) continue;
        dfs2(v);
    }
}

bool judge(int rt){
    dep[rt]=0; fa[rt]=-1; dfs(rt);

    memset(cnt,0,n*sizeof(int));
    for(int i=1;i<=n;i++){
        int d=dep[i];
        if(!cnt[d]) cnt[d]=deg[i];
        else if(cnt[d]!=deg[i]) return 0;
    }
    return 1;
}

int solve(){
    int e1, e2, rt;
    dep[1]=0; fa[1]=-1; dfs(1);
    e1=max_element(dep+1,dep+n+1)-dep;
    dep[e1]=0; fa[e1]=-1; dfs(e1);
    e2=max_element(dep+1,dep+n+1)-dep;
    //cout<<"e1: "<<e1<<" ,e2: "<<e2<<endl;
    if(judge(e2)) return e2;
    if(judge(e1)) return e1;

    if(dep[e2]&1) return -1;

    rt=e2;
    for(int i=0;i<dep[e2]/2;i++) rt=fa[rt];
    //cout<<"rt: "<<rt<<endl;

    dep[rt]=0; fa[rt]=-1; dfs(rt);

    bool flag=1;
    memset(cnt,0,n*sizeof(int));
    for(int i=1;i<=n;i++){
        int d=dep[i];
        if(!cnt[d]) cnt[d]=deg[i];
        else if(cnt[d]!=deg[i]) flag=0;
    }
    if(flag) return rt;

    //cout<<rt<<" *** "<<endl;
    // -----------------------------------
    flag=0;
    memset(vis,0,n+1);
    int d=*max_element(dep+1,dep+n+1);
    for(int i=0;i<G[rt].size();i++){
        int u=G[rt][i];
        if(mdep[u]<d && mdeg[u]<=2){
            //cout<<"u1: "<<u<<endl;
            dfs2(u);
            flag=1;
            break;
        }
    }

    if(!flag){
        //for(int i=1;i<=n;i++) cout<<i<<": "<<mdeg[i]<<endl;
        for(int i=0;i<G[rt].size();i++){
            int u=G[rt][i];
            if(mdeg[u]<=2){
                //cout<<"u2: "<<u<<endl;
                dfs2(u);
                flag=1;
                break;
            }
        }
    }

    //cout<<"flag: "<<flag<<endl;
    // --------------------------
    if(!flag) return -1;
    memset(cnt,0,n*sizeof(int));
    for(int i=1;i<=n;i++){
        if(vis[i]) continue;
        int d=dep[i];
        if(!cnt[d]) cnt[d]=deg[i];
        else if(cnt[d]!=deg[i]) return -1;
    }
    return rt2;
}

int main(){
    //freopen("in.txt", "r", stdin);
    while(cin>>n){
        memset(deg,0,(n+1)*sizeof(int));
        for(int i=0;i<=n;i++) G[i].clear();

        for(int i=0;i<n-1;i++){
            int u, v;
            scanf("%d %d",&u,&v);
            G[u].pb(v);
            G[v].pb(u);
            deg[u]++; deg[v]++;
        }

        int rt=solve();
        cout<<rt<<endl;
    }
    return 0;
}

