#define N 200005
int n,head[N],fa[N],cnt,rt,d[N],f[N],ans[N],tot;
struct edge{ int to,nxt; }e[N<<1];
void adde(int x,int y){
	e[++cnt].to=y; e[cnt].nxt=head[x]; head[x]=cnt;
}
void ins(int x,int y){
	adde(x,y); adde(y,x); d[x]++,d[y]++;
}
void dfs(int u){
	for (int i=head[u],v; i; i=e[i].nxt) if ((v=e[i].to)!=fa[u]){
		dfs(v); if (!f[v]) d[u]--;
	}
	f[u]=d[u]&1;
}
void dfs2(int u){
	for (int i=head[u],v; i; i=e[i].nxt) if ((v=e[i].to)!=fa[u]){
		if (!f[v]) dfs2(v);
	}
	ans[++tot]=u;
	for (int i=head[u],v; i; i=e[i].nxt) if ((v=e[i].to)!=fa[u]){
		if (f[v]) dfs2(v);
	}
}
