const int N = 2e6 + 7;
const int M = 1e9 + 7;

int n, k, l, x[N];
int dp[N];
int cnt[N];
int cnt2[N];
string s;

pair<int,int> solve(int delta){
    for (int i = 1; i <= n; i++){
        int p = max(0, i - l);
        if (dp[p] + delta <= dp[i - 1] + x[i]) cnt[i] = cnt[p] + 1, dp[i] = dp[p] + delta;
        else cnt[i] = cnt[i - 1], dp[i] = dp[i - 1] + x[i];
    }
    for (int i = 1; i <= n; i++){
        int p = max(0, i - l);
        if (dp[p] + delta < dp[i - 1] + x[i]) cnt2[i] = cnt2[p] + 1, dp[i] = dp[p] + delta;
        else cnt2[i] = cnt2[i - 1], dp[i] = dp[i - 1] + x[i];
    }
    return {dp[n] - min(cnt[n], k)*delta, cnt2[n]};
}

