bool gaosm(int S,int v,int dep) {
	if (S==0) return v==0;
	rep(j,0,n) if ((S&(1<<j))&&v>=a[j]&&sm[S^(1<<j)][v-a[j]]) {
		lev[j]=dep;
		return gaosm(S^(1<<j),v-a[j],dep);
	}
	return gaosm(S,v*k,dep+1);
}

