            while (j < sz && s[j] == s[i]) {
                j++;
            }
            if (i == 0 || j == sz) {
                i = j;
                continue;
            }
            int q1 = s[i - 1] - 'a', q2 = s[j] - 'a';
            if (m[q1][q2] != 1) {
                return false;
            }
            i = j;
        } else {
            if (i != 0 && s[i - 1] != p + 'a') {
                int q1 = s[i] - 'a', q2 = s[i - 1] - 'a';
                if (m[q1][q2] != 1) {
                    return false;
                }
