    @staticmethod

    def st(x):

        return sys.stdout.write(str(x) + '\n')



    @staticmethod

    def lst(x):

        return sys.stdout.write(" ".join(str(w) for w in x) + '\n')



    @staticmethod

    def bootstrap(f, stack=[]):

        def wrappedfunc(*args, **kwargs):

            if stack:

                return f(*args, **kwargs)

            else:

                to = f(*args, **kwargs)

                while True:

                    if isinstance(to, GeneratorType):

                        stack.append(to)

                        to = next(to)

                    else:

                        stack.pop()

                        if not stack:

                            break

                        to = stack[-1].send(to)

                return to

        return wrappedfunc





