using namespace std;



typedef long long ll;

typedef long double ld;

const ll N = 505;

const ll mod = 1e9 + 7;

ll pos[N];

ll id = 0;

ll cut[N];

ll mth[N];



void solve(){

    id = 0;

    pos[0] = -N;

    memset(cut, 0x3f, sizeof(cut));

    memset(mth, 0, sizeof(mth));

    mth[0] = 1;

    cut[0] = 0;

    string s, t; cin>>s>>t;

    ll n = s.length(), m = t.length();

    size_t found = s.find(t);

    while(found != string::npos){

        pos[++id] = found + 1;

        found = s.find(t, found + 1);

    }pos[++id] = m + n;

    for(ll i=0; i<id; i++){

        ll j = i + 1;

        while(j<=id && pos[j]<=(pos[i] + m - 1)) j++;

        for(ll k=j; pos[k]<=(pos[j] + t.length() - 1) && k<=id; k++){

            if(cut[i] + 1 < cut[k]){

                cut[k] = cut[i] + 1;

                mth[k] = mth[i];

            }else if(cut[i] + 1 == cut[k]){

                mth[k] = (mth[k] + mth[i])%mod;

            }

        }

    }cout<<cut[id] - 1<<" "<<mth[id];

    return;

}



