const int N = 1e5 + 5, hN = N;

std::vector<int> g[N], dg[N], nodeAt[N];

int parent[N], depth[N], subSz[N];

bool vis[N];

int chNo = 0, chHead[hN], chPos[hN], chInd[hN], chSz[hN];



void dfs(int v, int p){

	depth[v] = depth[p] + 1;

	subSz[v] = 1; parent[v] = p;

	vis[v] = true;

	for(int u : g[v]) if(!vis[u]){

		dfs(u, v);

		dg[v].pb(u);

		subSz[v] += subSz[u];

	}

}



void hld(int v){

	if(chHead[chNo] == -1) chHead[chNo] = v;

	chInd[v] = chNo;

	nodeAt[chNo].pb(v);

	chPos[v] = chSz[chNo]++;

	int next = 0;

	for(int u : dg[v]) next = subSz[u] > subSz[next] ? u : next;

	if(next) hld(next);

	for(int u : dg[v]){

		if(u != next){

			chNo++;

			hld(u);

		}

	}

}



int lca(int u, int v){

	if(chInd[u] == chInd[v]) return depth[u] < depth[v] ? u : v;

	int uh = chHead[chInd[u]], vh = chHead[chInd[v]];

	return depth[uh] < depth[vh] ? lca(u, parent[vh]) : lca(parent[uh], v);

}



int dist(int u, int v){

	return depth[u] - depth[v];

}



int childHaving(int u, int v){

	if(chInd[u] == chInd[v]) return nodeAt[chInd[v]][chPos[v] + 1];

	int uh = chHead[chInd[u]], vh = chHead[chInd[v]];

	if(parent[uh] == v) return uh;

	return childHaving(parent[uh], v);

}



int halfAnc(int u, int d){

	int uh = chHead[chInd[u]];

	if(depth[u] - depth[uh] < d) return halfAnc(parent[uh], d - depth[u] + depth[uh] - 1);

	return nodeAt[chInd[u]][chPos[u] - d];

}



int main()

{

	int n, m, i, u, v, shit;

	in(n);

	fill(chHead, -1); fill(chSz, 0); fill(vis, false);

	rep(i, 1, n){

		in(u); in(v);

		g[u].pb(v); g[v].pb(u);

	}

	depth[0] = 0;

	dfs(1, 0);

	hld(1);

	in(m); while(m--){

		in(u); in(v);

		if(u == v) shit = n;

		else{

			int mom = lca(u, v), d1 = dist(u, mom), d2 = dist(v, mom), d = d1 + d2;

			if(d & 1) shit = 0;

			else if(d1 == d2){

				shit = n;

				shit -= subSz[childHaving(u, mom)] + subSz[childHaving(v, mom)];

			}else{

				d >>= 1; d--;

				if(depth[v] > depth[u]) swap(u, v);

				int ha = halfAnc(u, d), pha = parent[ha];

				shit = subSz[pha] - subSz[ha];

			}

		}

		printf("%d\n", shit);

	}



	return 0;

}

