int n, h[_];

int solve(int l, int r, int H)
{
	if(l == r) return h[l] ? 1 : 0;
	int mn = LLONG_MAX, res = 0;
	for(int i = l; i <= r; ++i) mn = min(mn, h[i]);
	res += mn - H;
	int p;
	for(int i = l; i <= r; i = p + 1)
	{
		p = i;
