	if(id>a||id<a-p+1)return false;

	int R=(id+p)/p*p;

	if(R>a||R<a-p+1)return false;

	return true;

}

bool judge2(int id,int a){

	if(id>a||id<a-p+1)return false;

	int L=id/p*p;

	if(L>a||L<a-p+1)return false;

	return true;

