int Grandi(int k) {
   if (dp[k] != -1) return dp[k];
   vi nxt;
   for (int i = 2 ;; i++) {
      int N = k;
      int sum = S[i];
      if (sum >= N) break;
      N -= sum;
      if (N % i != 0) continue;
      int d0 = N/i;
      int g = 0;
