void solve() {
  LL(N, K);
  vv(mint, DP, 16, K + 1);

  auto upd0 = [&]() -> void {
    FOR(d, 4) {
      FOR_R(k, K) FOR(s, 16) {
        ll t = s | 1 << d;
        if (s == t) continue;
        DP[t][k + 1] += DP[s][k];
      }
    }

    FOR(d, 4) {
      ll x = 1 << d | 1 << ((d + 1) % 4);
      FOR_R(k, K) FOR(s, 16) {
        if (s & x) continue;
        ll t = s | x;
        DP[t][k + 1] += DP[s][k];
      }
    }
  };

  auto upd1 = [&]() -> void {
    // 正方形の角にあたる部分
    FOR(d, 4) {
      FOR_R(k, K) FOR(s, 16) {
        ll t = s | 1 << d;
        DP[t][k + 1] += DP[s][k];
      }
    }
  };

  auto upd2 = [&]() -> void {
    // 上下左右の 2 個ずつ
    FOR(d, 4) {
      ll a = d, b = (d + 1) % 4;
      FOR_R(k, K) FOR(s, 16) {
        ll t = s | 1 << a;
        DP[t][k + 1] += DP[s][k];
        t = s | 1 << b;
        DP[t][k + 1] += DP[s][k];
        t = s | 1 << a | 1 << b;
        DP[t][k + 1] += DP[s][k];
        if (k + 2 <= K) DP[t][k + 2] += DP[s][k];
      }
    }
  };

  DP[0][0] = 1;
  upd0();
  FOR(_, N) {
    upd1();
    upd2();
    upd0();
  }

  mint ANS = 0;
  FOR(s, 16) { ANS += DP[s][K]; }
  FOR3(k, 1, K + 1) ANS *= k;
  print(ANS);
}

