        d[u] = f[u] = 1;
        p[u] = h[u];
        return;
    }
    int tmp = 0;
    p[u] = n;
    for (int i = 0; i < (int)a[u].size(); i++)
    {
        int v = a[u][i];
        h[v] = h[u] + 1;
        dfs(v);
        if (p[v] - h[u] <= k)
        {
            p[u] = min(p[u],p[v]);
            d[u] += d[v];
        }
    }
    for (int i = 0 ; i < (int)a[u].size(); i++)
    {
        int v = a[u][i];
        if (p[v] - h[u] <= k) f[u] = max(f[u],d[u] - d[v] + f[v]); else f[u] = max(f[u],d[u] + f[v]);
    }
}

