const int inf = 0x3f3f3f3f;

const int MOD = 1e9 + 7;

const int maxn = 1e5 + 10;

const int maxv = 1e2 + 10;

const double eps = 1e-9;



ll n, m, res;

ll maxprime[maxn];

ll primes[30];

ll fac[maxn];

ll facv[maxn];

int tot;

void exgcd(ll a, ll b, ll& d, ll& x, ll& y) {

	if(!b) {d = a; x = 1; y = 0;}

	else {exgcd(b, a%b, d, y, x); y -= x * (a / b);}

}

ll inv(ll a, ll n) { //mod n aµÄÄæ

	ll d, x, y;

	exgcd(a, n, d, x, y);

	return d == 1 ? (x + n) % n : -1;

}

void init() {

    CLR(maxprime);

    for(int i = 2; i <= 1e5; i++) {

        if(!maxprime[i]) {

            for(int j = i; j <= 1e5; j += i) {

                maxprime[j] = i;

            }

        }

    }

    fac[0] = facv[0] = 1;

    for(ll i = 1; i <= 1e5; i++) {

        fac[i] = fac[i-1] * i % MOD;

        facv[i] = facv[i-1] * inv(i, MOD) % MOD;

    }

}

ll F(ll k) {

    ll tmp = n / k;

    if(tmp < m) return 0;

    return fac[tmp-1] * facv[tmp-m] % MOD * facv[m-1] % MOD;

}

void dfs(int now, ll cur, int jud) {

    if(now == tot) {

        if(jud & 1) res = (res + F(cur)) % MOD;

        else res = (res - F(cur) + MOD) % MOD;

        return;

    }

    dfs(now+1, cur, jud);

    dfs(now+1, cur*primes[now], jud^1);

}

void div(ll tmp) {

    while(tmp != 1) {

        primes[tot++] = maxprime[tmp];

        while(tmp % primes[tot-1] == 0) {

            tmp /= primes[tot-1];

        }

    }

}

