int Find_max(int x,int y)

{

    int Max = 0;

    int Pos = -1;

    rep(i,x,y) if (Max < a[i])

    {

        if ((i > x && a[i] > a[i-1]) ||

            (i < y && a[i] > a[i+1])) {Max = a[i]; Pos = i;}

    }

    return Pos;

}



void label1(int p,int be,int x, int y,int z)

{

    repd(i,z-p,be+1)

    {

        r1[++c] = i;

        r2[c] = 'L';

    }

    rep(i,1,y-z)

    {

        r1[++c] = be;

        r2[c] = 'R';

    }

}



void label2(int p,int be,int x, int y,int z)

{

    rep(i,1,y-z)

    {

        r1[++c] = z-p;

        r2[c] = 'R';

    }

    repd(i,z-p,be+1)

    {

        r1[++c] = i;

        r2[c] = 'L';

    }

}



void Try(int p,int be,int x, int y)

{

    int z; // the position have max value

    z = Find_max(x,y);

    if (z == -1) {stop =1; return;}

    if (z > x && a[z] > a[z-1]) label1(p,be,x,y,z);

    else label2(p,be,x,y,z);

}



void solve()

{

    int fi = 1,se = 0, cnt = 0;

    rep(i,1,k)

    {

        int s = 0;

        se = fi;

        while (s < b[i] && se <=n) s+=a[se++];

        if (s!=b[i]) {

            cout << "NO"; return;

        }

        se--;

        if (se > fi) Try(cnt,i,fi,se);

        if (stop) {cout << "NO"; return;}

        cnt += se - fi;

        fi = se +1 ;

    }

    if (se<n) cout << "NO"; else

    out();

}



int main()

{

