using namespace std;

vector<vector<pair<long long, long long> > > edges(100000);
long long kek, dp[100000];
long long d = 1, b[100000];
pair<long long, long long> tr[1 << 19];
bool used[100000];

struct trio
{
    long long k, tim, ind;
    trio() {};
    bool operator < (trio q)
    {
        if (tim != q.tim)
        {
            return tim <= q.tim;
        }
        return ind < q.ind;
    }
};

vector<trio> a;

void add(long long v)
{
    long long now = b[v] + d;
    while (now)
    {
        tr[now].first += a[b[v]].tim * a[b[v]].k;
        tr[now].second += a[b[v]].k;
        now /= 2;
    }
}

void del(long long v)
{
    long long now = b[v] + d;
    while (now)
    {
        tr[now].first -= a[b[v]].tim * a[b[v]].k;
        tr[now].second -= a[b[v]].k;
        now /= 2;
    }
}

long long get_ans(long long t)
{
    long long ans = 0;
    long long v = 1;
    if (tr[v].first <= t)
    {
        return tr[v].second;
    }
    while (1)
    {
        if (v >= d)
        {
            if (tr[v].first == 0)
            {
                return ans;
            }
            return ans + min(t / (tr[v].first / tr[v].second), tr[v].second);
        }
        if (tr[2 * v].first <= t)
        {
            ans += tr[2 * v].second;
            t -= tr[2 * v].first;
            v = 2 * v + 1;
        }
        else
        {
            v *= 2;
        }
    }
}

void dfs(long long v, long long t)
{
    long long max1 = 0, max2 = 0;
    dp[v] = get_ans(t);
    //cout << v << ") " << dp[v] << '\n';
    used[v] = true;
    for (long long i = 0; i < edges[v].size(); i++)
    {
        if (!used[edges[v][i].first])
        {
            add(edges[v][i].first);
            dfs(edges[v][i].first, max(t - 2 * edges[v][i].second, (long long)(0)));
            del(edges[v][i].first);
            if (dp[edges[v][i].first] >= max1)
            {
                max2 = max1;
                max1 = dp[edges[v][i].first];
            }
            else if (dp[edges[v][i].first] >= max2)
            {
                max2 = dp[edges[v][i].first];
            }
        }
    }
    if (v)
    {
        dp[v] = max(dp[v], max2);
    }
    else
    {
        dp[v] = max(dp[v], max1);
    }
}

