#include<bits/stdc++.h>

using namespace std;

typedef long long ll;

const int maxn=1e5+30;

int a[maxn];

int main(){

	ios::sync_with_stdio(false);

	cin.tie(nullptr);

	cout.tie(nullptr);

	int n;

	cin>>n;

	for(int i=1;i<=n;i++)	cin>>a[i];

	int x=-1,y=-1;//a(0)最后一个元素为x，a(1)最后一个元素为y; 

	int ans=0;

	for(int i=1;i<=n;i++){

		int z1=a[i],z2=a[i+1];//当前准备去分配的元素为z1，下一个要分配的元素为z2; 

		if(z1==x&&z1==y)	continue;

		if(z1==x){

			y=z1;//不用给x; 

			ans++;

		}

		else if(z1==y){

			x=z1;//不用给y; 

			ans++;

		}

		else{

			ans++;

			if(z2==x&&z2!=y){//下个要选的和a(0)最后一个元素相同 

				x=z1;

			} 

			else if(z2==y&&z2!=x){//下个要选的和a(1)最后一个元素相同 

				y=z1;

			}

			else	x=z1;

		}

	}

	cout<<ans<<endl;

