ll solve(ll n, ll ind, ll rem, ll u, ll z) {

	//trace(ind, rem);

	if(rem<0) return 0;

	if(ind<0) return 1;

	if(rem>2000) rem = 2000;

	if(dp[ind][rem]!=-1) return dp[ind][rem];



	ll ans = 0;

	for(int i=((z&(1LL<<ind))==0)?0:1; i<=n; i+=2) {

		ll to_add = (u&(1LL<<ind))==0?0:1;

		ll nxt_rem = 2*(rem+to_add-i);

		ll cur_ans = comb(n,i)*solve(n, ind-1, nxt_rem, u, z);

		cur_ans %= mod;

		ans += cur_ans;

		ans %= mod;

	}

	return dp[ind][rem] = ans;

}





