ll mPow(ll base, ll exponent, ll moduloNumber) {

	base %= moduloNumber;

	ll basePowerExponent = 1;

	while (exponent > 0) {

		if (exponent & 1) {

			basePowerExponent = (basePowerExponent * base) % moduloNumber;

		}

		base = (base * base) % moduloNumber;

		exponent >>= 1;

	}

	return basePowerExponent;

}



ll extGcd (ll numberA, ll numberB, ll &coeffA, ll &coeffB){

    ll x2, y2, x1, y1, x, y, r2, r1, q, r;

    x2 = 1; y2 = 0;

    x1 = 0; y1 = 1;

    for (r2 = numberA, r1 = numberB; r1 != 0; r2 = r1, r1 = r, x2 = x1, y2 = y1, x1 = x, y1 = y ) {

        q = r2 / r1;

        r = r2 % r1;

        x = x2 - (q * x1);

        y = y2 - (q * y1);

    }

    coeffA = x2; coeffB = y2;

    return r2;

}



