struct Dfs {

  const int n;

  const G &g;



  vector<int> parent, depth;



  Dfs(const G &g) : n(g.size()), g(g), parent(n), depth(n) {}



  void visit(int u, int p) {

    for (int v : g[u]) {

      if (v == p)

        continue;



      depth[v] = depth[u] + 1;

      parent[v] = u;

      visit(v, u);

    }

  }

};



enum class Color {

  NEW,

  INTERMEDIATE,

  FINAL,

};



int solve(const G &g) {

  const int n = g.size();



  Dfs dfs(g);

  dfs.visit(n-1, n-1);



  int best = 0;

  for (int u = 0; u < n; ++u)

    if (g[u].size() == 1)

      best = u;



  if (n % 2 == 0)

    return n - 1;



  for (int v = n - 1; v >= 0; --v)

    if (dfs.depth[v] % 2)

      best = max(best, v);



  int leaves = 2, inner = 1;

  vector<Color> cs(n);

  vector<bool> is_leaf(n);



  is_leaf[n - 2] = true;

  is_leaf[n - 1] = true;



  for (int v = n - 2; v != n - 1; v = dfs.parent[v]) {

    cs[v] = Color::INTERMEDIATE;

    ++inner;

  }



  cs[n - 2] = Color::FINAL;

  cs[n - 1] = Color::FINAL;



  for (int v = n - 3; v >= best; --v) {

    if (cs[v] == Color::INTERMEDIATE) {

      cs[v] = Color::FINAL;

      continue;

    }



    int p;

    for (p = dfs.parent[v]; cs[p] == Color::NEW; p = dfs.parent[p]) {

      ++inner;

      cs[p] = Color::INTERMEDIATE;

    }



    if (is_leaf[p] == true) {

      is_leaf[p] = false;

      --leaves;

    }



    ++inner;

    ++leaves;

    is_leaf[v] = true;

    cs[v] = Color::FINAL;



    if ((inner + leaves) % 2 != n % 2) {

      D {

        break;

        cerr << "at vertex " << v << " inner: " << inner << " leaves: " << leaves << '\n';

      }

      best = max(best, v);

    }

  }



  return best;

}



constexpr const int N = 9;



bool is_leaf(int u, const G &g, const bitset<N> &alive) {

  int neighbours = 0;

  for (int v : g[u])

    if (alive[v])

      ++neighbours;

  return neighbours == 1;

}



int stupid(const G &g, bitset<N> alive, bool alice) {

  const int n = g.size();



  if (alive.count() == 1) {

    if (alice) {

      for (int u = 0; u < n; ++u)

        if (alive[u])

          return u;

    } else {

      return 0;

    }

  }



  int answer = alice ? 0 : n;

  for (int u = 0; u < n; ++u) {

    if (alive[u] && is_leaf(u, g, alive)) {

      alive[u] = false;

      if (alice) {

        answer = max({

          answer,

          u,

          stupid(g, alive, !alice),

        });

      } else {

        answer = min({

          answer,

          stupid(g, alive, !alice),

        });

      }

      alive[u] = true;

    }

  }

  return answer;

}



int stupid(const G &g) {

  const int n = g.size();

  bitset<N> alive;



  for (int u = 0; u < n; ++u)

    alive[u] = true;



  return stupid(g, alive, true);

}



