ll gcd(ll a, ll b) 
{ 
    if (a == 0) return b; 
    return gcd(b%a, a); 
}

ll power(ll x, ll y, ll m) 
{ 
    if (y == 0) 
        return 1; 
    ll p = power(x, y/2, m) % m; 
    p = (p * p) % m; 

    return (y%2 == 0)? p : (x * p) % m; 
}

ll modInverse(ll a, ll m) 
{ 
    ll g = gcd(a, m); 
    if (g != 1) return -1;
    else
    {
        return power(a, m-2, m); 
    } 
} 

ll factorial(ll n) 
{
    return (n==1 || n==0) ? 1: (n * factorial(n - 1))%1000000007;  
} 

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    ll k = 1000000007;
