    cin>>n>>m;
    ll a = factorial((2*m)+n-1);
    ll b = factorial(n-1);
    ll c = factorial(2*m);
    b = modInverse(b,1000000007);
    c = modInverse(c,1000000007);
    ll ans = (a*b)%1000000007;
    ans = (ans*c)%1000000007;
    cout<<ans<<endl;
}

