constexpr int MOD = 998244353;

ll modPow(ll a, ll e, ll m) {
    ll t = 1 % m;
    while (e) {
        if (e % 2) t = t*a % m;
        e /= 2; a = a*a % m;
    }
    return t;
}

struct Zp {
    ll x;
    Zp() : x(0) {}
    Zp(ll a) : x(a%MOD) { if (x < 0) x += MOD; }
    #define OP(c,d) Zp& operator c##=(Zp r) { x = x d; return *this; } Zp operator c(Zp r) const { Zp t = *this; return t c##= r; }
    OP(+, +r.x - MOD*(x+r.x >= MOD));
    OP(-, -r.x + MOD*(x-r.x < 0));
    OP(*, *r.x % MOD);
    OP(/, *r.inv().x % MOD);
    Zp operator-() const { return Zp()-*this; }
    Zp inv() const { return pow(MOD-2); }
    Zp pow(ll e) const{ return modPow(x,e,MOD); }
    void print() { cerr << x; }
};

template<ll M, ll R, bool dit>
void ntt(vector<ll>& a) {
    static vector<ll> w(2, 1);
    int n = sz(a);

    for (int k = sz(w); k < n; k *= 2) {
        w.resize(n, 1);
        ll c = modPow(R, M/2/k, M);
        if (dit) c = modPow(c, M-2, M);
        rep(i, k+1, k*2) w[i] = w[i-1]*c % M;
    }

    for (int t = 1; t < n; t *= 2) {
        int k = (dit ? t : n/t/2);
        for (int i=0; i < n; i += k*2) rep(j,0,k) {
            ll &c = a[i+j], &d = a[i+j+k];
            ll e = w[j+k], f = d;
            d = (dit ? c - (f=f*e%M) : (c-f)*e % M);
            if (d < 0) d += M;
            if ((c += f) >= M) c -= M;
        }
    }
}

template<ll M = (119<<23)+1, ll R = 62>
void convolve(vector<ll>& a, vector<ll> b) {
    int len = sz(a) + sz(b) - 1;
    if (len <= 0) return a.clear();
    int n = 2 << __lg(len);
    ll t = modPow(n, M-2, M);
    a.resize(n); b.resize(n);
    ntt<M,R,0>(a); ntt<M,R,0>(b);
    rep(i, 0, n) a[i] = a[i]*b[i] % M * t % M;
    ntt<M,R,1>(a);
    a.resize(len);
}

int n;
vector<Zp> fac, facInv, dp;

/*
dp[2] = 1;
rep(i, 3, n+1) {
    rep(j, 2, i-1) {
        dp[i] += dp[j] * dp[i-j] * choose(i-1, j-1) * 2;
    }
    dp[i] += dp[i-1] * (i+1);
}
