void solve(int b, int e) {
    if (e-b <= 1) {
        if (e-b <= 0) return;
        if (b == 2) {
            dp[b] = 1;
        } else {
            dp[b] += dp[b-1] * (b+1);
        }
        return;
    }

    int m = (b+e+1) / 2;

    solve(b, m);

    vector<ll> P, Q;
    rep(i, b, m) P.pb((dp[i] * facInv[i-1]).x);
    rep(i, 0, min(m, e-b)) Q.pb((dp[i] * facInv[i]).x);
    convolve(P, Q);

    rep(i, m-b, min(sz(P), e-b)) {
        dp[i+b] += Zp(P[i]) * fac[i+b-1] * 2;
    }

    P.clear();
    Q.clear();
    rep(i, b, m) P.pb((dp[i] * facInv[i]).x);
    rep(i, 0, min(b, e-b)) Q.pb((dp[i] * facInv[i-1]).x);
    convolve(P, Q);

    rep(i, m-b, min(sz(P), e-b)) {
        dp[i+b] += Zp(P[i]) * fac[i+b-1] * 2;
    }

    solve(m, e);
}

void run() {
    cin >> n;

    fac.resize(n+1);
    facInv.resize(n+1);
    fac[0] = facInv[0] = 1;

    rep(i, 1, n+1) {
        fac[i] = fac[i-1] * i;
        facInv[i] = fac[i].inv();
    }

    dp.resize(n+1);
    solve(2, n+1);

    Zp ans = dp[n]*2 - 2;
    cout << ans.x << '\n';
}

