  }
  vector<int> pref(n + 1);
  for (int i = 0; i < n; i++) {
    pref[i + 1] = pref[i] + (s[i] == '?');
  }
  vector<int> pref_open(n + 1);
  for (int i = 0; i < n; i++) {
    pref_open[i + 1] = pref_open[i] + (s[i] == '(');
  }
  vector<Mint> fact(n + 1);
  fact[0] = 1;
  for (int i = 1; i <= n; i++) {
    fact[i] = fact[i - 1] * i;
  }
  vector<Mint> inv_fact(n + 1);
  for (int i = 0; i <= n; i++) {
    inv_fact[i] = 1 / fact[i];
  }
  auto C = [&](int N, int K) {
    if (K < 0 || K > N) return Mint(0);
    return fact[N] * inv_fact[K] * inv_fact[N - K];
  };
