using namespace std;

using i64 = long long;

i64 n, q, a[100005], suf1[100005][320], suf2[100005][320];

void solve() 
{
	int n, q;
	cin >> n >> q;
	for (int i = 1; i <= n; i++)
	{
		cin >> a[i];
	}
	int x = sqrtl(n);
	for (int i = n; i >= 1; i--)
	{
		for (int j = 1; j <= x; j++)
		{
			suf1[i][j] = suf1[i + j][j] + a[i];
		}
	}
	for (int i = n; i >= 1; i--)
	{
		for (int j = 1; j <= x; j++)
		{
			suf2[i][j] = suf2[i + j][j] + suf1[i][j];
		}
	}
	while (q--)
	{
		i64 s, d, k;
		cin >> s >> d >> k;
		i64 ans = 0;
		if (d >= x)
		{
			for (i64 i = 1; i <= k; i++)
			{
				ans += a[s + (i - 1) * d] * i;
			}
		}
		else
		{
			ans = suf2[s][d] - suf2[s + k * d][d] - k * suf1[s + k * d][d];
		}
		cout << ans << " \n"[q == 0];
	}
} 

