bool done[200001];

int first[200001];

int last[200001];

int h[200001];

int cnt;

void dfs(int u) {

    done[u] = 1;

    first[u] = ++cnt;

    for (int i = 0; f[f[u][i]][i]; i++) f[u][i + 1] = f[f[u][i]][i];

    for (auto&& v : g[u])

        if (done[v]) {

            swap(v, g[u].back());

            g[u].pop_back();

            break;

        }

    for (auto&& v : g[u]) {

        f[v][0] = u;

        h[v] = h[u] + 1;

        dfs(v);

    }

    last[u] = cnt;

}

int w[200002];

void ban(int u, int v) {

    w[u]++;

    w[v + 1]--;

}

void solve() {

    cin >> n;

    for (int i = 1; i <= n; i++) {

        cin >> a[i];

        group[a[i]].emplace_back(i);

    }

    for (int i = 1, u, v; i < n; i++) {

        cin >> u >> v;

        g[u].emplace_back(v);

        g[v].emplace_back(u);

    }

    h[1] = 1;

    dfs(1);

    for (auto&& [value, pos] : group) {

        if (pos.size() <= 1) continue;

        sort(pos.begin(), pos.end(), [](const int& a, const int& b) { return h[a] > h[b]; });

        int low = n + 1, high = 0;

        for (auto&& x : pos) {

            low = min(low, first[x]);

            high = max(high, first[x]);

        }

        set<pair<int, int>> current;

        for (auto&& x : pos) {

            if ((first[x] > low) || (last[x] < high)) ban(first[x], last[x]);

            else ban(first[x], first[x]);

            while (!current.empty()) {

                if (current.rbegin()->first < first[x]) break;

                auto [p, y] = *current.lower_bound({first[x], x});

                if (p > last[x]) break;

                current.erase({p, y});

                for (int i = __lg(h[y]); i >= 0; i--)

                    if (h[f[y][i]] > h[x]) y = f[y][i];

                ban(1, first[y] - 1);

                ban(last[y] + 1, n);

            }

            current.insert({first[x], x});

        }

    }

    int ans = 0;

    for (int i = 1; i <= n; i++) {

        w[i] += w[i - 1];

        ans += (w[i] == 0);

    }

    cout << ans << '\n';

}



