		fo(i, 0, M) fo(j, 0, M) fo(k, 0, M) c.a[i][j] = (c.a[i][j] + (LL)a.a[i][k] * b.a[k][j]) % mod;

		return c;

	}



	friend mat operator ^ (mat a, LL k) {

		mat ans;

		fo(i, 0, M) ans.a[i][i] = 1;

		while(k) {

			if(k & 1) ans = ans * a;

			a = a * a, k >>= 1;

		} return ans;

	}

};

LL L[N], R[N], b[N], a[N];

int d[N];



int solve(int l, int r) {

	fo(i, l + 1, r) {

		if(L[i] < R[i]) L[i]++;

		else L[i]--;

	} int tp = 0;

	fo(i, l, r) {

		if(L[i] > L[l]) b[++tp] = L[i] - 1;

		b[++tp] = L[i], b[++tp] = L[i] + 1;

		if(R[i] > L[l]) b[++tp] = R[i] - 1;

		b[++tp] = R[i], b[++tp] = R[i] + 1;

	} sort(b + 1, b + tp + 1);

	tp = unique(b + 1, b + tp + 1) - (b + 1);

	M = r - l + 1;

	mat ans; ans.a[0][0] = 1;

	LL lst = b[1] - 1;

	fo(i, 1, tp - 1) {

		mat tmp;

		fo(j, l, r) {

			if(min(L[j], R[j]) <= lst + 1 && max(L[j], R[j]) >= b[i]) {

				if(L[j] < R[j]) {

					fo(k, l - 1, j) tmp.a[k - l + 1][j - l + 1] = 1;

				} else {

					fo(k, l - 1, j - 1) tmp.a[k - l + 1][j - l + 1] = 1;

				}

			}

		} ans = ans * (tmp ^ (b[i] - lst));

		lst = b[i];

	} int sum = 0;

	fo(i, 0, M) sum = (sum + ans.a[0][i]) % mod;

	return sum;

}



