void solve()
{
    int n,k; cin>>n>>k;
    int p[n]; for(auto &i:p) cin>>i;
    int q[k]; 
    ordered_set<ll>st;
    ll NOI = 0;
    for(auto &i:q)
    {
        cin>>i;

        NOI += st.order_of_key(i);

        st.insert(i);
    }
    st.clear();
    ll ans = 0;

    int mx = 0;

    for(int j=0; j<n; ++j)
    {
        for(int y=0; (1ll<<y)<mx and y<k;++y)
        {
            ll val = (1ll<<y)*p[j];
            ans += 1ll * (k-y) * st.order_of_key(val);
            ans  %= mod;


        }

        ll rem = k-1;
        for(int y=1; (1ll<<y)<p[j] and y<k; ++y)
        {
            ll val = p[j]/(1ll<<y);
            --rem;
            ans += 1ll * (k-y)*st.order_of_key(val);
            ans  %= mod;
        }

        ans += ((((rem*(rem+1)) / 2)%mod) *(st.size()))%mod;
        ans %= mod;

        st.insert(p[j]);
        mx = max(p[j],mx);
    }
    NOI %= mod;
    ans += (NOI*n)%mod;
    ans %= mod;

    cout<<ans<<'\n';
