namespace {

struct Solver {

  void solve(int ca, std::istream& reader) {
    int n, k;
    std::string str;
    reader >> n >> k >> str;
    std::vector<int> vec;
    auto f = [&](int i) -> int {
      int x = str[i] - 'a';
      return std::min({x, (x + 1) % k, (x + k - 1) % k});
    };
    auto g = [&](int i) -> int {
      return str[i] - 'a';
    };
    int fixed = -1;
    auto one_step = [&](int i) -> void {
      if (i + 2 < n) {
        if (fixed == -1) {
          if (f(i + 1) < f(i) && f(i + 1) <= std::min({f(i), g(i + 1), g(i + 2)})) {
            if (f(i + 1) < g(i + 1)) {
              vec.emplace_back(f(i + 1));
              fixed = g(i);
              return;
            } else {
              vec.emplace_back(g(i + 1));
              fixed = f(i);
              return;
            }
          } else if (g(i + 1) < std::min(f(i), g(i + 2))) {
            vec.emplace_back(g(i + 1));
            fixed = f(i);
            return;
          }
          fixed = f(i);
        }
        if (fixed <= std::min(g(i + 1), g(i + 2))) {
          vec.emplace_back(fixed);
          fixed = -1;
          return;
        }
        if (g(i + 1) <= std::min(fixed, g(i + 2))) {
          vec.emplace_back(g(i + 1));
          return;
        }
        vec.emplace_back(g(i + 2));
        vec.emplace_back(fixed);
        fixed = g(i + 1);
        return;
      } else if (i + 1 < n) {
        if (fixed != -1) {
          if (fixed <= std::min(g(i + 1), f(i + 1))) {
            vec.emplace_back(fixed);
            vec.emplace_back(f(i + 1));
            return;
          } else if (g(i + 1) < fixed) {
            vec.emplace_back(g(i + 1));
            vec.emplace_back(fixed);
            return;
          } else {
            vec.emplace_back(fixed);
            vec.emplace_back(f(i + 1));
          }
        } else {
          if (f(i) <= f(i + 1)) {
            vec.emplace_back(f(i));
            vec.emplace_back(f(i + 1));
            return;
          } else if (f(i + 1) < g(i + 1)) {
            vec.emplace_back(f(i + 1));
            vec.emplace_back(g(i));
            return;
          } else {
            vec.emplace_back(g(i + 1));
            vec.emplace_back(f(i));
            return;
          }
        }
      } else {  // i + 1 == n
        if (fixed == -1) {
          fixed = f(i);
        }
        vec.emplace_back(fixed);
        return;
      }
    };
    for (int i = 0; i < n; i = vec.size()) {
      one_step(i);
      DUMP(i, vec, fixed);
    }
    assert(vec.size() == n);
    for (int i = 0; i < n; ++i) {
      putchar(vec[i] + 'a');
    }
    puts("");
  }
};

