	inline comp conj() { return comp(x, -y); }
};

inline comp operator +(const comp &a, const comp &b) {
	return comp(a.x + b.x, a.y + b.y);
}

inline comp operator -(const comp &a, const comp &b) {
	return comp(a.x - b.x, a.y - b.y);
}

inline comp operator *(const comp &a, const comp &b) {
	return comp(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

inline comp operator /(const comp &a, const double &b) {
	return comp(a.x / b, a.y / b);
}

namespace FFT {
	const double PI = acosl(-1.0);
	vector<comp> w[LOGN];
	vector<int> rv;

	void precalc() {
		forn(st, LOGN) {
			w[st].resize(1 << st);
			forn(i, 1 << st) {
				double ang = PI / (1 << st) * i;
				w[st][i] = comp(cos(ang), sin(ang));
			}
		}
		rv.assign(1 << LOGN, 0);
	    fore(i, 1, sz(rv))
			rv[i] = (rv[i >> 1] >> 1) | ((i & 1) << (LOGN - 1));
	}

	inline void fft(comp a[N], int n, bool inv) {
		int ln = __builtin_ctz(n);
		forn(i, n) {
	        int ni = rv[i] >> (LOGN - ln);
	        if(i < ni) swap(a[i], a[ni]);
	    }

		for(int st = 0; st < ln; st++) {
			int len = 1 << st;
			for(int k = 0; k < n; k += (len << 1))
				fore(pos, k, k + len) {
					comp l = a[pos];
					comp r = a[pos + len] * w[st][pos - k];

					a[pos] = l + r;
					a[pos + len] = l - r;
				}
		}

		if(inv) {
			forn(i, n)
				a[i] = a[i] / n;
			reverse(a + 1, a + n);
		}
	}

	comp aa[N], bb[N], cc[N];

	inline void multiply(int a[N], int sza, int b[N], int szb, int c[N], int &szc) {
		int ln = 1;
		while(ln < (sza + szb)) // sometimes works max(sza, szb)
			ln <<= 1;

		forn(i, ln)
			aa[i] = (i < sza ? a[i] : comp());
		forn(i, ln)
			bb[i] = (i < szb ? b[i] : comp());

		fft(aa, ln, false);
		fft(bb, ln, false);

		forn(i, ln)
			cc[i] = aa[i] * bb[i];

		fft(cc, ln, true);

		szc = ln;
		forn(i, szc)
			c[i] = int(cc[i].x + 0.5);
	}
}

const int MOD = int(1e9) + 7;
int norm(int a) {
	while (a >= MOD)
		a -= MOD;
	while (a < 0)
		a += MOD;
	return a;
}
int mul(int a, int b) {
	return int(a * 1ll * b % MOD);
}

