int mu[N], minD[N];
vector<int> divs[N];

void precalcDivs(int N) {
	fore (d, 1, N) {
		for (int v = d; v < N; v += d)
			divs[v].push_back(d);
	}

	mu[1] = 1;
	fore (d, 2, N) {
		if (minD[d] == 0)
			minD[d] = d;

		if (minD[d] != minD[d / minD[d]])
			mu[d] = -mu[d / minD[d]];

		for (int v = 2 * d; v < N; v += d) {
			if (minD[v] == 0)
				minD[v] = d;
		}
	}
}

int vs[2][N], res[N], ps[N];
li mxk[N];

inline void solve() {
	FFT::precalc();

	fore (i, 0, n) {
		vs[0][v[i]] = 1;
		vs[1][v[i]] = 1;
	}
	int sz = 1 + *max_element(v.begin(), v.end());

	int szRes = 0;
	FFT::multiply(vs[0], sz, vs[1], sz, res, szRes);

	fore (i, 0, szRes) {
		if (!(i & 1) && vs[0][i >> 1] > 0)
			res[i]--;
		if (res[i] > 0) {
			ps[i] = 1;
		}
	}

	memset(vs[1], 0, sizeof vs[1]);
	fore (i, 0, n)
		vs[1][sz - 1 - v[i]] = 1;
	FFT::multiply(vs[0], sz, vs[1], sz, res, szRes);

	fore (i, sz, szRes) {
		if (res[i] > 0) {
			ps[i - sz + 1] = 1;
		}
	}

	precalcDivs(2 * sz);

	int ans = 0;
	for (int i = N - 1; i > 0; i--) {
		if (ps[i] > 0)
			mxk[i] = max(mxk[i], t * 1ll * i / (2ll * l));

		for (int d : divs[i]) {
//			ans += mu[d] * (mxk[i] / d);
			ans = norm(ans + mu[d] * int((mxk[i] / d) % MOD));
			mxk[i / d] = max(mxk[i / d], mxk[i] / d);
		}
	}
	cout << ans << endl;
}

