    for (int i = 0; i < n; i++)
    {
        a[i] = lower_bound(c, c + m, a[i]) - c;
        b[a[i]].push_back(i);
    }
    return;
}

int getDist(int x, int y)
{
    int d = (n + y - x) % n;
    if (d > n - d)
        d -= n;
    return d;
}

void restore(int v)
{
    int idx = n;
    for (int val = m - 1; val >= 0; val--)
    {
        ans[idx--] = v;

        if ((int)b[val].size() > 1)
        {
            int u = par[v][1];
            int it = 0;
            while(b[val][it] != v) it++;
            if (b[val][(it + 1) % (int)b[val].size()] == u)
            {
                while(b[val][it] != u)
                {
                    it = (it + (int)b[val].size() - 1) % (int)b[val].size();
                    ans[idx--] = b[val][it];
                }
            }
            else
            {
                while(b[val][it] != u)
                {
                    it = (it + 1) % (int)b[val].size();
                    ans[idx--] = b[val][it];
                }
            }
            v = u;
        }

        if (val == 0) break;

        v = par[v][0];
    }
    ans[0] = s;
    for (int i = 0; i < n; i++)
    {
        int x = getDist(ans[i], ans[i + 1]);
        if (x >= 0)
            printf("+%d\n", x);
        else
            printf("%d\n", x);
    }
    return;
}

