//  freopen("output.txt", "w", stdout);

    read();
    for (int i = 0; i < n; i++)
        for (int j = 0; j < 2; j++)
            dp[i][j] = INF;
    for (int x : b[0])
        dp[x][0] = abs(getDist(s, x));
    for (int val = 0; val < m; val++)
    {
        if (b[val].size() == 1)
        {
            for (int x : b[val])
            {
                dp[x][1] = dp[x][0];
                par[x][1] = x;
            }
        }
        else
        {
            for (int i = 0; i < (int)b[val].size(); i++)
            {
                for (int dx = -1; dx <= 1; dx += 2)
                {
                    int nxt = (i + dx + (int)b[val].size()) % (int)b[val].size();
                    int dist = getDist(b[val][i], b[val][nxt]);
                    if (dx < 0 && dist < 0)
                        dist += n;
                    if (dx > 0 && dist > 0)
                        dist -= n;
                    int w = dp[b[val][i]][0] + abs(dist);
                    if (w < dp[b[val][nxt]][1])
                    {
                        dp[b[val][nxt]][1] = w;
                        par[b[val][nxt]][1] = b[val][i];
                    }
                }
            }
        }

        if (val == m - 1) break;

        for (int x : b[val])
            for (int y : b[val + 1])
            {
                int w = dp[x][1] + abs(getDist(x, y));
                if (w < dp[y][0])
                {
                    dp[y][0] = w;
                    par[y][0] = x;
                }
            }
    }

    int v = b[m - 1][0];
    for (int u : b[m - 1])
        if (dp[u][1] < dp[v][1])
            v = u;
    printf("%d\n", dp[v][1]);
    restore(v);

    return 0;
}

