typedef long long llint;

const int MAX = 101;
const int mod = 1000000007;

int n, K;
llint m;

llint C[MAX][MAX];
llint pot[MAX][MAX];

llint dp[MAX][MAX*MAX];

llint power( llint a, llint p ) {
   llint ret = 1;

   for( ; p > 0; p /= 2 ) {
      if( p%2 ) ret = ret * a % mod;
      a = a * a % mod;
   }

   return ret;
}

int main( void ) {
   cin >> n >> m >> K;

   for( int i = 0; i <= 100; ++i ) {
      C[i][0] = C[i][i] = 1;
      for( int j = 1; j < i; ++j ) C[i][j] = ( C[i-1][j] + C[i-1][j-1] ) % mod;
   }

   dp[0][K] = 1;

   for( int x = 0; x < n; ++x ) {
      for( int t = 0; t <= n; ++t ) {
         pot[x][t] = power( C[n][t], (m-x-1)/n + 1 );
      }
   }

   for( int x = 0; x < n; ++x ) {
      for( int k = 0; k <= K; ++k ) {
         if( dp[x][k] == 0 ) continue;
         if( (n-x)*n < k ) continue;

         for( int t = 0; t <= n && t <= K; ++t ) {
            dp[x+1][k-t] = ( dp[x+1][k-t] + dp[x][k] * pot[x][t] ) % mod;
         }
      } 
   }

   cout << dp[n][0] << endl;

   return 0;
}

