template <class S, class T>
struct lazyst {
    int n;
    vector<S> s; S se;
    vector<T> t; T te;
    S (*f)(S, S);
    void (*g)(S&, T);
    void (*h)(T&, T);
    lazyst() {}
    lazyst(int m, S (*x)(S, S), void (*y)(S&, T), void (*z)(T&, T), S es, T et) : 
    n(2 << __lg(m)), s(2 * n, es), t(2 * n, et), se(es), te(et), f(x), g(y), h(z) {}
    lazyst(const vector<S> &a,  S (*x)(S, S), void (*y)(S&, T), void (*z)(T&, T), S es, T et) : 
    lazyst(a.size(), x, y, z, es, et) {
        for (int i = 0; i < a.size(); i++) s[i + n] = a[i];
        for (int i = n - 1; i > 0; i--) pull(i);
    }
    void upd(int i, const T &v) {
        g(s[i], v);
        h(t[i], v);
    }
    void pull(int i) {
        s[i] = f(s[i * 2], s[i * 2 + 1]);
    }
    void push(int i) {
        upd(i * 2 + 0, t[i]);
        upd(i * 2 + 1, t[i]);
        t[i] = te;
    }
    void upd(int i, int l, int r, int L, int R, const T &v) {
        if (R <= l || r <= L) return;
        if (L <= l && r <= R) {upd(i, v); return;}
        int m = (l + r) / 2;
        push(i);
        upd(i * 2 + 0, l, m, L, R, v);
        upd(i * 2 + 1, m, r, L, R, v);
        pull(i);
    }
    void set(int i, int l, int r, int p, const S &v) {
        if (l + 1 == r) {s[i] = v; return;}
        int m = (l + r) / 2;
        push(i);
        if (p < m) set(i * 2 + 0, l, m, p, v);
        else       set(i * 2 + 1, m, r, p, v);
        pull(i);
    }
    S qry(int i, int l, int r, int L, int R) {
        if (R <= l || r <= L) return se;
        if (L <= l && r <= R) return s[i];
        int m = (l + r) / 2;
        push(i);
        if (R - L == 1) {
            if (L < m) return qry(i * 2 + 0, l, m, L, R);
            else       return qry(i * 2 + 1, m, r, L, R);
        }
        return f(qry(i * 2, l, m, L, R), qry(i * 2 + 1, m, r, L, R));
    }
    void upd(int l, int r, const T &v) {
        upd(1, 0, n, l, r, v);
    }
    void set(int i, const S &v) {
        set(1, 0, n, i, v);
    }
    S get(int i) {
        return qry(1, 0, n, i, i + 1);
    }
    S qry(int l, int r) {
        return qry(1, 0, n, l, r);
    }
};
