    int timer = 0;
    function<void(int)> dfs = [&](int x) {
        l[x] = timer++;
        sa.emplace_back(a[x], x);
        for (int y : adj[x]) {
            if (y == par[x]) continue;
            par[y] = x;
            a[y] = a[x] + 1;
            dfs(y);
        }
        r[x] = timer;
    };
    dfs(0);
    vector<int> vis(n);
    vis[0] = 1;
    lazyst<S, int> s(sa, f, g, h, S{-1, -1}, 0);
