				sv.push_back(tv.back());
				tv.pop_back();
				tv.pop_back();
				tv.pop_back();
			}
		}
		else if (tv.size() == 1) {
			if (sv.size() % 2 == 0) { 
				ans.emplace_back(sv.back() + sv[sv.size() - 2], tv.back());
				if (sv.size() > 2)
					sv[sv.size() - 3] += tv.back();
				tv.pop_back();
