				tv.push_back(sv.back());
				sv.pop_back();
				sv.pop_back();
				sv.pop_back();
			}
		}
		else if (sv.size() % 2 == tv.size() % 2) {
			ans.emplace_back(sv.back(), tv.back());
			tv[tv.size() - 2] += sv.back();
			sv[sv.size() - 2] += tv.back();
