				tv.pop_back();
				tv.push_back(sv.back());
				sv.pop_back();
				sv.pop_back();
			}
		}
	}
	if (sv.empty()) {
		if (tv.size() == 1) {
			ans.emplace_back(0, tv.back());
		}
		else if (tv.size() == 2) {
			ans.emplace_back(0, tv.back() + tv[tv.size() - 2]);
