typedef long long ll;
#define MOD 1000000007ll

int N;
vector <int> graph[100010];

int deg[100010];
int sum[100010];
ll dpa[100010],dpb[100010];

ll power(ll x, ll n){
	if(n == 0) return 1;
	ll y = power(x, n/2);
	y = y * y % MOD;
	if(n%2 == 1) y = y * x % MOD;
	return y;
}

void dfs(int p, int x){
	int i;

	if(deg[x] == 1){
		dpa[x] = dpb[x] = 0;
		return;
	}

	ll A = 0, B = 0;
	int K = 0;

	REP(i,graph[x].size()){
		int y = graph[x][i];
		if(y == p) continue;
		K++;
		dfs(x, y);
		A = (A + dpa[y]) % MOD;
		B = (B + dpb[y]) % MOD;
	}

	int K2 = K + 1;
	if(x == 0) K2--;

	dpa[x] = power((K2 - A + MOD) % MOD, MOD - 2);
	dpb[x] = (B + sum[x]) * dpa[x] % MOD;

//	cout << x << ' ' << A << ' ' << B << ' ' << K << ' ' << dpa[x] << ' ' << dpb[x] << endl;
}

