		graph[a].push_back(b);
		graph[b].push_back(a);
		deg[a]++;
		deg[b]++;
		sum[a] += c;
		sum[b] += c;
	}

	dfs(-1, 0);

	cout << dpb[0] << endl;

	return 0;
}

