            cnt_a[i] = cnt_a[i - 1] + (a[i] > b[i]);
            cnt_b[i] = cnt_b[i - 1] + (b[i] > a[i]);
            pref_m[i] = pref_m[i - 1] + max(a[i], b[i]);
        }
        for (int i = 1; i <= k; i++) {
            int ca = (a[i] > b[i]);
            int cb = (b[i] > a[i]);
