				int d1=max( min(down[i+1][l][1],down[i+1][r][0]) , min(down[i+1][l][0],down[i+1][r][1]) );

				if(u0>=2&&d0>=1)ans=max(ans,r-l-1+2*(u0+d0));

				if(!M&&u1>=2&&d0>=1)ans=max(ans,r-l-1+2*(u1+d0));

				if(!M&&u0>=2&&d1>=1)ans=max(ans,r-l-1+2*(u0+d1));



				if(s[i][r]=='m')M++;

				if(M>1)break;

			}

		}

