vl cost_edge;
vl cost_in;

ll mx;

ar<ar<ll, 2>, 2> GetDp(int pos) {
    ar<ar<ll, 2>, 2> dp;
    assert(pos + 1 < cost_edge.size());
    assert(pos < cost_in.size());
    rep(i, 2) {
        rep(j, 2) {
            dp[i][j] = cost_in[pos];
            if (i) dp[i][j] += cost_edge[pos];
            if (!j) dp[i][j] += cost_edge[pos + 1];
            if (dp[i][j] > mx) {
                dp[i][j] = -INF;
            }
        }
    }
    return dp;
}

struct node {
    ar<ar<ll, 2>, 2> dp;

    node(int pos = -1) {
        rep(i, 2) {
            rep(j, 2) {
                dp[i][j] = INF;
            }
        }
        dp[0][1] = -INF;
        dp[1][0] = -INF;
        init(pos);
    }

    void init(int pos) {
        if (pos != -1) {
            dp = GetDp(pos);
        }
    }

    void apply(ll delta, int vl, int vr) {
        assert(vl + 1 == vr && delta == -1);
        init(vl);
    }

    void push(node &child, int vl, int vr, int cl, int cr) {
    }

    void clear_after_push() {
    }

    static node merge(const node &left, const node &right) {
        node res;
        rep(i, 2) {
            rep(j, 2) {
                res.dp[i][j] = -INF;
                rep(t, 2) {
                    res.dp[i][j] = max(res.dp[i][j], min(left.dp[i][t], right.dp[t][j]));
                }
            }
        }
        return res;
    }
};

void solve() {
    int n;
    cin >> n;
    vl a(n * 2);
    rep(i, n * 2) cin >> a[i];
    if (n == 1) {
        cout << "0\n";
        return;
    }
    if (n % 2 == 0) {
        ll L = INF;
        ll R = -INF;
        rep(i, n / 2) {
            pair<ll, ll> f = {a[i * 2] + a[i * 2 + 1], a[i * 2 + n] + a[i * 2 + 1 + n]};
            swap(a[i * 2], a[i * 2 + n]);
            pair<ll, ll> s = {a[i * 2] + a[i * 2 + 1], a[i * 2 + n] + a[i * 2 + 1 + n]};
            if (f.first > f.second) swap(f.first, f.second);
            if (s.first > s.second) swap(s.first, s.second);
            if (f.first < s.first) swap(s, f);
            L = min(L, f.first);
            R = max(R, f.second);
        }
        cout << R - L << '\n';
        return;
    }
    int pos = 0;
    vi ord;
    rep(_, n) {
        ord.push_back(pos / 2);
        pos ^= 1;
        pos += n;
        if (pos >= 2 * n) pos -= 2 * n;
    }
    vi pos2(n);
    rep(i, n) pos2[ord[i]] = i;
    mx = INF;
    cost_in.assign(n, 0);
    cost_edge.assign(n + 1, 0);
    rep(i, n) {
        ll mn = min(a[i], a[i + n]);
        ll value = max(a[i], a[i + n]) - mn;
        int q = pos2[i / 2];
        int u = pos2[(i + n) / 2];
        cost_in[q] += mn;
        cost_in[u] += mn;
        if ((q + 1) % n == u) {
            cost_edge[u] += value;
        } else if ((u + 1) % n == q) {
            cost_edge[q] += value;
        } else {
            assert(0);
        }
    }
    cost_edge[n] = cost_edge[0];
    vi order(n);
    iota(all(order), 0);
    segtree<node> st(order);

    vector<pair<ll, int>> events;
    rep(i, n) {
        auto cur = GetDp(i);
        rep(j, 2) {
            rep(q, 2) {
                events.push_back({cur[j][q], i});
            }
        }
    }
    sort(rall(events));
    ll ans = INF;
    auto Check = [&] () {
        auto val = st.query(0, n);
        rep(i, 2) {
            ans = min(ans, mx - val.dp[i][i]);
        }
    };
    for(auto &[x, y] : events) {
        if (mx >= x) {
            mx = x;
            Check();
        }
        assert(mx >= x - 1);
        mx = x - 1;
        st.update(y, y + 1, -1);
    }

    cout << ans << '\n';
}

