inline bool work(int x)
{
	int tot = 0, cnt = 0;
	while(tot < n) {
		while(tot < n && x >= a[tot + 1]) {
			tot ++;
		}
		if (tot - cnt >= p) return false;
		cnt ++;
		x ++;
	}
	return true;
}
int main()
{
	int mini = 0;
	read(n); read(p);
	for (int i = 1; i <= n; i ++) 
	{
		read(a[i]);
	}
	sort(a + 1, a + n + 1);
	for (int i = 1; i <= n; i ++) 
	{
		mini = max(mini, a[i] - i + 1);
	}
	if (!work(mini)) {
		puts("0");
		return 0;
	}
	int l = mini, r = a[n], res = n;
	while(l <= r) {
		int mid = l + r >> 1;
		if (work(mid)) {
			res = mid;
			l = mid + 1;
		}
		else r = mid - 1;
	}
	write(res - mini + 1, '\n');
	if (res - mini + 1) {
		for (int i = mini; i < res; i ++) {
			write(i, ' ');
		}
		write(res, '\n');
	}
	return 0;
}

