int cnt[51][51];
int memo[51][51][51][51];

int max(int a, int b) { return a > b ? a : b; }
int min(int a, int b) { return a < b ? a : b; }

int count(int x1, int x2, int y1, int y2) {
    return cnt[x2][y2] - cnt[x1 - 1][y2] - cnt[x2][y1 - 1] + cnt[x1 - 1][y1 - 1];
}

int calc(int x1, int x2, int y1, int y2) {
    if (x1 > x2 || y1 > y2) return 0;
    if (memo[x1][x2][y1][y2] != -1) return memo[x1][x2][y1][y2];
    if (count(x1, x2, y1, y2) == 0) return memo[x1][x2][y1][y2] = 0;

    int a1 = x1, a2 = x2, b1 = y1, b2 = y2;

    while (count(a1, a1, b1, b2) == 0) a1++;
    while (count(a2, a2, b1, b2) == 0) a2--;
    while (count(a1, a2, b1, b1) == 0) b1++;
    while (count(a1, a2, b2, b2) == 0) b2--;

    if(x1 != a1 || x2 != a2 || y1 != b1 || y2 != b2) return memo[x1][x2][y1][y2] = calc(a1, a2, b1, b2);

    int ans = max(x2 - x1 + 1, y2 - y1 + 1);
    for(int i = x1; i <= x2 + 1; i++) {
        for(int j = y1; j <= y2 + 1; j++) {
            if ((i > x2 || count(i, i, y1, y2) == 0) && (j > y2 || count(x1, x2, j, j) == 0)) {
                if (i > x2 && j > y2) continue;
                ans = min(ans,
                    calc(x1, i - 1, y1, j - 1)
                    + calc(i + 1, x2, y1, j - 1)
                    + calc(x1, i - 1, j + 1, y2)
                    + calc(i + 1, x2, j + 1, y2)
                );
            }
        }
    }

    return memo[x1][x2][y1][y2] = ans;
}

int main() {
    int n, i, j;
    scanf("%d", &n);
    for(int i = 0; i <= n; i++) for(int j = 0; j <= n; j++) cnt[i][j] = 0;
    for(int i = 0 ; i < n ; i++) {
        for(int j = 0; j < n; j++) {
            char ch;
            scanf(" %c", &ch);
            cnt[i + 1][j + 1] = (ch == '#' ? 1 : 0);
        }
    }

    for(int i = 1; i <= n; i++) {
        for(int j = 1; j <= n; j++) cnt[i][j] = cnt[i][j - 1] + cnt[i][j];
    }

    for(int j = 1; j <= n; j++) {
        for(int i = 1; i <= n; i++) cnt[i][j] = cnt[i - 1][j] + cnt[i][j];
    }

    for(int i = 0; i <= n; i++) {
        for(int j = 0; j <= n; j++) {
            for(int k = 0; k <= n; k++) {
                for(int l = 0; l <= n; l++) {
                    memo[i][j][k][l] = -1;
                }
            }
        }
    }

    printf("%d\n", calc(1, n, 1, n));
    return 0;
}

