					for (j0=0;j0<=j;j0++)
						for (k0=0;k0<=k;k0++)
							if (j0+k0 >= 1 && j0*50 + k0*100 <= K)
								F[ii^1][N1-j+j0][N2-k+k0] = F[ii^1][N1-j+j0][N2-k+k0] + 
								(((long long)(F[ii][j][k].n) * C[j][j0])*C[k][k0])%modulo;
							else if (j0*50 + k0*100 > K)
								break;
				}
	}
}

