struct dsu {
	vector<int> chot;
	int n;
	dsu(int n) : n(n) {
		chot.resize(n,-1);
	}
	int find(int u) {
		return chot[u] < 0 ? u : chot[u] = find(chot[u]);
	}
	void combine(int u,int v) {
		u = find(u);v = find(v);
		if (u != v) {
			if (-chot[u] < -chot[v]) swap(u,v);
			chot[u] += chot[v];
			chot[v] = u;
		}
	}
};

int main() {
	IOS;
	cin >> q;
	while (q--) {
		cin >> n >> m;
		auto con = [&](int i,int j) {
			return i * m + j;
		};
		vector<int> nxt(n*m);
		vector<bool> kt(n * m);
		for (int i = 0;i < n;i++) {
			string s;
			cin >> s;
			for (int j = 0;j < m;j++) kt[con(i,j)] = (s[j] == '0' ? true : false);
		}
		for (int i = 0;i < n;i++) {
			string s;
			cin >> s;
			for (int j = 0;j < m;j++) {
				for (int pos = 0;pos < 4;pos++) {
					if (s[j] == c[pos]) {
						int x = i + dx[pos];
						int y = j + dy[pos];
						nxt[con(i,j)] = (con(x,y));
						break;
					}
				}
			}
		}
		int ans = 0,black = 0;
		vector<int> vis(n * m);
		vector<vector<int>> time(n * m);
		vector<int> P(n * m);
		vector<int> d(n * m);
		vector<vector<int>> cycle;
		for (int i = 0;i < n * m;i++) {
			if (!vis[i]) {
				int u = i;
				stack<int> s;
				while (1) {
					s.emplace(u);
					if (vis[u] == 1) {
						s.pop();
						cycle.emplace_back(vector<int>());
						while (1) {
							int v = s.top();s.pop();
							cycle.back().emplace_back(v);
							++ans;
							if (kt[v]) time[v].emplace_back(0);
							vis[v] = 2;
							P[v] = v;
							d[v] = 0;
							if (u == v) break;
						}
						break;
					}
					else if (vis[u] == 2) break;
					vis[u] = 1;
					u = nxt[u];
				}
				if (s.empty()) continue;
				int root = s.top();
				while ((int)s.size()) {
					int v = s.top();s.pop();
					vis[v] = 2;
					P[v] = P[nxt[root]];
					d[v] = d[nxt[v]] + 1;
					if (kt[v]) time[P[v]].emplace_back(d[v]);
				}
			}
		}
		for (int i = 0;i < (int)cycle.size();i++) {
			set<int> s;
			int count = 0;
			for (auto&x : cycle[i]) {
				for (auto&u : time[x]) {
					s.insert((u + count) % (int)cycle[i].size());
				}
				count++;
			}
			black += (int)s.size();
		}
		cout << ans <<" " << black <<"\n";
	}
}

