	for (i = 1; i < N; i++) {
		int t1, t2, t3;
		scanf("%d %d %d", &t1, &t2, &t3);
		D[t1][t2] = min(D[t1][t2], t3);
		D[t2][t1] = min(D[t2][t1], t3);
		deg[t1]++;
		deg[t2]++;
		conn[t1].push_back(t2);
		conn[t2].push_back(t1);
	}
	for (k = 1; k <= N; k++) for (i = 1; i <= N; i++) for (j = 1; j <= N; j++) D[i][j] = min(D[i][k] + D[k][j], D[i][j]);

	int lc = 0;
	for (i = 1; i <= N; i++) if (deg[i] == 1) u[++lc] = i;

	scanf("%d", &S);
	scanf("%d", &M);
	for (i = 1; i <= M; i++) {
		int t;
		scanf("%d", &t);
		cri[t]++;
	}

	for (i = 1; i <= lc; i++) {
		for (j = 1; j <= lc; j++) dp[i][1] = max(dp[i][1], D[u[i]][u[j]]);
	}

	for (i = 2; i <= M; i++) {
		for (j = 1; j <= lc; j++) {
			int st = 1, en = INF, mi, rv = 0;
			while (st <= en) {
				mi = (st + en) / 2;
				int c = 0;
				for (k = 1; k <= lc; k++) {
					if (k == j) continue;
					for (l = 1; l <= i; l++) if (dp[k][i - l] + D[u[j]][u[k]] < mi) break;
					c += l - 1;
				}
				if (c >= i) {
					rv = mi;
					st = mi + 1;
				}
				else en = mi - 1;
			}
			dp[j][i] = rv;
		}
	}
	if (deg[S] == 1) {
		for (i = 1; i <= lc; i++) if (u[i] == S) break;
		return !printf("%d\n", dp[i][M]);
	}

	vector <int> Vu;
	gpar[S] = S;
	for (auto it : conn[S]) {
		gpar[it] = it;
		Vu.push_back(it);
		for (i = 0; i < Vu.size(); i++) {
			for (auto it2 : conn[Vu[i]]) {
				if (gpar[it2]) continue;
				gpar[it2] = it;
				Vu.push_back(it2);
			}
		}
		Vu.clear();
	}

	int st = 1, en = INF, mi, rv = 0;
	while (st <= en) {
		mi = (st + en) / 2;
		bool c = false;
		for (auto it : conn[S]) {
			int cnt = 0;
			Vu.clear();
			for (i = 1; i <= lc; i++) if (gpar[u[i]] == it) Vu.push_back(i);
			for (i = 1; i <= N; i++) if (gpar[i] == it) cnt += cri[i];

			int cnt2 = 0;
			for (auto it : Vu) {
				for (i = 1; i <= cnt; i++) if (dp[it][M - i] + D[S][u[it]] < mi) break;
				cnt2 += i - 1;
			}
			if (cnt2 < cnt) {
				c = true;
				break;
			}
		}
		if (!c) {
			rv = mi;
			st = mi + 1;
		}
		else en = mi - 1;
	}
	return !printf("%d\n", rv);
}

