#include <bits/stdc++.h>
int n, q, f[200005];
struct seg{
  int l, a, b, r;
}se[200005];
int ma[200005 * 32], tot = 0, ls[200005 * 32], rs[200005 * 32], tg[200005 * 32];
int ask(int x, int l, int r, int L, int R){
  if(!x) return 0;
  if(l == L && r == R) return ma[x];
  int mid = l + r >> 1;
  if(R <= mid) return ask(ls[x], l, mid, L, R);
  else if(L >= mid + 1) return ask(rs[x], mid + 1, r, L, R);
  return std::max(ask(ls[x], l, mid, L, mid), ask(rs[x], mid + 1, r, mid + 1, R));
}
int upd(int x, int l, int r, int y, int z){
  if(!x) x = ++tot;
  if(l == r){
    ma[x] = std::max(ma[x], z);
    return x;
  }
  int mid = l + r >> 1;
  if(y <= mid) ls[x] = upd(ls[x], l, mid, y, z);
  else rs[x] = upd(rs[x], mid + 1, r, y, z);
  ma[x] = std::max(ma[ls[x]], ma[rs[x]]);
  return x; 
}
int upd2(int x, int l, int r, int L, int R, int y){
  if(!x) x = ++tot;
  if(l == L && r == R){
    ma[x] = std::max(ma[x], y);
    tg[x] = std::max(tg[x], y);
    return x;
  }
  int mid = l + r >> 1;
  if(R <= mid) ls[x] = upd2(ls[x], l, mid, L, R, y);
  else if(L >= mid + 1) rs[x] = upd2(rs[x], mid + 1, r, L, R, y);
  else {
    ls[x] = upd2(ls[x], l, mid, L, mid, y);
    rs[x] = upd2(rs[x], mid + 1, r, mid + 1, R, y);
  } 
  ma[x] = std::max(ma[ls[x]], ma[rs[x]]);
  return x;
}
int ask2(int x, int l, int r, int y){
  if(!x) return 0;
  if(l == r) return ma[x];
  int res = tg[x];
  int mid = l + r >> 1;
  if(y <= mid) return std::max(res, ask2(ls[x], l, mid, y));
  return std::max(res, ask2(rs[x], mid + 1, r, y));
}
const int N = 1000000000;
void solve(){
  scanf("%d", &n);
  for(int i = 1; i <= n; ++i) scanf("%d%d%d%d", &se[i].l, &se[i].r, &se[i].a, &se[i].b);
  std::sort(se + 1, se + n + 1, [&](seg a, seg b){
    return a.b > b.b;
  });
  tot = 1;
  for(int i = 1; i <= n; ++i){
    f[i] = std::max(se[i].b, ask(1, 0, N, 0, se[i].b));
    upd(1, 0, N, se[i].l, f[i]);
    //printf("seg %d %d\n", i, f[i]);
  }
  for(int i = 1; i <= tot; ++i) ma[i] = ls[i] = rs[i] = tg[i] = 0;
  tot = 1;
  for(int i = 1; i <= n; ++i) upd2(1, 0, N, se[i].l, se[i].r, f[i]);
  scanf("%d", &q);
  for(int i = 1; i <= q; ++i){
    int x;
    scanf("%d", &x);
    printf("%d ", std::max(ask2(1, 0, N, x), x));
  }
  printf("\n");
  for(int i = 1; i <= tot; ++i) ma[i] = ls[i] = rs[i] = tg[i] = 0;
  tot = 1;
  return ;
}
int main(){
  int T = 1;
  scanf("%d", &T);
  while(T--) solve();
  return 0;
}

