void dfs(int32_t v, std::vector<int32_t>* children, std::vector<std::vector<int32_t> >& layers, int32_t depth) {
    if(layers.size() <= depth)
        layers.emplace_back();
    layers[depth].push_back(v);
    for(int32_t i = 0; i < children[v].size(); i++)
        dfs(children[v][i], children, layers, depth + 1);
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);

    int32_t num_tests;
    std::cin >> num_tests;

    for(int32_t t = 0; t < num_tests; t++) {
        int32_t n;
        std::cin >> n;

        std::vector<int32_t>* children = new std::vector<int32_t>[n];
        int32_t* parents = new int32_t[n];
        for(int32_t i = 0; i < n - 1; i++) {
            int32_t parent;
            std::cin >> parent;
            parent--;

            children[parent].push_back(i + 1);
            parents[i + 1] = parent;
        }

        int32_t* cost = new int32_t[n];
        for(int32_t i = 1; i < n; i++)
            std::cin >> cost[i];

        std::vector<std::vector<int32_t> > layers;
        dfs(0, children, layers, 0);

        int64_t* dp = new int64_t[n];
        dp[0] = 0;
        int64_t* pref_max = new int64_t[n + 1];
        pref_max[0] = -INF;
        int64_t* suf_max = new int64_t[n + 1];
        suf_max[0] = -INF;
        for(int32_t i = 1; i < layers.size(); i++) {
            std::sort(layers[i].begin(), layers[i].end(), [&](int32_t v1, int32_t v2) {
                return cost[v1] < cost[v2];
            });
            for(int32_t j = 1; j <= layers[i].size(); j++)
                suf_max[j] = std::max(suf_max[j - 1], dp[parents[layers[i][layers[i].size() - j]]] + cost[layers[i][layers[i].size() - j]]);
            for(int32_t j = 1; j <= layers[i].size(); j++)
                pref_max[j] = std::max(pref_max[j - 1], dp[parents[layers[i][j - 1]]] - cost[layers[i][j - 1]]);
            for (int32_t j = 0; j < layers[i].size(); j++) {
                int32_t v = layers[i][j];
                dp[v] = dp[parents[v]] + cost[v] - cost[layers[i][0]];
                dp[v] = std::max(dp[v], dp[parents[v]] - cost[v] + cost[layers[i].back()]);

                dp[v] = std::max(dp[v], cost[v] + pref_max[j]);
                dp[v] = std::max(dp[v], suf_max[layers[i].size() - j - 1] - cost[v]);
            }
        }

        int64_t ans = INT64_MIN;
        for(int32_t i = 0; i < layers.back().size(); i++)
            ans = std::max(ans, dp[layers.back()[i]]);

        std::cout << ans << "\n";
    }
    return 0;
}

