int parse(int x, int y){
    int i,j,ans=0;
    REP(i,3) REP(j,3) if(buf[x+i][y+j] == 'O') ans |= (1 << (3*i + j));
    return ans;
}

int main(void){
    int i,j;

    scanf("%d%d",&H,&W);
    REP(i,H) REP(j,W) hor[i][j] = ver[i][j] = true;
    REP(i,H){
        scanf("%s",buf[0]); scanf("%s",buf[0]); scanf("%s",buf[1]); scanf("%s",buf[2]);
        REP(j,W){
            int mask = parse(0,4*j+1);
            if((mask&(1<<0)) && (mask&(1<<8)) && !(mask&(1<<2)) && !(mask&(1<<6))) ver[i][j] = false;
            if(!(mask&(1<<0)) && !(mask&(1<<8)) && (mask&(1<<2)) && (mask&(1<<6))) hor[i][j] = false;
            if(mask&(1<<1)) ver[i][j] = false;
            if(mask&(1<<3)) hor[i][j] = false;
        }
    }

//  REP(i,H) REP(j,W) cout << i << ' ' << j << ' ' << ver[i][j] << ' ' << hor[i][j] << endl;

    if(H%2 == 0){
        REP(j,W){
            bool all = true;
            REP(i,H) if(!ver[i][j]) all = false;
            if(all) dp1[j] = 1;
        }
    }

    REP(i,W-1){
        REP(j,H+1) dp[j] = 0;
        dp[0] = 1;

        REP(j,H){
            if(hor[j][i] && hor[j][i+1]) dp[j+1] = (dp[j+1] + dp[j]) % MOD;
            if(j <= H-2) if(ver[j][i] && ver[j][i+1] && ver[j+1][i] && ver[j+1][i+1]) dp[j+2] = (dp[j+2] + dp[j]) % MOD;
        }

        dp2[i] = dp[H]; // cout << dp2[i] << endl;
        if(dp1[i] == 1 && dp1[i+1] == 1) dp2[i] = (dp2[i] + MOD - 1) % MOD;
    }

    ans[0] = 1;
    REP(i,W){
        ans[i+1] = (ans[i+1] + ans[i] * dp1[i]) % MOD;
        if(i <= W-2) ans[i+2] = (ans[i+2] + ans[i] * dp2[i]) % MOD;
    }

    cout << ans[W] << endl;

    return 0;
}

