bool thue(ll pos) {

    return __builtin_popcountll(pos) & 1;

    ll ret = 0;



    while (pos) {

        ret ^= pos;

        pos /= 2;

    }



    return ret & 1;

}



map<pll, ll> cache;

ll calc(ll len, ll offset) {

    if (!len || !offset)

        return 0;



    auto p = pair(len, offset);

    if (cache.count(p))

        return cache[p];



    ll ans = 0;

    if (len & 1) {

        len -= 1;

        ans += thue(len) != thue(offset + len);

    }

    if (!len)

        return cache[p] = ans;



    if (offset & 1)

        ans += len - calc(len/2, offset/2) - calc(len/2, offset/2+1);

    else

        ans += 2*calc(len/2, offset/2);



    return cache[p] = ans;

}



