void add(int &x, int y) { x += y; if(x >= mod) x -= mod; }
void init() {
	f[0][0] = 1;
	p[0] = 1 % m;
	for(int i = 1; i <= n; i ++) p[i] = 10 * p[i-1] % m;
	for(int i = 1; i <= n; i ++) {
		for(int j = 0; j < m; j ++) {
			for(int k = 0; k < 10; k ++) if(((n - i) & 1) == (k == d)) {
				add(f[i][(p[i-1] * k + j)% m], f[i - 1][j]);
			}
		}
	}
}

int calc(int *a) {
	int tp = 0, tt = 0, rt = 0;
	for(int i = 1; i <= n; i ++) {
		for(int j = a[i] + (i < n); j < 10; j ++) {
			if((i & 1) == (j == d)) continue;
			tt =(tp + j * p[n-i]) % m;
			tt = (m - tt) % m;
			add(rt, f[n-i][tt]);
		}
		if((i & 1) == (a[i] == d)) break;
		tp = (tp + a[i] * p[n-i]) % m;
	}
	return rt;
}

