    cin >> N >> K;
    vector<int> a(N);
    for (int i = 0; i < N; i++)
        cin >> a[i];
    vector<int> prev(N);
    vector<int> nxt(N + 1, N);
    vector<int> last(N + 1, -1);
    vector<int> dp(N + 1);
    for (int i = 0; i < N; i++)
    {
        dp[i + 1] = dp[i] + (last[a[i]] == -1);
        prev[i] = last[a[i]];
        if (prev[i] != -1)
            nxt[prev[i]] = i;
        last[a[i]] = i;
    }

    for (int pass = 1; pass < K; pass++)
    {
        vector<int> dp2(N + 1, INT_MAX);
        vector<int> dpi(N + 1);
        vector<int> dpl(N + 1);
        dp2[0] = 0;
        dpi[0] = 0;
        dpl[0] = 0;
        dpi[N] = N;
        int step = 1;
        while (step < N)
            step *= 2;
        for (; step >= 1; step /= 2)
        {
            for (int i = step; i <= N; i += 2 * step)
            {
                int lo = dpi[i - step];
                int hi = dpi[min(i + step, N)];
                hi = min(hi, i);
                int best = -1;
                int bestj = -1;
                int bestu = -1;
                int u = dpl[i - step];
                for (int j = i - step; j < i; j++)
                    if (prev[j] < lo)
                        u++;
                for (int j = lo; j <= hi; j++)
                {
                    int score = dp[j] + u;
                    if (score > best)
                    {
                        best = score;
                        bestj = j;
                        bestu = u;
                    }
                    if (nxt[j] >= i)
                        u--;
                }
                dp2[i] = best;
                dpi[i] = bestj;
                dpl[i] = bestu;
            }
        }
        dp = move(dp2);
    }
    cout << dp[N] << '\n';

    return 0;
}

