namespace {

struct Edge {
  int u, v;
};

struct Query {
  int v, k, id;
};

template<typename T>
struct DirtyTable {
 public:
  DirtyTable() = default;
  DirtyTable(int n, T default_value) : table(n, default_value), vis(n, 0) {}

  void clear() { ++stmp; }

  T get(int p) const { return vis[p] == stmp ? table[p] : default_value; }

  bool contains(int p) const { return vis[p] == stmp; }

  void update(int p, T val) {
    table[p] = val;
    vis[p] = stmp;
  }

  bool enlarge(int p, T val) {
    if (vis[p] != stmp) {
      update(p, val);
      return true;
    } else if (table[p] < val) {
      table[p] = val;
      return true;
    }
    return false;
  }

 private:
  int stmp = 1;
  std::vector<T> table;
  std::vector<int> vis;
  T default_value = 0;
};

struct Solver {
  int n;
  std::vector<std::vector<Edge>> graph;
  int q;
  std::vector<Query> queries;
  std::vector<int> result;
  std::vector<std::pair<int, int>> candidates;
  std::vector<int> parent, depth;

  int get_num_raw_children(int v) const { return v == 0 ? graph[v].size() : (int)graph[v].size() - 1; }

  void solve(int ca, std::istream& reader) {
    reader >> n;
    graph.resize(n);
    for (int i = 0; i < n - 1; ++i) {
      int x, y;
      reader >> x >> y; --x; --y;
      graph[x].emplace_back(Edge{.u = x, .v = y});
      graph[y].emplace_back(Edge{.u = y, .v = x});
    }
    reader >> q;
    for (int i = 0; i < q; ++i) {
      int v, k;
      reader >> v >> k; --v;
      queries.emplace_back(Query{.v = v, .k = k, .id = i});
    }
    result.resize(q, 0);
    parent.resize(n);
    depth.resize(n);
    dfs(0, -1);
    std::sort(candidates.begin(), candidates.end());
    std::sort(queries.begin(), queries.end(), [](const Query& lhs, const Query& rhs) { return lhs.k < rhs.k; });
    DirtyTable table(n, 0);
    for (int k = 0, i = 0, j = 0; k <= 200000 && i < q; ++k) {
      while (i < q && queries[i].k < k) ++i;
      if (i >= q || queries[i].k != k) continue;
      table.clear();
      while (j < candidates.size() && candidates[j].first <= k) ++j;
      std::priority_queue<std::tuple<int, int, int>> pq;
      for (int r = j; r < candidates.size(); ++r) {
        table.update(candidates[r].second, candidates[r].first);
        pq.emplace(depth[candidates[r].second], candidates[r].first, candidates[r].second);
      }
      while (!pq.empty()) {
        int d, w, u;
        std::tie(d, w, u) = pq.top(); pq.pop();
        if (!table.contains(u) || table.get(u) != w) continue;
        if (parent[u] == -1) continue;
        if (w <= k) continue;
        if (!table.contains(parent[u])) {
          table.update(parent[u], get_num_raw_children(parent[u]));
        }
        if (table.enlarge(parent[u], table.get(parent[u]) - 1 + w - k)) {
          pq.emplace(depth[parent[u]], table.get(parent[u]), parent[u]);
        }
      }
      while (i < q && queries[i].k == k) {
        int v = queries[i].v;
        int id = queries[i].id;
        if (table.contains(v)) {
          result[id] = table.get(v);
        } else {
          result[id] = get_num_raw_children(v);
        }
        ++i;
      }
    }
    for (int i = 0; i < q; ++i) {
      printf("%d\n", result[i]);
    }
  }

  void dfs(int u, int fa) {
    parent[u] = fa;
    int cnt = 0;
    for (const Edge& e : graph[u]) if (e.v != fa) {
      depth[e.v] = depth[u] + 1;
      ++cnt;
      dfs(e.v, u);
    }
    if (cnt > 0) {
      candidates.emplace_back(cnt, u);
    }
  }
};

}  // namespace

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::istream& reader = std::cin;

  int cas = 1;
  // reader >> cas;
  for (int ca = 1; ca <= cas; ++ca) {
    auto solver = std::make_unique<Solver>();
    solver->solve(ca, reader);
  }
}

