const int DIM = 2e5 + 5;

vector<int> v[DIM];
int tt[DIM], h[DIM];
int dp[DIM], hm[DIM];

void dfs(int nod) {
  for (auto it : v[nod]) {
    if (it == tt[nod])
      continue;

    tt[it] = nod;
    h[it] = h[nod] + 1;
    dfs(it);
  }
}

void dfs2(int nod) {
  hm[nod] = h[nod];
  dp[nod] = 0;
  for (auto it : v[nod]) {
    if (it == tt[nod])
      continue;

    tt[it] = nod;
    h[it] = h[nod] + 1;
    dfs2(it);

    dp[nod] += 2 + dp[it];
    hm[nod] = max(hm[nod], hm[it]);
  }
}

void solve() {
  int n;
  cin >> n;

  int a, b;
  cin >> a >> b;

  for (int i = 1; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    v[x].push_back(y);
    v[y].push_back(x);
  }

  tt[a] = h[a] = 0;
  dfs(a);

  int ans = 0;

  int cnt = (h[b] + 1) / 2; 

  ans += cnt;
  while (cnt--)
    b = tt[b];

  tt[b] = h[b] = 0;
  dfs2(b);

  cout << ans + dp[b] - hm[b] << "\n";

  for (int i = 1; i <= n; ++i)
    v[i].clear();
}

