string decimalToBase9(int decimal)
{
      string result = "";

      // special case for input 0
      if (decimal == 0)
      {
            result = "0";
      }
      else
      {
            // convert decimal to base-9 using modulo operator and integer division
            while (decimal != 0)
            {
                  int digit = decimal % 9;
                  result = to_string(digit) + result;
                  decimal /= 9;
            }
      }

      return result;
}

