                int zz=mul(curr[j],ways);

                int prob=mul(fact[n-j-2],inv_fact[n]);

                prob=mul(prob,zz);

                res=add(res,prob);
            }
        }

        vector<int> now;now.pb(1);now.pb(cnt[i]);

        curr=mult(curr,now);
    }

