int dfs(int x,int y,int pos){
    if(dp[x][y]!=-1)return dp[x][y];
    dp[x][y]=inf;
    int tmp=0;
    pos=(pos+1)%4;
    if(s[x+1][y]==st[pos])
        tmp=max(tmp,dfs(x+1,y,pos));
    if(s[x-1][y]==st[pos])
        tmp=max(tmp,dfs(x-1,y,pos));
    if(s[x][y+1]==st[pos])
        tmp=max(tmp,dfs(x,y+1,pos));
    if(s[x][y-1]==st[pos])
        tmp=max(tmp,dfs(x,y-1,pos));
    dp[x][y]=++tmp;
    return tmp;
}
