vector<pair<int,ll> > a[M];

struct STR{
      int h;
      ll cost;
}str[M];

int le[M],ri[M];
int stk[M];
int top = 0;
void solvel() {
      top = 0;
      le[1] = 1;
      stk[top++] = 1;
      for(int i = 2; i <= m; i++) {
            int ans = i;
            int t = i - str[i].h + 1;
            t = max(t, 1);
            while(top > 0 && stk[top - 1] >= t) {
                   ans = min(ans, le[stk[top - 1]]);
                   top--;
            }
            stk[top++] = i; le[i] = ans;
      }
}

void solver() {
      top = 0;
      ri[m] = m;
      stk[top++] = m;
      for(int i = m - 1; i >= 1; i--) {
            int ans = i;
            int t = i + str[i].h - 1;
            t = min(m, t);
            while(top > 0 && stk[top - 1] <= t) {
                   ans = max(ans, ri[stk[top - 1]]);
                   top--;
            }
            stk[top++] = i; ri[i] = ans;
      }
}
ll dp[M];
void solve() {
     dp[1] = str[1].cost;
     top = 0;
     stk[top++] = 1;
     for(int i = 2; i <= m; i++) {
           int t = le[i];
           dp[i] = str[i].cost + dp[t - 1];
           ll v1 = str[i].cost + dp[i - 1];
           dp[i] = min(v1, dp[i]);
           while(top > 0 && ri[stk[top - 1]] < i) {
                 top--;
           }
           if(top == 0) {
                  stk[top++] = i;
           } else {
                 int id = stk[top - 1];
                 v1 = str[id].cost + dp[id - 1];
                 dp[i] = min(v1, dp[i]);
                 //if(dp[stk[top - 1]] > dp[i]) stk[top++] = i;
                 if(dp[stk[top - 1] - 1] + str[stk[top - 1]].cost > dp[i - 1] + str[i].cost) stk[top++] = i;

           }
     }
}
