int cnt[1 << 17];
int fib[1010101];
int sab[1 << 17];
int sde[1 << 17];
int sabc[1 << 17];
void fwht(int *data, int dim) {
    for (int len = 1; 2 * len <= dim; len <<= 1) {
        for (int i = 0; i < dim; i += 2 * len) {
            for (int j = 0; j < len; j++) {
                int a = data[i + j];
                int b = data[i + j + len];

                data[i + j] = (a + b) % mod;
                data[i + j + len] = (mod + a - b) % mod;
            }
        }
    }
}
void transformAnd(int *data, int dim, bool inverse) {
    for (int len = 1; 2 * len <= dim; len <<= 1) {
        for (int i = 0; i < dim; i += 2 * len) {
            for (int j = 0; j < len; j++) {
                int a = data[i + j];
                int b = data[i + j + len];

//                data[i + j] = (a + b) % mod;
//                data[i + j + len] = (mod + a - b) % mod;
                if (!inverse) {
                    data[i + j] = b;
                    data[i + len + j] = (a + b) % mod;
                } else {
                    data[i + j] = (mod -a + b) % mod;
                    data[i + len + j] = a;
                }
            }
        }
    }
}

int solve() {
    fib[0] = 0;
    fib[1] = 1;
    for (int i = 2; i <= 1000000; ++i) {
        fib[i] = fib[i - 1] + fib[i - 2];
        if (fib[i] >= mod) fib[i] -= mod;
    }
    int n = readInt();
    FI(n) {
        int x = readInt();
        cnt[x]++;
    }
    for (int mask = 0; mask < (1 << 17); ++mask) {
        ll res = 0;
        for (int i = mask;; i = mask & (i - 1)) {
            int j = mask ^ i;
            res += cnt[i] * (ll)cnt[j];
            if (i == 0) break;
        }
        sab[mask] = res % mod;
    }
    const int N = 1 << 17;
    FI(N) sde[i] = cnt[i];
    fwht(sde, 1 << 17);
    FI(N) {
        sde[i] = sde[i] * (ll) sde[i] % mod;
    }
    fwht(sde, 1 << 17);
    int rev = (int)powmod(N, mod - 2, mod);
    FI(N) {
        sde[i] = sde[i] * (ll) rev % mod;
    }
//    printarray(fib, 16);
//    cout << endl;
//
//    printarray(sab, 16);
//    printarray(cnt, 16);
//    printarray(sde, 16);
//    cout << endl;
    FI(N) {
        sab[i] = sab[i] * (ll) fib[i] % mod;
    }
    FI(N) {
        sde[i] = sde[i] * (ll) fib[i] % mod;
    }
    FI(N) {
        cnt[i] = cnt[i] * (ll) fib[i] % mod;
    }
//    printarray(sab, 16);
//    printarray(cnt, 16);
//    printarray(sde, 16);

    transformAnd(sab, N, false);
    transformAnd(cnt, N, false);
    transformAnd(sde, N, false);
    FI(N) {
        sabc[i] = sab[i] * (ll) cnt[i] % mod * sde[i] % mod;
    }
    transformAnd(sabc, N, true);
    ll ans = 0;
    for (int i = 0; i < 17; ++i) {
        ans += sabc[1 << i];
    }
    ans %= mod;
    cout << ans << endl;
    return 0;
}

