int N, K, A[109]; modulo ans[55][55], mat[55][55], tmp[55][55];
int main() {
	cin >> N >> K;
	int zeros = 0, ones = 0;
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
		if (A[i] == 0) ++zeros;
		else ++ones;
	}
	int inidiff = 0;
	for (int i = 0; i < N; ++i) {
		if (A[i] == 0 && i >= zeros) ++inidiff;
	}
	modulo allposs = modulo(N * (N - 1) / 2);
	int md = min(zeros, ones);
	for (int i = 0; i <= md; ++i) {
		for (int j = 0; j <= md; ++j) {
			if (i - j == 1) {
				mat[i][j] = modulo(i * i) * allposs.inv();
			}
			if (i - j == 0) {
				mat[i][j] = modulo(allposs - i * i - (zeros - i) * (ones - i)) * allposs.inv();
			}
			if (i - j == -1) {
				mat[i][j] = modulo((zeros - i) * (ones - i)) * allposs.inv();
			}
		}
	}
	for (int i = 0; i <= md; ++i) {
		ans[i][i] = modulo(1);
	}
	while (K > 0) {
		if (K & 1) {
			for (int i = 0; i <= md; ++i) {
				for (int j = 0; j <= md; ++j) {
					tmp[i][j] = 0;
				}
			}
			for (int i = 0; i <= md; ++i) {
				for (int j = 0; j <= md; ++j) {
					for (int k = 0; k <= md; ++k) {
						tmp[i][j] += ans[i][k] * mat[k][j];
					}
				}
			}
			for (int i = 0; i <= md; ++i) {
				for (int j = 0; j <= md; ++j) {
					ans[i][j] = tmp[i][j];
				}
			}
		}
		for (int i = 0; i <= md; ++i) {
			for (int j = 0; j <= md; ++j) {
				tmp[i][j] = 0;
			}
		}
		for (int i = 0; i <= md; ++i) {
			for (int j = 0; j <= md; ++j) {
				for (int k = 0; k <= md; ++k) {
					tmp[i][j] += mat[i][k] * mat[k][j];
				}
			}
		}
		for (int i = 0; i <= md; ++i) {
			for (int j = 0; j <= md; ++j) {
				mat[i][j] = tmp[i][j];
			}
		}
		K >>= 1;
	}
	cout << ans[inidiff][0].get() << endl;
	return 0;
}

