void solve(){
	ll n,m;
	cin>>n>>m;
	vector<pii>v[3];
	rep(i,0,n){
		ll a,l,r;
		cin>>a>>l>>r;
		v[a-1].pb({l,r});
	}
	rep(i,0,3){
		sort(all(v[i]));
		stack<pii>stk;
		for(auto j:v[i]){
			if(stk.empty() or stk.top().S<j.F-1)stk.push(j);
			else stk.top().S=max(stk.top().S,j.S);
		}
		v[i].clear();
		v[i].reserve(sz(stk));
		while(!stk.empty())v[i].pb(stk.top()),stk.pop();
		reverse(all(v[i]));
	}
	vector<pii>mods[3];
	rep(i,0,3){
		for(auto j:v[i]){
			mods[i].push_back({j.F,1});
			mods[i].push_back({j.S+1,0});
		}
	}
	vector<int>ans={0,1,0};
	ll pos=1;
	mods[0].pb({m+1,0});
	mods[1].pb({m+1,0});
	mods[2].pb({m+1,0});
	int i=0;
	int j=0;
	int k=0;
	array<int,3>cur={0,0,0};
	while(true){
		ll nextch=min({mods[0][i].F,mods[1][j].F,mods[2][k].F});
		ll changes=nextch-pos-1;
		ans=get(ans,cur,cur,changes);
		if(nextch==m+1){
			cout<<ans[1]<<endl;
			return;
		}
		pos=nextch-1;
		array<int,3>newcur=cur;
		while(nextch==mods[0][i].F){
			newcur[0]=mods[0][i].S;
			i++;
		}
		while(nextch==mods[1][j].F){
			newcur[1]=mods[1][j].S;
			j++;
		}
		while(nextch==mods[2][k].F){
			newcur[2]=mods[2][k].S;
			k++;
		}
		ans=get(ans,cur,newcur,1);
		pos++;
		cur=newcur;
	}
}

