ll bp(ll a,ll b,ll md) {
    ll res = 1;
    while (b) {
        if (b & 1) res *= a;
        a *= a;
        a %= md;
        res %= md;
        b >>= 1;
    }
    return res;
}
ll inv(ll x,ll md) {return bp(x, md - 2, md);}


void update_by_mod(int &x,int md){
    x%=md;
    if (x<0) x+=md;
}

void update_by_mod(int &x,int &y,int md){
    update_by_mod(x,md);
    update_by_mod(y,md);
}
void update_by_mod(int &x,int &y,int &z,int md){
