#define maxN 200050

void solve() {
    int n;
    cin>>n;
    vi v(n);
    map<int, int> mp;
    for (int &i:v){
        cin>>i;
        mp[i]++;
    }
    vpii vec;
    for (int i=0; i<=n; i++){
        if (mp.count(i)){
            vec.push_back({i,mp[i]});
        }else{
            n = i;
            break;
        }
    }

    vi dp(n+1, 0);

    dp[n] = 0;

    for (int i=n-1; i>=0; i--){
        dp[i] = INF64;
        int cn = vec[i].second;
        for (int prev = i+1; prev<=n; prev++){
            dp[i]=min(dp[i], dp[prev]+prev*(cn-1)+i);
        }
    }
    cout<<dp[0]<<en;



}

