using namespace std;

const int MAX_N = 3e5 + 5;

vector<int> adj [MAX_N];

int dfs (int u, int p, vector<int> &ops) {
  vector<int> ch;
  for (int nxt : adj[u]) {
    if (nxt == p)
      continue;

    int val = dfs(nxt, u, ops);
    ch.push_back(val);
  }

  if (ch.empty()) {
    // leaf
    return 1;
  }

  sort(ch.begin(), ch.end());
  for (int i = 0; i < (int) ch.size() - 1; i++)
    ops.push_back(ch[i]);

  if (u == 1)
    ops.push_back(ch.back());

  return 1 + ch.back();
}

void solve () {
  int n;
  cin >> n;

  for (int i = 1; i <= n; i++)
    adj[i].clear();

  for (int i = 0; i < n - 1; i++) {
    int u, v;
    cin >> u >> v;

    adj[u].push_back(v);
    adj[v].push_back(u);
  }

  vector<int> ops;
  dfs(1, 0, ops);

  sort(ops.rbegin(), ops.rend());
  int ans = 0;
  for (int i = 1; i < n; i++) {
    if (i != 1 && 2 * i - 3 < (int) ops.size())
      ans += ops[2 * i - 3];
    if (2 * i - 2 < (int) ops.size())
      ans += ops[2 * i - 2];

    cout << n - 1 - ans << " ";
  }
  cout << '\n';
}

int main () {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int testc;
  cin >> testc;

  for (int i = 0; i < testc; i++) {
    solve();
  }
}

