void init(int& n){
    int m = 0;
    for(int i = 1; i <= n; i++){
        if(c[i] != c[i - 1]){
            temp_c[++m] = c[i];
        }
    }
    for(int i = 1; i <= m; i++){
        c[i] = temp_c[i];
    }
    n = m;
}

void calcula_dp(int n){
    dp[1][n] = 0;
    int izq, der;
    for(int i = 1; i <= n; i++){
        for(int j = n; j >= i; j--){
            // si estoy en una orilla
            if(i == 1){
                if(j != n) dp[i][j] = dp[i][j + 1] + 1;
            }else if(j == n){
                dp[i][j] = dp[i - 1][j] + 1;
            }else if(c[i - 1] == c[j + 1]){
                dp[i][j] = dp[i - 1][j + 1] + 1;
            }else{
                izq = dp[i - 1][j] + 1;
                der = dp[i][j + 1] + 1;
                dp[i][j] = min(izq, der);
            }
        }
    }
}

