            if (f[v] >= w) { f[u] = std::max(f[u], f[v] - w + val[u]); }
            g[u] = std::max(g[u], f[u]);
        }
    }
}

int main() {
    n = read();
    for (int i = 1; i <= n; i++) { val[i] = read(); f[i] = g[i] = val[i]; }
    for (int i = 2; i <= n; i++) { int u = read(), v = read(); ls.connect(u, v, read()); }
    dfs(1, 0);
    for (int i = 1; i <= n; i++) { ans = std::max(ans, g[i]); }
    printf("%I64d\n", ans);
    return 0;
}

