using namespace std;

using namespace std;

using LL = long long;

const int maxn = 1e5 + 5;

LL mod;

LL fact[maxn], invfact[maxn];

LL qpow(LL a, LL b, LL mod){

    LL res = 1;

    while (b){

        if (b & 1) res = 1LL * res * a % mod;

        a = 1LL * a * a % mod;

        b >>= 1;

    }

    return res;

}



void init(){

    fact[0] = invfact[0] = 1;

    for(int i = 1; i < maxn; i++) fact[i] = (fact[i - 1] * i)%mod;

    invfact[maxn - 1] = qpow(fact[maxn - 1],mod-2,mod);

    for(int i = maxn - 2; i; i--)

        invfact[i] = (invfact[i + 1] * (i + 1))%mod;

}



inline LL C(int a, int b){

    if (a < b) return 0;

    return fact[a] * invfact[b] %mod* invfact[a - b]%mod;

}



void solve()

{

    LL n;

    cin>>n>>mod;

    init();

    LL ans=0;

    for(int i=2;i<=(n+1)/2;i++){

        int res=i-2;

        int last=i-(n&1);

        for(int j=0;j<=res;j++){

            ans+=(LL)last*C(res,j)%mod*fact[n-j-3]%mod;

        }

    }

    if(n%2==0){

        ans=(ans+fact[n-2])%mod;

    }

    ans=((LL)n*ans)%mod;

    cout<<ans<<endl;

    return ;

}

int main()

{

    int T;

    //cin>>T;

    T=1;

    while(T--){

        solve();

    }

    return 0;

}

