int nex[100005],pre[100005];

int dp[1005][1005];

int p[1005]; 

int n;

bool valid(int pos,int val)

{

    return p[pos]==-1||p[pos]==val;

}

bool check(int L,int R)

{

    return abs(L-R)==1&&(L%2==1);

}

int calc(int L,int R,int len)

{

    if (L==R) return valid(L,1);

    if (dp[L][R]!=-1)return dp[L][R];

    dp[L][R]=0;

    if(!check(L,R)&&valid(L,len))dp[L][R]=(dp[L][R]+calc(nex[L],R,len-1))%mod;

    if(!check(R,L)&&valid(R,len))dp[L][R]=(dp[L][R]+calc(L,pre[R],len-1))%mod;

    return dp[L][R];

}

int work()

{

    int ret=0;

    for(int i=1;i<=n;i++)

        for(int j=1;j<=n;j++)

            dp[i][j]=-1;

    for(int i=2;i<=n;i+=2)if(valid(i,n))ret=(ret+calc(nex[i],pre[i],n-1))%mod;

    return ret;

}

int main()

{

