    for(int greg=1;greg<=t;greg++)

    {

    	n=read();

    	for (int i=1;i<=n;i++)p[i]=read();

    	nex[2]=1;

    	pre[1]=2;

    	for(int i=1;i+2<=n;i+=2)nex[i]=i+2,pre[i+2]=i;

    	for(int i=2;i+2<=n;i+=2)nex[i+2]=i,pre[i]=i+2;

    	if(n%2==0)nex[n-1]=n,pre[n]=n-1;

		else nex[n]=n-1,pre[n-1]=n;

    	int ans=0;

    	ans=(ans+work())%mod;

    	for(int i=1;i<=n;i++)if(p[i]!=-1)p[i]=n+1-p[i];

    	ans=(ans+work())%mod;

    	printf("%d\n",ans);

    }

}

