int n;

struct item {
	int t, d, p, idx;
	inline void read(int id) {
		idx = id; scanf("%d%d%d",&t,&d,&p);
	}
} it[110];
inline bool cmp(const item &a, const item &b) {
	return a.d < b.d;
}

int dp[2020];
bool take[110][2020];

void DP() {
	for (int i = 1; i <= n; i++)
		for (int j = it[i].d-1; j >= it[i].t; j--) {
			register int w = dp[j-it[i].t] + it[i].p;
			if (take[i][j] = w > dp[j]) dp[j] = w;
		}
}

int main() {
	scanf("%d",&n);
	for (int i = 1; i <= n; i++)
		it[i].read(i);
	std::sort(it+1,it+n+1,cmp);
	DP();
	int maxp = 0, d = 0;
	for (int i = 1; i < it[n].d; i++)
		if (dp[i] > maxp) maxp = dp[d = i];
	int ans[110], m = 0;
	for (int i = n; i; i--)
		if (take[i][d]) {
			ans[m++] = it[i].idx;
			d -= it[i].t;
		}
	printf("%d\n%d\n",maxp,m);
	while (m) printf("%d ",ans[--m]);
	return 0;
