struct mint {
private:
  ll _val;

public:
  mint() { _val = 0; }
  mint(ll value) { _val = value % Mod; }
  mint(ll value, const bool &&ok) { _val = value; }

  inline mint operator+(mint b) const {
    b._val += this->_val;
    if (b._val > Mod)
      b._val -= Mod;
    return b;
  }
  inline mint operator-(mint b) const {
    b._val = this->_val + Mod - b._val;
    if (b._val > Mod)
      b._val -= Mod;
    return b;
  }
  inline mint operator*(mint b) const {
    b._val = b._val * this->_val % Mod;
    return b;
  }
  inline mint operator/(mint b) const {
    b._val = this->_val * inv(b)._val % Mod;
    return b;
  }

  inline mint &operator+=(const mint &b) {
    _val += b._val;
    if (_val > Mod)
      _val -= Mod;
    return *this;
  }
  inline mint &operator-=(const mint &b) {
    _val += Mod - b._val;
    if (_val > Mod)
      _val -= Mod;
    return *this;
  }
  inline mint &operator*=(const mint &b) {
    _val = _val * b._val % Mod;
    return *this;
  }
  inline mint &operator/=(const mint &b) {
    _val = _val * inv(b)._val % Mod;
    return *this;
  }

  mint &operator=(const mint &b) {
    _val = b._val;
    return *this;
  }

  explicit operator ll() const { return _val; }
  explicit operator bool() const { return _val; }
};

