struct Tree {
  int N;
  int *H, *Sz, *Sttime, *Edtime;
  int **Par;
  vector<int> *Adj;
  vector<int> *Ch;

  Tree(int n) {
    N = n;
    H = new int[n + 5];
    Sz = new int[n + 5];
    Sttime = new int[n + 5];
    Edtime = new int[n + 5];
    Adj = new vector<int>[n + 5];
    Ch = new vector<int>[n + 5];
    Par = new int *[n + 5];
    Par[0] = new int[(n + 5) * Log];
    for (int i = 1; i < n + 5; i++) {
      Par[i] = Par[i - 1] + Log;
    }
  }
  ~Tree() {
    delete[] H;
    delete[] Sz;
    delete[] Sttime;
    delete[] Edtime;

    delete[] Par[0];
    delete[] Par;

    delete[] Adj;
    delete[] Ch;
  }
  inline void Input1() {
    for (int i = 1; i < N; i++) {
      int a, b;
      cin >> a >> b;
      Adj[a].push_back(b);
      Adj[b].push_back(a);
    }
  }
  inline void Input2() {
    for (int i = 2; i <= N; i++) {
      int p;
      cin >> p;
      Adj[p].push_back(i);
      Adj[i].push_back(p);
    }
  }
  void MakeRooted(const int &v) {
    Sz[v] = 1;
    for (int lg = 1; lg < Log; lg++)
      Par[v][lg] = Par[Par[v][lg - 1]][lg - 1];
    for (int u : Adj[v])
      if (u != Par[v][0]) {
        Ch[v].push_back(u);
        H[u] = H[v] + 1;
        Par[u][0] = v;
        Edtime[u] = Sttime[u] = Edtime[v] + 1;
        MakeRooted(u);
        Edtime[v] = Edtime[u];
        Sz[v] += Sz[u];
      }
  }
  inline int LCA(int a, int b) {
    if (a == b)
      return a;
    if (Sttime[a] > Sttime[b])
      swap(a, b);
    for (int lg = Log; lg--;)
      if (Sttime[a] < Sttime[Par[b][lg]])
        b = Par[b][lg];
    return Par[b][0];
  }
  inline int KthPar(int v, const int &k) {
    for (int lg = 0; lg < Log; lg++)
      if ((1 << lg) & k)
        v = Par[v][lg];
    return v;
  }
  inline bool IsPar(const int &p, const int &v) {
    return Sttime[p] <= Sttime[v] && Sttime[v] <= Edtime[p];
  }
  inline int Dist(const int &a, const int &b) {
    int l = LCA(a, b);
    return H[a] + H[b] - (H[l] << 1);
  }
};

