    for (int i = 1; i <= n; i++) {
      bit[i] += A[i];
      bit[i + mnbit(i)] += bit[i];
    }
  }
  ~FEN() { delete[] bit; }
  void upd(int i, const num &x) {
    for (; i <= n; i += mnbit(i)) {
      bit[i] += x;
    }
  }
