    num res = 0;
    for (; i; i -= mnbit(i)) {
      res += bit[i];
    }
    return res;
  }
};

template <class Node> struct SEG {
  int n;
  Node *node;

  SEG(const int &N) {
    n = N + 1;
    node = new Node[n << 1];

    int *null = NULL;
    for (int i = 0; i < n; i++)
      node[n + i] = Node(null);

    for (int i = n; i--;)
      Node::merge(node[i << 1], node[i << 1 | 1], node[i]);
  }
  template <class Ty> SEG(const int &N, const Ty *A) {
    n = N + 1;
    node = new Node[n << 1];

    for (int i = 0; i < n; i++)
      node[n + i] = Node(A + i);

    for (int i = n; i--;)
      Node::merge(node[i << 1], node[i << 1 | 1], node[i]);
  }
  ~SEG() { delete[] node; }

  template <class Ty> void upd(int i, const Ty &x) {
    i += n;
    node[i].upd(x);

    for (; i >>= 1;)
      Node::merge(node[i << 1], node[i << 1 | 1], node[i]);
  }
  void rangeact(int l, int r, void (*act)(Node *)) {
    l += n, r += n;
    for (; l < r; l >>= 1, r >>= 1) {
      if (l & 1)
        act(&node[l++]);
      if (r & 1)
        act(&node[--r]);
    }
  }
  Node get(int l, int r) {
    l += n, r += n;
    Node lv, lvt, rv, rvt;
    Node *lres = &lv, *lres_t = &lvt;
    Node *rres = &rv, *rres_t = &rvt;
    for (; l < r; l >>= 1, r >>= 1) {
      if (l & 1)
        Node::merge(*lres, node[l++], *lres_t), swap(lres, lres_t);
      if (r & 1)
        Node::merge(node[--r], *rres, *rres_t), swap(rres, rres_t);
    }
    Node::merge(*lres, *rres, *lres_t);
    return *lres_t;
  }
};
