int A[Max], cold[Max], hot[Max];

ll dp[5100][5100];

void solve() {
  int n, k;
  cin >> n >> k;
  // init_fac();
  // init_sieve();

  for (int i = 0; i <= n; i++)
    for (int j = 0; j <= n; j++)
      dp[i][j] = INF;
  dp[0][0] = 0;

  for (int i = 1; i <= n; i++)
    cin >> A[i];
  for (int i = 1; i <= k; i++)
    cin >> cold[i];
  for (int i = 1; i <= k; i++)
    cin >> hot[i];

  // dp[i][j] => dp[mx + 1][j] , dp[i][mx + 1]

  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++) {
      int mx = max(i, j);
      dp[mx + 1][j] =
          min(dp[mx + 1][j], dp[i][j] + (A[mx + 1] == A[i] ? hot[A[mx + 1]]
                                                           : cold[A[mx + 1]]));
      dp[i][mx + 1] =
          min(dp[i][mx + 1], dp[i][j] + (A[mx + 1] == A[j] ? hot[A[mx + 1]]
                                                           : cold[A[mx + 1]]));
    }
  ll ans = INF;
  for (int i = 0; i < n; i++)
    ans = min(ans, dp[i][n], dp[n][i]);
  cout << ans << '\n';
}

