        edges[v].emplace_back(u, d);

    }

    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> hp;

    hp.push({0, 0});

    dist[0][0] = 0;

    while(!hp.empty()) {

        int onTemp = hp.top().second / n;

        int on = hp.top().second % n;

        int onDist = hp.top().first;

