#define FOR(i,n,m) for (int i=(n);i<=(m);i++)
#define si(n) fscanf(in,"%d",&n)
#define NM 10005
#define INF 0x7fffffff
#define MOD 1000000007
#define MIN(x,y) ((x)<(y)?(x):(y))
typedef long long int ll;
FILE *in = stdin, *out = stdout;
//FILE *in=fopen("input.txt","r"),*out=fopen("output.txt","w");
using namespace std;
#pragma comment (linker,"/stack:36777216")

int n;
ll m;
struct LIST {
	int stair, flag;
	ll idx;
	bool operator()(LIST A, LIST B) {
		if (A.idx != B.idx) return A.idx < B.idx;
		return A.flag < B.flag;
	}
}obs[NM * 2];
struct MATRIX {
	ll a[3][3];
	MATRIX() {
		FOR(i, 0, 2) FOR(j, 0, 2) a[i][j] = 0;
	}
	MATRIX operator*(const MATRIX& A) {
		MATRIX t;
		FOR(i, 0, 2) FOR(j, 0, 2) t.a[i][j] = 0;
		FOR(i, 0, 2) FOR(j, 0, 2) FOR(k, 0, 2) t.a[i][j] = (t.a[i][j] + a[i][k] * A.a[k][j]) % MOD;
		return t;
	}
}I;
MATRIX f(MATRIX &A, ll b) {
	if (b == 0) return I;
	MATRIX T = f(A, b >> 1);
	T = T * T;
	if (b & 1) T = T * A;
	return T;
}

void input() {
	si(n), fscanf(in, "%lld", &m);
	FOR(i, 1, n) {
		ll s, l, r;
		fscanf(in, "%lld %lld %lld", &s, &l, &r);
		obs[i].stair = s - 1, obs[i].idx = l, obs[i].flag = 0;
		obs[i + n].stair = s - 1, obs[i + n].idx = r, obs[i + n].flag = 1;
	}
	sort(obs + 1, obs + 1 + n * 2, LIST());
}

MATRIX make(int prev_st[], int next_st[]) {
	MATRIX res = MATRIX();
	FOR(i, 0, 2) {
		FOR(j, 0, 2) {
			if (i - j == 2 || i - j == -2) continue;
			if (prev_st[j] == 0 && next_st[i] == 0) res.a[i][j] = 1;
		}
	}
	return res;
}

void mult(MATRIX &A, ll d[]) {
	ll d2[3] = { 0, };
	FOR(i, 0, 2)
		FOR(j, 0, 2)
		d2[i] += A.a[i][j] * d[j], d2[i] %= MOD;
	FOR(i, 0, 2) d[i] = d2[i];
}

void pro() {
	ll d[3] = { 0,1,0 }, last = 1;
	int state[3] = { 0, }, next_state[3] = { 0, };
	FOR(i, 1, n * 2) {
		FOR(j, 0, 2) next_state[j] = state[j];
		if (obs[i].flag == 0) {
			next_state[obs[i].stair]++;
			if (next_state[obs[i].stair] == 1) {
				if (last < obs[i].idx) {
					MATRIX A = make(state, state);
					A = f(A, obs[i].idx - 1 - last);
					mult(A, d);
					last = obs[i].idx - 1;
				}
				MATRIX A = make(state, next_state);
				if (last < obs[i].idx) mult(A, d);
				last = obs[i].idx;
			}
		}
		else {
			next_state[obs[i].stair]--;
			if (next_state[obs[i].stair] == 0) {
				MATRIX A = make(state, state);
				A = f(A, obs[i].idx - last);
				mult(A, d);
				last = obs[i].idx;
			}
		}
		FOR(j, 0, 2) state[j] = next_state[j];
		FOR(j, 0, 2) if (state[j] == 1) d[j] = 0;
	}
	MATRIX A = make(state, state);
