int qpow(int a, int b) {

    int res = 1;

    for (; b; b >>= 1, a = 1ll * a * a % MOD)

        if (b & 1)

            res = 1ll * res * a % MOD;

    return res;

}

void dft(vector<int> &a) {

    // n为2的倍数

    int n = a.size();

    if ((int)(rev.size()) != n) {

        int k = __builtin_ctz(n) - 1;

        rev.resize(n);

        for (int i = 0; i < n; ++i)

            rev[i] = rev[i >> 1] >> 1 | (i & 1) << k;

    }

    for (int i = 0; i < n; ++i)

        if (rev[i] < i)

            swap(a[i], a[rev[i]]);

    if ((int)(roots.size()) < n) {

        int k = __builtin_ctz(roots.size());

        roots.resize(n);

        while ((1 << k) < n) {

            int e = qpow(3, (MOD - 1) >> (k + 1));

            for (int i = 1 << (k - 1); i < (1 << k); ++i) {

                roots[2 * i] = roots[i];

                roots[2 * i + 1] = 1ll * roots[i] * e % MOD;

            }

            ++k;

        }

    }

    for (int k = 1; k < n; k *= 2) {

        for (int i = 0; i < n; i += 2 * k) {

            for (int j = 0; j < k; ++j) {

                int u = a[i + j];

                int v = 1ll * a[i + j + k] * roots[k + j] % MOD;

                int x = u + v;

                if (x >= MOD)

                    x -= MOD;

                a[i + j] = x;

                x = u - v;

                if (x < 0)

                    x += MOD;

                a[i + j + k] = x;

            }

        }

    }

}

void idft(vector<int> &a) {

    int n = a.size();

    reverse(a.begin() + 1, a.end()); // ?

    dft(a);

    int inv = qpow(n, MOD - 2);

    for (int i = 0; i < n; ++i)

        a[i] = 1ll * a[i] * inv % MOD;

}

