ll gcd (ll a, ll b, ll & x, ll & y) {

    if (a == 0) {

        x = 0; y = 1;

        return b;

    }

    ll x1, y1;

    ll d = gcd (b%a, a, x1, y1);

    x = y1 - (b / a) * x1;

    y = x1;

    return d;

}



ll invmod(ll a, ll modulo) {

    ll x, y;

    ll g = gcd (a, modulo, x, y);

    if (g != 1)

    {

        return -1;

    }

    else {

        x = (x % modulo + modulo) % modulo;

        return x;

    }

}



