typedef long long ll;

const int MOD = 998244353;

ll bigMod (ll a, ll e) {
  if (e == -1) e = MOD - 2;
  ll ret = 1;
  while (e) {
    if (e & 1) ret = ret * a % MOD;
    a = a * a % MOD, e >>= 1;
  }
  return ret;
}

int t, m; ll n;
map <ll, vector <ll>> paths, chains;

vector <ll> getChains (ll x) {
  if (chains.find(x) != chains.end()) return chains[x];
  if (!x) return chains[x] = {};
  if (x == 1) return chains[x] = {1};
  if (x == 2) return chains[x] = {1, 1};
  int h = 62; while (~x & 1LL << h) --h;
  vector <ll> res(h + 1); 
  res[0] = 1, res[h] = (x - (1LL << h) + 1) % MOD;
  for (int i = 1; i < h; ++i) res[i] = (1LL << i) % MOD;
  return chains[x] = res;
}

vector <ll> call (ll x) {
  if (paths.find(x) != paths.end()) return paths[x];
  if (!x) return paths[x] = {};
  if (x == 1) return paths[x] = {1};
  if (x == 2) return paths[x] = {2, 1};
  int h = 62; while (~x & 1LL << h) --h;
  ll lastLevel = x - (1LL << h) + 1, L, R;
  if (lastLevel > (1LL << (h - 1))) L = (1LL << h) - 1, R = x - 1 - L;
  else R = (1LL << (h - 1)) - 1, L = x - 1 - R;
  vector <ll> res(h << 1 | 1), chainL = getChains(L), chainR = getChains(R);
  res[0] = 1;
  for (int i = 0; i < chainL.size(); ++i) {
    for (int j = 0; j < chainR.size(); ++j) {
      ll here = chainL[i] * chainR[j] % MOD;
      res[i + j + 2] += here;
    }
  }
  for (int i = 0; i < chainL.size(); ++i) res[i + 1] += chainL[i];
  for (int i = 0; i < chainR.size(); ++i) res[i + 1] += chainR[i];
  vector <ll> pathsL = call(L);
  for (int i = 0; i < pathsL.size(); ++i) res[i] += pathsL[i];
  vector <ll> pathsR = call(R);
  for (int i = 0; i < pathsR.size(); ++i) res[i] += pathsR[i];
  for (auto &it : res) it %= MOD;
  return paths[x] = res;
}

int main() {
  cin >> t;
  while (t--) {
    cin >> n >> m;
    vector <ll> vec = call(n);
    vector <ll> ways(vec.size());
    for (int i = 1; i <= m; ++i) {
      ll one = 1, two = 1;
      for (int j = 0; j < vec.size(); ++j) {
        one = one * i % MOD, two = two * (i - 1) % MOD;
        ways[j] += i * (one - two) % MOD;
      }
    }
    for (auto &x : ways) x %= MOD, x += MOD, x %= MOD;
    ll ans = 0;
    for (int i = 0; i < vec.size(); ++i) ans = (ans + vec[i] * ways[i] % MOD * bigMod(m, n - i - 1)) % MOD;
    cout << ans << '\n';
  }
  return 0;
}

