void dfs(int d, int used, LL s)
{
    if(s > S) return;
	if(d == m)
	{
		cnt[used][s]++;
		return;
	}
	dfs(d + 1, used, s);
	dfs(d + 1, used, s + a[d]);
	if(a[d] < 19) dfs(d + 1, used + 1, s + fac[a[d]]);
}

void dfs2(int d, int used, LL s)
{
    if(s > S) return;
	if(d == n)
	{
		for(int i = 0; i + used <= k; i++) if(cnt[i].count(S - s)) ans += cnt[i][S - s];
		return;
	}
	dfs2(d + 1, used, s);
	dfs2(d + 1, used, s + a[d]);
	if(a[d] < 19) dfs2(d + 1, used + 1, s + fac[a[d]]);
}

