Mint fast(int n, int m, int b0) {
    Mint tot = 1;
    for (int i = 0; i < n; i++) {
        tot *= Mint(m);
    }
    if (b0 >= m) {
        return tot;
    }
    vector<Mint> f(n);
    for (int cnt_up = 0; cnt_up <= n; cnt_up++) {
        int cnt_dn = b0 + cnt_up + 1;
        if (cnt_up + cnt_dn <= n) {
            f[cnt_up + cnt_dn - 1] += cat(cnt_dn, cnt_up, m - b0);
        }
    }

    vector<Mint> ct((n / 2) + 1, 0);
    ct[0] = 1;
    for (int j = 1; 2 * j < n; j++) {
        ct[j] = cat(j, j, m + 1);
    }
    ct = fps_inv(ct);
    vector<Mint> f2((n / 2) + 1);
    for (int i = 0; i < n; i++) {
        if ((i + 1) % 2 == (b0 + 1) % 2) {
            f2[i / 2] = f[i];
        }
    }
    f2 = convolve(f2, ct);

    vector<Mint> pw1(n + 1, 1);
    vector<Mint> pw0(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        pw1[i] = pw1[i - 1] * (m - 1);
        pw0[i] = pw0[i - 1] * m;
    }
    for (int i = 1; i <= n; i++) {
        if (i >= b0 + 1 && (i - b0 - 1) % 2 == 0) {
            int cnt_up = (i - b0 - 1) / 2;
            tot -= ((i - 1) / 2 < f2.size() ? f2[(i - 1) / 2] : Mint(0)) * pw1[cnt_up] * pw0[n - i];
        }
    }
    return tot;
}

