    int n, m, b0;
    cin >> n >> m >> b0;
    //cout << slow(n, m, b0) << "\n";
    cout << fast(n, m, b0) << "\n";
}

void init() {
    fact[0] = 1;
    for (int i = 1; i < M; i++) {
        fact[i] = fact[i - 1] * i;
    }
    inv[M - 1] = Mint(1) / fact[M - 1];
    for (int i = M - 2; i >= 0; i--) {
        inv[i] = inv[i + 1] * (i + 1);
    }
}

