    linked_list &operator=(const linked_list &) = delete;



    linked_list(const linked_list &copy) = delete;



    linked_list() {

        head = nullptr;

        tail = nullptr;

        length = 0;

    }



    linked_list(int value1, int value2 = 0) {

        length = 2;

        head = new node{};

        tail = new node{};

        this->tail->data = value2;

        this->head->data = value1;

        tail->next = nullptr;

        head->next = nullptr;

    }



    ~linked_list() {

        delete_linked_list(head);

    }



    void print() {

        if (length == 0)

           return;

        node *temp_head = head;

        while (temp_head != nullptr) {

            cout << temp_head->data << " ";

            temp_head = temp_head->next;

        }

        cout << line;

    }



    node *get_nth_from_front(int index) {

        index--;

        if (index < 0 || index > length)

            throw length_error("out of range");

        else {

            node *temp_head = head;

            while (index--) {

                temp_head = temp_head->next;

            }

            return temp_head;

        }

    }



    node *get_nth_form_back(int index) {

        return get_nth_from_front(length - index + 1);

    }



    void insert_end(int value) {

        if(length==0)

        {

            head=new node{};

            head->data=value;

            head->next=nullptr;

        }

        else if(length==1)

        {

            tail=new node{};

            tail->data=value;

            head->next=tail;

            tail->next= nullptr;

        }

        else {

            node *temp = new node{};

            temp->data = value;

            temp->next = nullptr;

            tail->next = temp;

            swap(tail, temp);

        }

        length++;

    }



    void insert_front(int value)

    {

        if(length==0)

        {

            head=new node{};

            head->data=value;

            head->next=nullptr;

        }

        else if(length==1)

        {

            tail=new node{};

            head->next=tail;

            tail->data=value;

            tail->next= nullptr;

            swap(tail,head);

        }

        else

        {

            node *temp = new node{};

            temp->data = value;

            temp->next = head;

            swap(head, temp);

        }

        length++;

    }

    void delete_head() {

        node *temp_head = head;

        temp_head = temp_head->next;

        delete head;

        head = new node{};

        head = temp_head;

        length--;

    }

    void delete_back()

    {

        node*temp_head=head;

        int temp_length=length-1;

        while(length--)

        {

            temp_head=temp_head->next;

        }

        delete tail;

        tail=new node{};

        tail=temp_head;

        tail->next=nullptr;

        length--;

    }

    void delete_nth_element(int index)

    {

        if(index==1)

            delete_head();

        else if(index==length)

            delete_back();

        else {

            node *prev = get_nth_from_front(index - 1);

            node *to_delete = prev->next;

            prev->next = prev->next->next;

            delete to_delete;

            length--;

        }

    }

