	}

	Z ans = 0;

	for (r = 1; r <= n; ++r) {

		Z res = power(Z(2), n) - calc();

		ans += res;

	}

	ans = (ans - 1) / power(Z(2), n);

	cout << ans.x << "\n";

	return 0;

}

