const int MAXN = 1e5 + 5;
typedef long long ll;
int n, k;
ll a[12][MAXN];
void update(int i, int j, ll v)
{
    while(i <= n + 1) {
        a[j][i] += v;
        i += i & (-i);
    }
}
ll query(int i, int j)
{
    if(i == 0) return 0;
    return a[j][i] + query(i - (i & -i), j);
}
int main(int argc, char const *argv[])
{
    scanf("%d%d", &n, &k);
    update(1, 0, 1);
    for(int i = 0; i < n; ++i) {
        int x;
        scanf("%d", &x);
        x++;
        for(int j = k + 1; j > 0; --j)
            update(x, j, query(x, j - 1));
    }
    printf("%lld\n", query(n + 1, k + 1));
    return 0;
}

