ll binom(ll n, ll k){
 ll ans = 1;
 ll t=1;
 for(ll i = 1; i <= min(k,n-k); i++) ans *= (n-k+i), ans %= MOD, t*=i, t%=MOD;
 Log("ans",ans,"t",t);
 Log("modi",mod_inverse(t,MOD));
 Log("ans",ans);
 ans *= mod_inverse(t,MOD);
 return ans % MOD;
}
