int dfs(int state, int d) {
    if (dp[state]) return dp[state];
    if (state == 1) return dp[state] = 1;
    dp[state] = INF;
    int cc = __builtin_popcount(state), ns = state & ~(1 << d) | 1 << (d - 1);
