vector<vector<i64>> matrixMul(vector<vector<i64>> &a, vector<vector<i64>> &b,
                              i64 mod) {
    int n = (int)a.size();
    int m = (int)b[0].size();
    vector<vector<i64>> c(n, vector<i64>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            for (int k = 0; k < (int)b.size(); k++) {
                c[i][j] = (c[i][j] + a[i][k] * b[k][j] % mod) % mod;
            }
        }
    }
    return c;
}

vector<vector<i64>> matrixPow(vector<vector<i64>> &a, int n) {
    int m = (int)a.size();
    vector<vector<i64>> f(m, vector<i64>(m));
    for (int i = 0; i < m; i++) {
        f[i][i] = 1;
    }
    while (n) {
        if (n & 1) {
            f = matrixMul(f, a, MOD);
        }
        a = matrixMul(a, a, MOD);
        n /= 2;
    }

    return f;
}

