i64 phi(i64 a) {
    i64 t = a, ans = a;
    i64 d = 2;

    while (d * d <= t) {
        i64 cnt = 0;

        while (t % d == 0) {
            t /= d;
            cnt++;
        }
        if (cnt > 0) {
            ans -= ans / d;
        }
        d++;
    }
    if (t > 1) {
        ans -= ans / t;
    }
    return ans;
}

vector<int> zfunc(string &s) {
    int n = (int)s.size();
    vector<int> z(n);
    int l = 0, r = 0;
    for (int i = 1; i < n; i++) {
        if (i <= r) {
            z[i] = min(r - i, z[i - l]);
        }
        while (i + z[i] < n && s[i + z[i]] == s[z[i]]) {
            z[i]++;
        }
        if (i + z[i] > r) {
            r = i + z[i];
            l = i;
        }
    }
    return z;
}

vector<int> prefix_func(string &s) {
    int n = (int)s.size();
    vector<int> pi(n);
    for (int i = 1; i < n; i++) {
        int j = pi[i - 1];
        while (j > 0 && s[i] != s[j]) {
            j = pi[j - 1];
        }
        if (s[i] == s[j]) {
            j++;
        }
        pi[i] = j;
    }
    return pi;
}

void kmp(string &s, string &t) {
    auto pi = prefix_func(t);
    int j = 0;

    int n = (int)s.size();
    vector<int> p(n);
    for (int i = 0; i < n; i++) {
        while (j > 0 && s[i] != t[j]) {
            j = pi[j - 1];
        }
        if (s[i] == t[j]) {
            j++;
        }

        p[i] = j;
    }
}

