vector<vector<i64>> mul(const vector<vector<i64>> m1,
                        const vector<vector<i64>> m2) {
    i64 n = m1.size();
    i64 m = m1[0].size();
    i64 k = m2[0].size();
    assert(m2.size() == m);

    vector<vector<i64>> m3(n, vector<i64>(k, 0));

    for (i64 i = 0; i < n; i++) {
        for (i64 j = 0; j < k; j++) {
            for (i64 z = 0; z < m; z++) {
                m3[i][j] = (m3[i][j] + m1[i][z] * m2[z][j] % MOD) % MOD;
            }
        }
    }
    return m3;
}

vector<vector<i64>> exp(const vector<vector<i64>> m, i64 d) {
    if (d == 0)
        return I;
    else if (d % 2)
        return mul(exp(m, d - 1), m);

    auto m1 = exp(m, d / 2);
    return mul(m1, m1);
}

void solve() {
    i64 n;
    cin >> n;

    vector<i64> a(n);
    i64 sum = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sum += a[i];
    }
    if (sum % n) {
        cout << "No\n";
        return;
    }
    sum /= n;

    vector<int> in(32, 0), out(32, 0), in1(32, 0), out1(32, 0);

    for (int i = 0; i < n; i++) {
        int flag = 0;
        if (a[i] == sum) continue;
        for (int j = 0; j < 31; j++) {
            if (a[i] + (1 << j) == sum) {
                in1[j]++;
                flag = 1;
                continue;
            }
            if (a[i] - (1 << j) == sum) {
                out1[j]++;
                flag = 1;
                continue;
            }
        }
        if (flag) continue;

        for (int j = 0; j < 31; j++) {
            for (int k = 0; k < 31; k++) {
                if (a[i] + (1 << j) - (1 << k) == sum) {
                    in[j]++;
                    out[k]++;
                    flag = 1;
                }
            }
        }
        if (!flag) {
            cout << "No\n";
            return;
        }
    }

    for (int i = 30; i >= 0; i--) {
        if (in[i + 1] == out[i + 1]) {
            in[i] += in1[i];
            out[i] += out1[i];
            continue;
        }

        if (in[i + 1] > out[i + 1]) {
            int d = in[i + 1] - out[i + 1];
            if (out1[i] < d) {
                cout << "No\n";
                return;
            } else {
                out1[i] -= d;
                in1[i] += d;
            }
        }
        if (in[i + 1] < out[i + 1]) {
            int d = out[i + 1] - in[i + 1];
            if (in1[i] < d) {
                cout << "No\n";
                return;
            } else {
                in1[i] -= d;
                out1[i] += d;
            }
        }
        in[i] += in1[i];
        out[i] += out1[i];
    }

    if (in[0] == out[0]) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
}

