void push(node &f, int v, int p) {

	if(f.v1 == -inf) {f.v1 = v, f.p1 = p; return;}

	if(f.p1 == p) {if(v > f.v1) f.v1 = v, f.p1 = p; return;}

	if(v >= f.v1) {f.v2 = f.v1, f.p2 = f.p1, f.v1 = v, f.p1 = p; return;}

	if(v > f.v2) f.v2 = v, f.p2 = p;

}



