					dp[j] += dp[j - 1];

				}

				dp -= 2;

			} else {

				db tmp = {0, 0};

				for(int j = i;j >= 1;--j) {

					dp[j] += tmp;

					tmp = dp[j];

					dp[j] += dp[j +  1];

				}

			}

			i += 1;

			continue;

		}

		if(c != '>') {

			for(int j = 1;j <= i;++j) {

				dp[j] += dp[j - 1];

			}

			-- dp;

		} else {

			for(int j = i;j >= 1;--j) {

				dp[j] += dp[j + 1];

			}

		}

	}

	db ans = {0, 0};

	for(int i = 1;i <= n;++i) {

		ans += dp[i];

	}

	printf("%.20lf\n", ans.exp + std::log2(ans.value));

}

