    }
    p[v] = getp(p[v]);
    return p[v];
}

bool join(int u, int v) {
    u = getp(u);
    v = getp(v);
    if (u == v) {
        return false;
    }
    if (r[u] < r[v]) {
        swap(u, v);
    }
    r[u] += r[v];
    p[v] = u;
    return true;
}

