int gcd(int a, int b)
{
	return b ? gcd(b, a % b) : a;
}
int fac[200100];
int mfac[200100];
#define MOD 998244353
int modinv(int n, int m = MOD - 2)
{
	if (m == 0)
		return 1;
	if (m % 2)
		return n * modinv(n, m - 1) % MOD;
	int v = modinv(n, m / 2);
	return v * v % MOD;
}
int ncr(int n, int r)
{
	if (n < r)
		return 0;
	int v = fac[n];
	v *= mfac[r];
	v %= MOD;
	v *= mfac[n - r];
	v %= MOD;
	return v;
}
int npr(int n, int r)
{
	if (n < r)
		return 0;
	int v = fac[n];
	v *= mfac[n - r];
	v %= MOD;
	return v;
}
