	cin.tie(NULL);
	fac[0] = 1;
	mfac[0] = 1;
	int i;
	for (i = 1; i <= 200000; i++)
	{
		fac[i] = fac[i - 1] * i % MOD;
		mfac[i] = modinv(fac[i]);
	}
	int T;
	cin >> T;
	while (T--)
	{
		int N, K;
