		for (i = 1; i <= N; i++)
		{
			int a;
			cin >> a;
			if (i == N && a == -1)
			{
				a = N;
			}
			if (a != -1)
			{
				if (a > i)
					ans = 0;
				if (i == N && a < N)
					ans = 0;
				if (ans == 0)
					continue;
				int difa = a - befa;
				int difi1 = i - befa;
				int dif2i = befi - befa;
				int j;
				int curcnt = 0;
				for (j = 0; j <= min(dif2i, difa); j++)
				{
					int pick = ncr(dif2i, j) * ncr(difi1 - dif2i, difa - j) % MOD;
					pick *= npr(difi1-dif2i, j) * npr(difi1 - j, difa - j) % MOD;
					curcnt += pick;
					curcnt %= MOD;
				}
				ans *= curcnt;
				ans %= MOD;
				befa = a;
