      }
    }
  }
  return ret;
}

char get_map(int id)
{
  if (id < 0 || id >= len*3)
  {
    return 0;
  }

  return mp[id%3][id/3];
}

void pre()
{
  MEM(dpx);
  x = dpx[0];
  y = dpx[1];
  x[0][get_num()] = 1;
}

void add_from(int& a,int b)
{
  a = (a+b) % P;
}

void gao(int id, int mk, int ch)
{
  int val[2];
  val[0] = x[0][mk];
  val[1] = x[1][mk];
  if ('O' == ch || 'X' == ch)
  {
    mk |= 1 << 6;
  }

  if (mk & 1)
  {
    int m = mk >> 1;
    add_from(y[0][m], val[0]);
    add_from(y[1][m], val[1]);
    return ;
  }

  if ((mk & 3) == 0 && (id%3 != 2))
  {
    int m = (mk | 3) >> 1;
    add_from(y[1][m], val[1]);
    int ok = 0;
    if (id % 3 == 0 && get_map(id+2) == 'O')
    {
      ok = 1;
    }
    else if (id % 3 == 1 && get_map(id-1) == 'O')
    {
      ok = 1;
    }
    add_from(y[ok][m], val[0]);
  }
  if ((mk & 9) == 0)
  {
    //printf("id %d mk 0x%x\n", id, mk);
    int m = (mk | 9) >> 1;
    add_from(y[1][m], val[1]);
    int ok = 0;
    if ('O' == get_map(id-3) || 'O' == get_map(id+6))
    {
      ok = 1;
    }
    add_from(y[ok][m], val[0]);
  }
}

void doit()
{
  pre();

  for (int i = 0; i < len*3; ++i)
  {
    memset(y, 0, sizeof(dpx[0]));
    for (int j = 0; j < (1<<6); ++j)
    {
      if (x[0][j] || x[1][j])
      {
        //printf("%d %d %d %d\n", i, j, x[0][j], x[1][j] );
        gao(i, j, get_map(i+6));
      }
    }
    swap(x, y);
  }
  printf("%d\n", x[1][0]);
}

