template <typename T>
class graph {
  public:
  struct edge {
    int from;
    int to;
    T cost;
  };

  vector<edge> edges;
  vector< vector<int> > g;
  int n;

  function<bool(int)> ignore;

  graph(int _n) : n(_n) {
    g.resize(n);
    ignore = nullptr;
  }

  virtual int add(int from, int to, T cost) = 0;

  virtual void set_ignore_edge_rule(const function<bool(int)> &f) {
    ignore = f;
  }

  virtual void reset_ignore_edge_rule() {
    ignore = nullptr;
  }
};

template <typename T>
class undigraph : public graph<T> {
  public:
  using graph<T>::edges;
  using graph<T>::g;
  using graph<T>::n;

  undigraph(int _n) : graph<T>(_n) {
  }

  int add(int from, int to, T cost = 1) {
    assert(0 <= from && from < n && 0 <= to && to < n);
    int id = (int) edges.size();
    g[from].push_back(id);
    g[to].push_back(id);
    edges.push_back({from, to, cost});
    return id;
  }
};

template <typename T>
class dfs_undigraph : public undigraph<T> {
  public:
  using undigraph<T>::edges;
  using undigraph<T>::g;
  using undigraph<T>::n;
  using undigraph<T>::ignore;

  vector<int> pv;
  vector<int> pe;
  vector<int> order;
  vector<int> pos;
  vector<int> end;
  vector<int> sz;
  vector<int> root;
  vector<int> depth;
  vector<int> min_depth;
  vector<T> dist;
  vector<int> was;
  int attempt;

  dfs_undigraph(int _n) : undigraph<T>(_n) {
  }

  void init() {
    pv = vector<int>(n, -1);
    pe = vector<int>(n, -1);
    order.clear();
    pos = vector<int>(n, -1);
    end = vector<int>(n, -1);
    sz = vector<int>(n, 0);
    root = vector<int>(n, -1);
    depth = vector<int>(n, -1);
    min_depth = vector<int>(n, -1);
    dist = vector<T>(n);
    was = vector<int>(n, -1);
    attempt = 0;
  }

  void clear() {
    pv.clear();
    pe.clear();
    order.clear();
    pos.clear();
    end.clear();
    sz.clear();
    root.clear();
    depth.clear();
    min_depth.clear();
    dist.clear();
    was.clear();
  }

  private:
  void do_dfs(int v) {
    was[v] = attempt;
    pos[v] = (int) order.size();
    order.push_back(v);
    sz[v] = 1;
    min_depth[v] = depth[v];
    for (int id : g[v]) {
      if (id == pe[v] || (ignore != nullptr && ignore(id))) {
        continue;
      }
      auto &e = edges[id];
      int to = e.from ^ e.to ^ v;
      if (was[to] == attempt) {
        min_depth[v] = min(min_depth[v], depth[to]);
        continue;
      }
      depth[to] = depth[v] + 1;
      dist[to] = dist[v] + e.cost;
      pv[to] = v;
      pe[to] = id;
      root[to] = (root[v] != -1 ? root[v] : to);
      do_dfs(to);
      sz[v] += sz[to];
      min_depth[v] = min(min_depth[v], min_depth[to]);
    }
    end[v] = (int) order.size() - 1;
  }

  void do_dfs_from(int v) {
    ++attempt;
    depth[v] = 0;
    dist[v] = T{};
    root[v] = v;
    pv[v] = pe[v] = -1;
    do_dfs(v);
  }

  public:
  void dfs(int v, bool clear_order = true) {
    if (pv.empty()) {
      init();
    } else {
      if (clear_order) {
        order.clear();
      }
    }
    do_dfs_from(v);
  }

  void dfs_all() {
    init();
    for (int v = 0; v < n; v++) {
      if (depth[v] == -1) {
        do_dfs_from(v);
      }
    }
    assert((int) order.size() == n);
  }
};

template <typename T>
vector<bool> find_bridges(dfs_undigraph<T> &g) {
  g.dfs_all();
  vector<bool> bridge(g.edges.size(), false);
  for (int i = 0; i < g.n; i++) {
    if (g.pv[i] != -1 && g.min_depth[i] == g.depth[i]) {
      bridge[g.pe[i]] = true;
    }
  }
  return bridge;
}
};

const int maxN = 1e5+2;
using bt = bitset<maxN>;

lli solve(const int n,const map<int, pair<int,vector<bool>>> &components){
  lli ans=INF;
  bt cur;
  cur[0]=true;
  cur[n+1]=true;
  vector<vector<bool>> cuts;
  auto addComponent=[&](int size,int freq){
    lli b=1,val=0;
    while(val+b<=freq){
      cur|=cur<<(b*size);
      val+=b;
      b*=2;
    }
    cur|=cur<<((freq-val)*size);
  };

  for(const auto &z:components){
    addComponent(z.X,z.Y.X-1);
    cuts.pb(z.Y.Y);
  }
  auto f=[&](lli s){
    dbg(s,n-s);
    ans=min(ans,s*s+(n-s)*(n-s));
  };
  y_combinator([&](const auto &self,int l,int r,bt cur)->void{
    if(l==r){
      auto add=[&](const int addSize){
        if(addSize>=n/2){
          f(addSize);
          return;
        }
        const int v=n/2-1-addSize;
        const lli s=cur._Find_next(v);
        if(s+addSize>=n)
          return;
        f(s+addSize);
      };
      const auto &current = cuts[l];
      const int curSize = current.size()-1;
      for(int i=0;i<=curSize;++i){
        if(current[i])
          add(i);
      }
      if(l==0){
        add(0);
        add(curSize);
      }
      return;
    }
    const int mid = (l+r)/2;
    bt LC=cur,RC=cur;
    for(int i=l;i<=mid;++i)
      RC|=RC<<(cuts[i].size()-1);
    for(int i=mid+1;i<=r;++i)
      LC|=LC<<(cuts[i].size()-1);
    self(l,mid,LC);
    self(mid+1,r,RC);
  })(0,sz(cuts)-1,cur);
  return ans;
}

