    lli offset=-c;
    for(int i=0;i<n;++i){
      if(g.pe[i]!=-1)
        continue;
      offset+=c;
      totalBridges++;
      const int s=g.sz[i];
      auto it=components.find(s);
      if(it==components.end())
        components[s]={0,vector<bool>(s+1,0)};
      components[g.sz[i]].X++;
    }

    for(int id=0;id<m;++id){
      if(!bridges[id])
        continue;
      totalBridges++;
      const auto &e = g.edges[id];
      int u=e.from, p=e.to;
      if(g.pe[u]!=id){
        swap(u,p);
        assert(g.pe[u]==id);
      }
      // dbg(u,p);
      const int root = g.root[u];
      const int s=g.sz[u],tot=g.sz[root];
      components[tot].Y[s]=true;
      components[tot].Y[tot-s]=true;
    }
    if(totalBridges==0){
      cout<<-1<<endl;
      continue;
    }
    const lli ans=solve(n,components)+offset;
    cout<<ans<<endl;
}
    return 0;
}

