int a[200050ll]={0};

int tree[800050ll]={0};

void build(int n,int tl,int tr){

	if(tl==tr){

		tree[n]=a[tl];

		return;

	}

	int tm=(tl+tr)/2;

	build(2*n,tl,tm);

	build(2*n+1,tm+1,tr);

	tree[n]=max(tree[2*n],tree[2*n+1]);

}

int mxn(int n,int tl,int tr,int l,int r){

	if(l<=tl && tr<=r){

		return tree[n];

	}

	if(tr<l || r<tl)	return -1;



	int tm=(tr+tl)/2;

	int x=mxn(2*n,tl,tm,l,min(tm,r));

	int y=mxn(2*n+1,tm+1,tr,max(tm,l),r);

	return max(x,y);

}



