  }

  int mu[m+1]={};

  mu[1]=1;

  Z res=0;

  for(int i=1;i<=m;i++)

    for(int j=i*2;j<=m;j+=i)

      mu[j]-=mu[i];

   for(int d=1;d<=m;d++)

   {

    if(mu[d]==0)

      continue;

      int s=m/d;

      int suml=0;

      for(int i=0;i<n;i++)

        suml+=l[i]/d+1;

