#if use_dinic==1

struct DINIC{

	#define qpqpqpqp N*2+10

	const int MAXN=qpqpqpqp;

    const int inf=2147483647;

	vector<long long>Stream,S2;

	int Arc[qpqpqpqp],Deep[qpqpqpqp];

	vector< pair<int,int> >Edge[qpqpqpqp];

    vector<array<int,3>>ee;

	inline bool Bfs(int Start,int End)

	{

	    queue<int>Queue;

	    memset(Deep,0,sizeof(Deep));

	    Queue.push(Start);

	    Deep[Start]=1;

	    int i;

	    while(!Queue.empty())

	    {

	        int Top;

	        Top=Queue.front();

	        Queue.pop();

	        for(i=0;i<Edge[Top].size();i++)

	        {

	            if(!Deep[Edge[Top][i].first]&&Stream[Edge[Top][i].second])

	            {

	                Deep[Edge[Top][i].first]=Deep[Top]+1;

	                Queue.push(Edge[Top][i].first);

	                if(Edge[Top][i].first==End)

	                {

	                    return true;

	                }

	            }

	        }

	    }

	    return false;

	}

	inline long long Dfs(int Now,int End,long long Min)

	{

	    if(Now==End)

	    {

	        return Min;

	    }

	    for(int &i=Arc[Now];i<Edge[Now].size();i++)

	    {

	        int U,V;

	        U=Edge[Now][i].first;

	        V=Edge[Now][i].second;

	        if(Deep[U]==Deep[Now]+1&&Stream[V])

	        {

	            int MinStream=0;

	            MinStream=min(Min,Dfs(U,End,min(Min,Stream[V])));

	            if(!MinStream)

	            {

	                continue;

	            }

	            Stream[V]-=MinStream;

	            Stream[V^1]+=MinStream;

	            return MinStream;

	        }

	    }

	    return 0;

	}

	inline long long Dinic(int Start,int End)

	{

	    memset(Arc,0,sizeof(Arc));

	    memset(Deep,0,sizeof(Deep));

	    long long Return;

	    Return=0;

	    long long Delta;

	    while(Bfs(Start,End))

	    {

	        memset(Arc,0,sizeof(Arc));

	        while(Delta=Dfs(Start,End,inf))

	        {

	            Return+=Delta;

	        }

	    }

	    return Return;

	}

	int Count=0;

    void addedge(int u,int v,int w=1)

    {

		Stream.push_back(w);

		S2.push_back(0);

        ee.push_back({u,v,w});

		Edge[u].push_back(pair<int,int>(v,Count));

		++Count;

    }

	void add_edge(int u,int v,int w=1)

	{

        addedge(u,v,w);

        addedge(v,u,0);

	}

    void init()

    {

        Stream.clear();

        S2.clear();

        memset(Arc,0,sizeof(Arc));

        memset(Deep,0,sizeof(Deep));

        for(int x=0;x<MAXN;x++)

        {

            vector<pair<int,int>>pp;

            swap(Edge[x],pp);

        }

	    Count=0;

    }

    DINIC(){init();}

    void fill(DINIC a)

    {

        Stream=a.Stream;

        S2=a.S2;

        memset(Arc,0,sizeof(Arc));

        memset(Deep,0,sizeof(Deep));

        for(int x=0;x<MAXN;x++)

        {

            Arc[x]=a.Arc[x];

            Deep[x]=a.Deep[x];

            Edge[x]=a.Edge[x];

        }

	    Count=a.Count;

    }

    #undef qpqpqpqp

};

