      long long mn = min(a[i], min(a[i - 1], a[i - 2]));
      if (mx - mn == w[i - 2]) {
        found = true;
        break;
      }
    }
    assert(found);
  }
  long long mn = *min_element(a.begin(), a.end());
  for (int i = 0; i < n; i++) {
    a[i] -= mn;
  }
  for (int i = 0; i < n; i++) {
    if (i > 0) {
      cout << " ";
    }
    cout << a[i];
  }
  cout << '\n';
  return 0;
}

