int solve(int n, int m, ll b){
    if(all<=b) return 1;
    int l = n-1;
    ll sum = a[l];
    int r = 0;
    while(r<n && sum+a[r]<=b) sum+=a[r++];
    dp[l] = 1;
    di[l] = r;
    int ans = n;
    while(l>0){
        --l;
        sum+=a[l];
        while(sum>b){
            --r;
            if(r<0) r=n-1;
            sum-=a[r];
        }
        //cout<<"?"<<l<<' '<<r<<' '<<sum<<endl;
        if(l<r){
            dp[l] = dp[r]+1;
            di[l] = di[r];
        }else{
            dp[l] = 1;
            di[l] = r;
        }
        if(di[l]>=l) ans = min(ans, dp[l]);
    }
    return ans;
}

