ll bf(ll x, vector<ll> &a)

{

    ll l = 0, r = a.size() - 1, m;

    while (l != r)

    {

        m = (l + r + 1) / 2;

        if (a[m] > x)

            r = m - 1;

        else

            l = m;

    }

    if (a[l] != x)

