inline void update(int ind, int val) {
	for (++ind; ind < n + 5; ind += ind & -ind)
		fen[ind] = max(fen[ind], val);
}

inline int query(int ind) {
	int ans = 0;
	for (++ind; ind > 0; ind -= ind & -ind)
		ans = max(ans, fen[ind]);
	return ans;
}

inline void solve() {
	fill(fen, fen + n + 10, 0);
	cin >> n;
	for (int i = 1; i <= n; i++)
		cin >> A[i];

	stack<int> st;
	for (int i = n; i > 0; i--) {
		while (!st.empty() && A[st.top()] < A[i]) st.pop();
		if (!st.empty()) Q[st.top()].push_back(i);
