		f[i] = max((i > 1 ? 2 : 1), query(A[i]) + 1);
		for (int j : Q[i])
			update(A[j], f[j] + 1);

		update(A[i], f[i]);
		ans = max(ans, f[i]);
		Q[i].clear();
	}

	cout << ans << endl;
}

