constexpr int N = 1e5 + 1;

int n;

array<int, 3> a;

vector<pair<int64_t, int>> inp[3];



auto maxb(auto& a, const auto& b) { return a < b? a = b, 1: 0; }

auto minb(auto& a, const auto& b) { return a > b? a = b, 1: 0; }



struct DSU {

  void reset(int n) {

    memset(p, -1, n * sizeof *p);

  }



  auto operator[](int v) { return -p[getp(v)]; }

  auto operator[](pair<int, int> vu) { return getp(vu.first) == getp(vu.second); }

  auto operator()(int v) { return getp(v); }

  auto operator()(int v, int u) { return uni(v, u); }



private:

  int p[N];



  int getp(int v) {

    return p[v] < 0? v: p[v] = getp(p[v]);

  }



  bool uni(int u, int v) {

    if (p[v = getp(v)] < p[u = getp(u)]) {

      swap(u, v);

    }

    if (u == v) {

      return 0;

    }

    p[u] += p[v];

    p[v] = u;

    return 1;

  }

};



struct EList {

  int nxt[N];

  DSU dsu;



  void fill(int n) { for (int i = 0; i <= n; ++i) nxt[i] = i; dsu.reset(n + 1); }



  int getnext(int x) { return nxt[dsu(x)]; }



  void rm(int x) { auto t = nxt[dsu(x + 1)]; dsu(x, x + 1); nxt[dsu(x)] = t; }

} ava;



auto eval(array<int64_t, 3> w) {

  array<int, 3> cnt{};

  int64_t res{}, s{};

  ava.fill(n);

  int pos[]{inp[0].size(), inp[1].size(), inp[2].size()};

  while (s < a[0] + a[1] + a[2]) {

    int t = -1;

    int64_t r = -1ll << 63;

    for (int i = 0; i < 3; ++i) if (pos[i] && maxb(r, inp[i][pos[i] - 1].first + w[i])) {

      t = i;

    }

    if (t == -1) {

      break;

    }

    int d = inp[t][--pos[t]].second;

    d = ava.getnext(n - d);

    if (d < n) {

      ava.rm(d);

      res += r - w[t] >> 25;

      ++cnt[t], ++s;

    }

  }

  return pair{cnt, res};

}



int64_t solve() {

  array<array<int64_t, 2>, 3> bounds;

  fill_n(bounds.begin(), 3, array<int64_t, 2>{-1ll << 31 + 25, 1ll << 31 + 25});

  while (1) {

    int r{};

    array<int64_t, 3> mid{};

    for (int i = 0; i < 3; ++i)

    for (int a = 0; a < 2; ++a)

    for (int b = 0; b < 2; ++b) {

      int j = (i + 1) % 3, k = (i + 2) % 3;

      auto x = bounds[j][a], y = -bounds[k][b];

      if (bounds[i][0] <= y - x && y - x <= bounds[i][1]) {

        mid[k] += x, mid[j] += y;

        ++r;

      }

    }

    mid[0] /= r, mid[1] /= r, mid[2] /= r;

    for (int i = 0; i < 3; ++i) {

      int j = (i + 1) % 3, k = (i + 2) % 3;

      if (bounds[i][0] > mid[j] - mid[k] || mid[j] - mid[k] > bounds[i][1]) {

        return -1;

      }

    }

    auto [t, res] = eval(mid);

    if (t[0] + t[1] + t[2] != a[0] + a[1] + a[2]) {

      return -1;

    }

    if (t == a) {

      return res;

    }

    for (int i = 0; i < 3; ++i) {

      int j = (i + 1) % 3, k = (i + 2) % 3;

      t[j] > a[j] && t[k] < a[k] && minb(bounds[i][1], mid[j] - mid[k] - 1);

      t[j] < a[j] && t[k] > a[k] && maxb(bounds[i][0], mid[j] - mid[k] + 1);

    }

  }

}



