using namespace std;

using i64 = long long;
const int P = 998244353, N = 5050;

int c[N][N];

int solve() {
    int n;
    cin >> n;
    vector<int> p(n);
    map<int, int> cnt;
    for(int i = 0; i < n; i ++) {
        cin >> p[i];
        cnt[p[i]] ++;
    }

    int lst = -N;
    cnt[0] ++;

    vector<vector<int> > dp(4, vector<int>(n + 1));

    for(auto [x, y] : cnt) {
        vector<vector<int> > newdp(4, vector<int>(n + 1));
        if(lst == -N) {
            newdp[3][y - 1] = 1;
            lst = x - 1;
        }else if(x <= 0) {
            for(int i = 0; i < y; i ++)
                for(int j = i; j <= i; j ++)
                    newdp[1][y - 1 - i] += (dp[1][j] + dp[3][j]) * (i64)c[j][i] % P * c[y - 1][i] % P;

            for(int i = 0; i + 1 < y; i ++)
                for(int j = i; j <= i; j ++)
                    newdp[3][y - 2 - i] += dp[3][j] * (i64)c[j][i] % P * c[y - 1][i + 1] % P;
        }else{
            for(int i = 1; i <= y; i ++)
                for(int j = i; j <= i; j ++)
                    newdp[0][y - i] += (dp[1][j] + dp[3][j] + (i64)dp[0][j] + dp[2][j]) * (i64)c[j][i] % P * c[y - 1][i - 1] % P;

            for(int i = 0; i < y; i ++)
                for(int j = i; j <= i; j ++)
                    newdp[2][y - 1 - i] += (dp[2][j] + dp[3][j]) * (i64)c[j][i] % P * c[y - 1][i] % P;
        }
        if(lst != x - 1) return 0;

        //cout << dp[2][0] << " " << dp[3][0] << " " << c[0][0] % P << " " << c[y - 1][0] << "\n";
        swap(dp, newdp);
        lst = x;

        //cout << "[" << x << ", " << y << "]\n";
        //for(int i : {0, 1, 2, 3}) {
        //    for(int j = 0; j <= y; j ++)
        //        cout << dp[i][j] << " ";
        //    cout << "\n";
        //}
        //
        //cout << "\n";
    }
    return (dp[0][0] + dp[1][0] + (i64)dp[2][0] + dp[3][0]) % P;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    for(int i = 0; i < N; i ++) {
        c[i][0] = 1;
        for(int j = 1; j <= i; j ++)
            c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % P;
    }

    int T;
    cin >> T;
    while(T --) cout << solve() << "\n";
}

