ll power(ll x, ll y, ll p=mod) 

{ 

    ll res = 1;  

    x = x % p;  

    while (y > 0) 

    { 

        if (y & 1) 

            res = (res*x) % p; 

        y = y>>1; // y = y/2 

        x = (x*x) % p; 

    } 

    return res; 

} 



// Returns n^(-1) mod p 

ll modInverse(ll n, ll p=mod) 

{ 

    return power(n, p-2, p); 

} 



