ll nCrModPFermat(ll n, ll r, ll p=mod) 

{ 

   if (r==0) 

      return 1; 

    if(r>n)

      return 0;

    return (fac[n]* modInverse(fac[r], p) % p * modInverse(fac[n-r], p) % p) % p; 

}

