using i64 = long long;
using namespace std;

const int mod = 1e9 + 7;

int n, k, C[15][15], f[205][205][6][3];

int g[6] = {0, 0, 1, 0, 2, 4};
int T1[6][6] = {{1}, {1, 1}, {1, 2, 1}, {1, 2, 0, 1}, {1, 3, 2, 1, 1}, {1, 4, 4, 2, 4, 1}};
int T2[6][6] = {{1}, {0, 1}, {1, 0, 1}, {0, 0, 0, 1}, {0, 2, 0, 0, 1}, {2, 0, 4, 0, 0, 1}};

int upd(int x, int y) { return x + y >= mod ? x + y - mod : x + y; }
int get(int x) { return x - (x > 2); }
int dfs(int x, int y, int p, int q)
{
    if (y < 0 || y > get(p) * x * 3 + get(p))
        return 0;
    if (f[x][y][p][q] != -1)
        return f[x][y][p][q];
    int &ans = f[x][y][p][q];
    ans = 0;

    if (x == 0 && q == 0)
        return ans = (y == 0);
    if (q == 0)
        for (int t = 0; t <= g[p]; ++t)
            for (int i = 0; i <= get(p) * 3 - t * 2; ++i)
                ans = upd(ans, 1ll * dfs(x - 1, y - t - i, p, 2) * C[g[p]][t] % mod * C[get(p) * 3 - t * 2][i] % mod);

    if (q == 1)
        for (int i = 0; i <= p; ++i)
            if (T1[p][i])
                ans = upd(ans, 1ll * dfs(x, y - (get(p) - get(i)), i, 0) * T1[p][i] % mod);

    if (q == 2)
        for (int i = 0; i <= p; ++i)
            if (T2[p][i])
                ans = upd(ans, 1ll * dfs(x, y - ((get(p) - get(i)) / 2), i, 1) * T2[p][i] % mod);

    return ans;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    for (int i = 0; i <= 12; i++)
    {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++)
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
    }
    memset(f, -1, sizeof(f));

    int ans = dfs(n, k, 5, 2);
    for (int i = 1; i <= k; i++)
        ans = (i64)ans * i % mod;
    cout << ans << '\n';
}

