typedef long long ll;
ll n;int k,p;
int qp(int a,ll b){
	int res=1;
	b%=(p-1);
	while(b){
		if(b&1) res=(ll)res*a%p;
		a=(ll)a*a%p;b>>=1;
	}
	return res;
}
ll gcd(ll a,ll b){
	if(!b) return a;
	return gcd(b,a%b);
}
void inc(int &x,int v){if((x+=v)>=p) x-=p;}
void dec(int &x,int v){if((x-=v)<0) x+=p;}
int main(){
	n=read<ll>();k=read<int>();p=read<int>();
	if(n==1){puts("1");return 0;}
	if(k&1){
		int g=gcd(n-2,k);
		int res=qp(k,n);
		dec(res,qp(k-1,n));
		if(n&1) inc(res,g-1);
		else dec(res,g-1);
		printf("%d\n",res);
	}
	else{
		int g=gcd(n-2,k>>1);
		int res=qp(k,n);
		dec(res,qp(k-2,n));
		inc(res,qp(p-2,n));
		if(res&1) res=(res+p)>>1;
		else res>>=1;
		if(n&1) inc(res,(ll)qp(2,n-1)*g%p);
		else dec(res,(ll)qp(2,n-1)*g%p);
		printf("%d\n",res);
	}
	return 0;
}

