bool isprime(int x) {
    if (x % 2 == 0) {
        return false;
    }
    int temp = sqrt(x) + 1;
    for (int i = 3; i <= temp; i += 2) {
        if (x % i == 0) {
            return false;
        }
    }
    return true;
}

int main(int argc, const char * argv[]) {

    ss[1] = 2;
    cnt = 1;
    REP(i, 3, 10000) {
        if (isprime(i)) {
            ss[++cnt] = i;
        }
    }

    //cout << cnt << endl;
    REP(i, 1, cnt) {
        t[i] = ss[i] * ss[i];
    }

    getint(n);
    REP(i, 1, n) {
        getint(a[i]);
    }
    REP(i, 1, n) {
        if (a[i] < 0) {
            b[i] = -1;
            a[i] = -a[i];
        } else {
            b[i] = 1;
        }
    }
    REP(i, 1, n) {
        REP(j, 1, cnt) {
            if (a[i] < t[j]) {
                break;
            }
            while (a[i] % t[j] == 0) {
                a[i] /= t[j];
            }
        }
    }
    map<int, int>ss1, ss2;
    int ccnt = 1;
    REP(i, 1, n) {
        if (a[i] == 0) {
            aa[i] = 0;
        } else if (b[i] == 1) {
            if (ss1.count(a[i]) == 0) {
                ss1.insert(pii(a[i], ccnt));
                ccnt++;
            }
            aa[i] = ss1[a[i]];
        } else {
            if (ss2.count(a[i]) == 0) {
                ss2.insert(pii(a[i], ccnt));
                ccnt++;
            }
            aa[i] = ss2[a[i]];
        }
    }

    int counttime = 1;
    REP(i, 1, n) {
        set<int>s1,s2;
        int tans = 0;
        REP(j, i, n) {
            if (aa[j] == 0) {
                if (tans == 0) {
                    ans[1]++;
                }
            } else if (b[j] == 1) {
                if (vis[aa[j]] != counttime) {
                    vis[aa[j]] = counttime;
                    tans++;
                }
            } else {
                if (vis[aa[j]] != counttime) {
                    vis[aa[j]] = counttime;
                    tans++;
                }
            }
            ans[tans]++;
        }
        counttime++;
    }

    REP(i, 1, n) {
        printf("%d ", ans[i]);
    }
    printf("\n");

    return 0;
}

