inline int qpow(int a,int b=p-2){
    int r=1;
    for(;b;b>>=1,a=a*a%p) if(b&1) r=r*a%p;
    return r;
}

int n,m,ans,vis[N],fl[N];
vector<int> G[N];
map<pii,bool> mp;
struct v2{
    int x,y;
    v2 operator+(v2 o)const{return {x+o.x,y+o.y};}
    v2 operator-(v2 o)const{return {x-o.x,y-o.y};}
    int operator&(v2 o)const{return x*o.y-y*o.x;}
    int operator*(v2 o)const{return x*o.x+y*o.y;}
    bool operator<(v2 o)const{return y==o.y ? x<o.x : y<o.y;}
    bool operator==(v2 o)const{return x==o.x && y==o.y;}
}I,J,a[N],t[N];

inline bool cmp(v2 X,v2 Y){
    int o=(a[1]-X)&(a[1]-Y);
    return o?o>0:(a[1]-X)*(a[1]-X)<(a[1]-Y)*(a[1]-Y);
}
inline int chk(v2 A){each(i,1,n) if (a[i]==A) return i; return 0;}
inline ld ang(v2 A,v2 B){return A*B/sqrtl((A*A)*(B*B));}

int dfs(int u){
    int sz=1;
    for(int v:G[u]) sz+=dfs(v);
    ans=ans*qpow(sz)%p; return sz;
}

int convex(){
    int tp=0;
    each(i,1,n){
        while(tp>1 && (a[i]-t[tp-1]&t[tp]-t[tp-1])>=0) --tp;
        t[++tp]=a[i];
    }
    return tp;
}

inline void sol(){
    n=rd(); int tp=0;
    each(i,1,n) a[i].x=rd(),a[i].y=rd();
    I=a[1],J=a[2];
    each(i,2,n) if (a[i]<a[1]) swap(a[1],a[i]);
    sort(a+2,a+n+1,cmp);
    n=convex();
    each(i,1,n) a[i]=t[i];
    int i_,j_;
    if (!(i_=chk(I)) || !(j_=chk(J))) return puts("0"),void();

    mp.clear();
    each(i,1,n) G[i].clear(),fl[i]=vis[i]=0;

    each(l,1,n) each(r,l+1,n){
        ld mx1=-10,mx2=-10;
        int id1=-1,id2=-1,id;
        each(i,1,n) if(i!=l && i!=r){
            ld x=ang(a[l]-a[i],a[r]-a[i]);
            if(l<i && i<r){
                if(x>mx1) mx1=x,id1=i;
            }else{
                if(x>mx2) mx2=x,id2=i;
            }
        }
        if(mx1>-3.0 && mx2>-3.0 && acosl(mx2)+acosl(mx1)<PI) continue;

        if(mx2<-3.0) id=id1; 
        else if(mx1<-3.0) id=id2;
        else if(1-mx2*mx2<1-mx1*mx1) id=id2; 
        else id=id1;

        mp[{l,r}]=mp[{r,l}]=mp[{l,id}]=mp[{id,l}]=mp[{r,id}]=mp[{id,r}]=1;
    }

    if (!mp.count({i_,j_})) return puts("0"),void();

    queue<int> q; q.push(j_),vis[i_]=1;
    while(!q.empty()){
        int u=q.front(); vis[u]=1,q.pop();
        each(i,1,n) if(vis[i] && mp.count({i,u})){ 
            each(j,1,n) if( !vis[j] && mp.count({i,j}) && mp.count({u,j}) && !fl[j] ){
                fl[j]=1,q.push(j),G[u].push_back(j);
            }
        }
    }
    ans=1;
    each(i,1,n-1) ans=ans*i%p; 
    dfs(j_);
    printf("%lld\n",ans);
}

signed main(){
    for(int T=rd();T--;) sol();   
    return 0;
}

