ll util(int ind,string &s,int mx,int changed,vector<vector<vector<ll>>> &dp){
    if(ind==-1)return 0;
    if(dp[ind][mx][changed]!=-1)return dp[ind][mx][changed];
    ll vl=(pw(10,s[ind]-'A')) * ((s[ind]-'A') < mx?-1:1);
