using mod_t = uint64_t;
using coord = array<int, 2>;
const mod_t mod = 1'000'000'000 + 7;
const int N = 100'000;
const int K = 2'000 + 10;
const int L = 21;

mod_t fact[2 * N], ifact[2 * N];
vector<coord> anom;
mod_t dyn[K][L];

mod_t fastpow(mod_t b, mod_t e) {
	mod_t r = 1;
	for (; e; e >>= 1) {
		if (e & 1) {
			r *= b;
			r %= mod;
		}
		b *= b;
		b %= mod;
	}
	return r;
}

mod_t inv(mod_t a) {
	return fastpow(a, mod - 2);
}

mod_t C(int a, int b) {
	assert(0 <= a && a < N && 0 <= b && b < N);
	return fact[a + b] * ifact[a] % mod * ifact[b] % mod;
}

int main() {
	fact[0] = 1;
	for (int i = 1; i < 2 * N; ++i) fact[i] = fact[i - 1] * i % mod;
	for (int i = 0; i < 2 * N; ++i) ifact[i] = inv(fact[i]);
	int n, m, k, s;
	cin >> n >> m >> k >> s;
	anom.resize(k);
	for (auto &a: anom) {
		cin >> a[0] >> a[1];
		--a[0];
		--a[1];
	}
	if (k == 0) {
		cout << s << '\n';
		return 0;
	}
	anom.emplace_back(coord{0, 0});
	swap(anom.front(), anom.back());
	anom.emplace_back(coord{n - 1, m - 1});
	sort(begin(anom) + 1, end(anom) - 1, [](coord a, coord b) {
		return a[0] + a[1] < b[0] + b[1];
	});
	for (int i = 1; i <= k + 1; ++i) {
		const coord &ani = anom[i];
		dyn[i][0] = 0;
		dyn[i][1] = C(ani[0], ani[1]);
		for (int l = 2; l < L; ++l) dyn[i][l] = dyn[i][1];
		for (int j = 1; j < i; ++j) {
			int dx = ani[0] - anom[j][0], dy = ani[1] - anom[j][1];
			if (dx < 0 || dy < 0) continue;
			mod_t cxy = C(dx, dy);
			for (int l = 1; l < L; ++l) {
				dyn[i][l] += (mod + dyn[j][l - 1] - dyn[j][l]) * cxy;
				dyn[i][l] %= mod;
			}
		}
	}
	mod_t ans = 0;
	for (int i = 0; i < 20; ++i) {
		ans += s * (mod + dyn[k + 1][i + 1] - dyn[k + 1][i]);
		ans %= mod;
		s = (s + 1) / 2;
	}
	ans += 1 * (mod + C(n - 1, m - 1) - dyn[k + 1][20]);
	ans %= mod;
	ans *= inv(C(n - 1, m - 1));
	ans %= mod;
	cout << ans << '\n';
	return 0;
}

