		if(*pos==P)	--l;

		int ans=0,lstd=-1;

		while(lstd^D)

		{

			int w=min({D-lstd,P-p[l]-1-lstd,p[r]-P-1-lstd});

			add(ans,Mul(l+1==r?MOD-pre[m+1]:MOD-g[l+1][r-1],w));

			lstd+=w;

			if(P-lstd==p[l]+1)	--l;

			if(P+lstd==p[r]-1)	++r;

		}

		write(ans),puts("");

	}

	return 0;

}

