    int tot = (n * (n - 1)) / 2;
    for (int a = 0; a <= N; a++) {
        for (int b = 0; b <= zero; b++) {
            for (int c = 0; c <= tot; c++) {
                dp[a][b][c] = 1e9;
            }
        }
    }
    for (int i = 0; i < N; i++) {
        pref_sum[i + 1] = pref_sum[i] + b[i];
