                        dp[pref][i][c] + add * add);
                }
            }
        }
    }
    int add = pref_sum[N] * pref_sum[N];
    for (int i = 1; i <= tot; i++) {
        dp[N][zero][i] = min(dp[N][zero][i], dp[N][zero][i - 1]);
    }
    for (int i = 0; i <= tot; i++) {
