struct Scan {
  char buf[1 << 15], temp;
  int l = len(buf), r = l;
  bool go(char& c) {
    for (;; ++l) {
      if (r - l < 64) r = (r - l) + read(STDIN_FILENO, move(buf + l, buf + r, buf), len(buf) - (r - l)), l = 0;
      if (l == r) return c = {}, false;
      if (buf[l] > ' ') return c = buf[l++], true;
    }
  }
  bool go(string& s) {
    if (!go(temp)) return s = {}, false;
    for (s = temp; buf[l] > ' '; s += temp) go(temp);
    return true;
  }
  template <class T, enable_if_t<is_integral_v<T>, int> = 0> bool go(T& x) {
    if (!go(temp)) return x = {}, false;
    make_unsigned_t<T> u = (temp == '-' ? buf[l++] : temp) & 15;
    for (; buf[l] > ' '; ++l) (u *= 10) += buf[l] & 15;
    return x = temp == '-' ? -u : u, true;
  }
  template <class T, enable_if_t<is_floating_point_v<T>, int> = 0> bool go(T& x) {
    if (!go(temp)) return x = {}, false;
    char* endptr;
    if constexpr (is_same_v<T, float>) x = strtof(buf + (l - 1), &endptr);
    if constexpr (is_same_v<T, double>) x = strtod(buf + (l - 1), &endptr);
    if constexpr (is_same_v<T, long double>) x = strtold(buf + (l - 1), &endptr);
    return l = int(endptr - buf), true;
  }
  template <class C, enable_if_t<!is_same_v<typename C::value_type, char>, int> = 0> bool go(C& c) {
    for (auto&& e : c)
      if (!go(e)) return c = {}, false;
    return true;
  }
  template <class T> bool go(vector<T>& v) {
    for (auto&& e : v)
      if (!go(e)) return v = {}, false;
    return true;
  }
  template <class... Args> bool operator()(Args&... args) { return (..., go(args)); }
} scan;
struct Print {
  char buf[1 << 15], temp;
  int p = 0;
  void go(char c = '\0') {
    if (len(buf) - p < 64 || c == -1) write(STDOUT_FILENO, buf, p), p = 0;
    if (c > 0) buf[p++] = c;
  }
  void go(string_view sv) {
    for (char c : sv) go(c);
  }
  template <class T, enable_if_t<is_integral_v<T>, int> = 0> void go(T x) {
    go(), p = int(to_chars(buf + p, end(buf), x).ptr - buf);
  }
  template <class T, enable_if_t<is_floating_point_v<T>, int> = 0> void go(T x) {
    go(), p += snprintf(buf + p, len(buf) - p, "%.20Lf", (long double)(x));
  }
  template <class C, enable_if_t<!is_same_v<typename C::value_type, char>, int> = 0> void go(const C& c) {
    temp = '\0';
    for (auto&& e : c) go(exchange(temp, ' ')), go(e);
  }
  template <class... Args> void operator()(const Args&... args) {
    temp = '\0', (..., (go(exchange(temp, ' ')), go(args))), go('\n');
  }
  ~Print() { go(char(-1)); }
} print;

struct Graph {
  std::vector<std::array<int, 2>> edges;
  struct Pair_ : std::pair<int, int> {
    using std::pair<int, int>::pair;
    operator int() const { return first; }
  };
  std::vector<Pair_> adj_;
  std::vector<int> pos_;
  Graph() {}
  Graph(int n, int m) : pos_(n + 1) { edges.reserve(m); }
  int n() const { return pos_.size() - 1; }
  int m() const { return edges.size(); }
  void build() {
    for (auto&& [u, v] : edges) ++pos_[u], ++pos_[v];
    std::partial_sum(pos_.begin(), pos_.end(), pos_.begin()), adj_.resize(pos_[n()]);
    for (int e = m(); e--;) adj_[--pos_[edges[e][0]]] = {edges[e][1], e}, adj_[--pos_[edges[e][1]]] = {edges[e][0], e};
  }
  template <class T> struct View_ {
    T *first, *last;
    int size() const { return last - first; }
    T& operator[](int i) const { return *(first + i); }
    T* begin() const { return first; }
    T* end() const { return last; }
  };
  View_<Pair_> operator[](int v) { return {adj_.data() + pos_[v], adj_.data() + pos_[v + 1]}; }
  View_<const Pair_> operator[](int v) const { return {adj_.data() + pos_[v], adj_.data() + pos_[v + 1]}; }
};

struct DfsForest : Graph {
  std::vector<int> was, pe, d, low, sub, deg, in, seq;
  int num_dfs = 0;
  DfsForest() {}
  DfsForest(int n, int m) : Graph(n, m), was(n, -1), pe(n), d(n), low(n), sub(n), deg(n), in(n) { seq.reserve(n); }
  void dfs(int r, bool clear_seq = true) {
    if (clear_seq) seq.clear();
    was[r] = num_dfs, pe[r] = -1, d[r] = 0;
    dfs_impl_(r), ++num_dfs;
  }
  void dfs_all() {
    for (int v = 0, t = num_dfs; v < n(); ++v)
      if (was[v] < t) dfs(v, v == 0);
  }
  int p(int v) const { return ~pe[v] ? edges[pe[v]][0] : -1; }
  View_<Pair_> ch(int v) { return {(*this)[v].begin(), (*this)[v].begin() + deg[v]}; }
  View_<const Pair_> ch(int v) const { return {(*this)[v].begin(), (*this)[v].begin() + deg[v]}; }
  void dfs_impl_(int v) {
    std::stable_partition((*this)[v].begin(), (*this)[v].end(), [&](int u) { return was[u] < num_dfs; });
    low[v] = d[v], sub[v] = 1, deg[v] = 0, in[v] = seq.size(), seq.push_back(v);
    for (auto&& [u, e] : (*this)[v])
      if (was[u] < num_dfs) {
        edges[e] = {v, u};
        was[u] = num_dfs, pe[u] = e, d[u] = d[v] + 1;
        dfs_impl_(u);
        low[v] = std::min(low[v], low[u]), sub[v] += sub[u], ++deg[v];
      } else if (e != pe[v] && d[u] < d[v]) {
        edges[e] = {v, u};
        low[v] = std::min(low[v], d[u]);
      }
  }
};

#undef NDEBUG
#include <cassert>

int main() {
  int tt;
  scan(tt);
  while (tt--) {
    int n;
    scan(n);
    DfsForest g(n, n - 1);
    for (int e : Rep(n - 1)) {
      int u, v;
      scan(u, v);
      --u, --v;
      g.edges.push_back({u, v});
    }
    g.build();
    g.dfs(0);

    vector<int> f(n);
    vector<bool> ok(n);
    for_each(rbegin(g.seq), rend(g.seq), [&](int v) {
      if (g.deg[v] == 0) {
        f[v] = 1;
        ok[v] = false;
        return;
      }

      ok[v] = false;
      f[v] = 0;
      int cnt = 0;
      for (int u : g.ch(v)) {
        if (!ok[u]) {
          ok[v] = true;
        } else {
          ++cnt;
        }
        f[v] += f[u];
      }
      f[v] -= min(cnt, g.deg[v] - 1);
    });

    print(f[0]);
  }
}

