      bss.push_back(seqs[i]);
    }
// cerr<<"M = "<<M<<endl;
// for(int i=0;i<M;++i){cerr<<ns[i]<<"; ";pv(bss[i].begin(),bss[i].end());}

    for (int i = 0; i < M; ++i) for (int k = 0; k <= K; ++k) {
