int power(int a, int n) {

	int ret = 1;

	for (int i = 1; i <= n; i <<= 1) {

		if (n & i) {

			ret = 1LL * ret * a % MOD;

		}

		a = 1LL * a * a % MOD;

	}

	return ret;

}



void add(int &a, int b) {

	if ((a += b) >= MOD) {

		a -= MOD;

	}

}



int comb(int n, int m) {

	assert(n <= MOD && m <= MOD);

	int ret = 1;

	for (int i = 1; i <= m; i++) {

		ret = 1LL * ret * ((n - i + 1 + MOD) % MOD) % MOD;

		ret = 1LL * ret * rev[i] % MOD;

	}

	return ret;

}



int main() {

	scanf("%d %d %d", &n, &d, &MOD);

	if (n <= 2) {

		printf("1\n");

		return 0;

	}

	rev[0] = 1;

	for (int i = 1; i <= d; i++) {

		rev[i] = power(i, MOD - 2) % MOD;

	}

	f[1][0] = 1;

	for (int i = 1; i <= n / 2; i++) {

		if (i == 1) {

			g[1] = 1;

		} else {

			g[i] = f[i][d - 1];

		}

		if (g[i] == 0) continue;

