				}

				for (int l = 1; k + l <= d && j + l * i <= n; l++) {

					add(f[j + l * i][k + l], 1LL * f[j][k] * comb(g[i] + l - 1, l) % MOD);

				}

			}

		}

	}

	int ans = f[n][d];

	//printf("%d\n", f[n / 2][d - 1]);

