void maket(int x, int s, int k) {
  start[x] = s;
  cnt[x] = k;
  mid[x] = s + k / 2;
  if (k <= 2) {
    return;
  }
  maket(2 * x + 0, s, k / 2);
  maket(2 * x + 1, s + k / 2, k - k / 2);
}

void inst(int x, int qi) {
  if (Q[qi].X < mid[x] && mid[x] <= Q[qi].Y) {
    qs[x].push_back(qi);
    return;
  }
  if (Q[qi].Y < mid[x]) inst(2 * x + 0, qi);
  else                  inst(2 * x + 1, qi);
}

