int solve(int x, int y, int z, int lst){
  if(x+y+z==0)return 1;
  int &ret = dp[x][y][z][lst];
  if(~ret)return ret;
  ret = 0;
  if(lst!=0&&x)
    ret += 1ll * x * solve(x-1,y,z,0) % MOD;
  if(lst!=1&&y)
    ret += 1ll * y * solve(x,y-1,z,1) % MOD;
  if(ret>=MOD)ret-=MOD;
  if(lst!=2&&z)
    ret += 1ll * z * solve(x,y,z-1,2) % MOD;
  if(ret>=MOD)ret-=MOD;
  return ret;
}
