const int  N= 105;
int dp[N][N];
int a[N];
int n;
// back=first not painted cell, front=next cell of the last painted cell
//both are same due to the way its handled
int solve(int in,int back){
    if(in==n){
        if(back>=in){
            return 0;
        }
        return n;
    }
    if(dp[in][back]!=-1){
        return dp[in][back];
    }
    int ans= solve(in+1,back);
    if(back>=in){
        //always paint in front
        int nxt=in+a[in]-1;
        nxt=min(nxt,n-1);
        if(nxt>=back){
            ans= min(ans, 1+ solve(in+1,nxt+1));
        }
    }
    else{
        int rem=in-back+1;
        //testing for front
        int nxt=in+a[in]-1;
        nxt=min(nxt,n-1);
        //colour upto next
        vector<pair<int,int>>v;
        for(int i=in+1;i<=nxt;i++){
            int lst= i-a[i]+1;
            lst=max(lst,0);
            if(lst<=back){
                v.push_back({min(i+a[i]-1,n-1),i});
            }
        }
        sort(v.begin(), v.end());
        if(!v.empty()){
            auto [fr,in1]= v[0];
            //use in1 for back;
            ans= min(ans,2+solve(nxt+1,nxt+1));
            //also use someone for front
            int n_nxt=nxt;
            for(int i=in+1;i<=nxt;i++){
                if(i==in1)  continue;
                n_nxt=max(n_nxt,i+a[i]-1);
            }
            n_nxt=min(n_nxt,n-1);
            ans= min(ans,3+solve(nxt+1,n_nxt+1));
        }
        if(rem<=a[in]){
            //sufficient for back;
            //use for back;
            ans= min(ans, 1+ solve(in+1,in+1));
        }
    }
    return dp[in][back]=ans;
}

