const ll INF = 1e18 + 69;

struct CHT{ // casual CHT
    #define Node pair<ll, ll>
    vector<Node> hull, suboptimal;
    vector<double> inter;

    double getInter(Node a, Node b){return (double) (b.second - a.second) / (a.first - b.first);}
    ll f(Node s, ll x){return s.first * x + s.second;}

    void add(Node x){
        if (hull.empty()) {hull.push_back(x); return;}
        if (hull.back().first == x.first){
            suboptimal.push_back(hull.back());
            hull.pop_back();
            if (inter.size()) inter.pop_back();
        }
        while(hull.size() >= 2){
            double x1 = getInter(hull.back(), x), x2 = inter.back();
            if (x1 >= x2) break;
            suboptimal.push_back(hull.back());
            hull.pop_back(); inter.pop_back();
        }
        if (hull.size()) inter.push_back(getInter(hull.back(), x));
        hull.push_back(x);
    }

    vector<ll> get_val(ll x, int r = 0){
        int idx = lower_bound(ALL(inter), x) - inter.begin();
        vector<ll> ans;
        for(int i = idx - r; i <= idx + r; ++i) if (i >= 0 && i < size()){
            ans.push_back(f(hull[i], x));
        }  
        return ans;
    }

    int size(){return hull.size();}
};


struct CHT_extended{ // mlg super pro vip CHT
    #define Node pair<ll, ll>
    int k;
    vector<CHT> hull_max;

    CHT_extended(int k): k(k){
        for(int i = 0; i < k; ++i) hull_max.push_back(CHT());
    }

    void add(vector<Node> a){
        for(int i = 0; i < k; ++i){
            sort(ALL(a));
            for(Node j: a) hull_max[i].add(j);
            a = hull_max[i].suboptimal; hull_max[i].suboptimal.clear();
        }
    }

    vector<ll> get(ll x){
        vector<ll> ans;
        for(int i = 0; i < k; ++i){
            vector<ll> cur = hull_max[i].get_val(x, k - i - 1);
            for(ll j: cur) ans.push_back(j);
        }
        sort(ALL(ans), greater<ll>());
        while(ans.size() > k) ans.pop_back();
        return ans;
    }
};


const int N = 1e5 + 69;

int n, q;
vector<pair<int,int>> graph[N];
vector<pair<int,int>> queries[N];
ll ans[N];
ll depth[N];
ll diameter = 0;

void find_diameter(int u, int p){
    pair<ll, ll> ma = {0, 0};
    for(pair<int,int> v: graph[u]) if (v.first != p){
        find_diameter(v.first, u);
        ll val = depth[v.first] + v.second;
        maximize(depth[u], val);
        if (ma.first < val){
            ma.second = ma.first;
            ma.first = val;
        }
        else maximize(ma.second, val);
    }
    maximize(diameter, ma.first + ma.second);
}

void dfs(int u, int p){
    vector<pair<ll, ll>> f;
    for(pair<ll, ll> i: graph[u]) f.push_back({i.second, depth[i.first]});

    CHT_extended hull_max(2);
    hull_max.add(f);

    for(pair<int,int> i: queries[u]){
        ans[i.second] = diameter;
        vector<ll> cur = hull_max.get(i.first);
        ll sum = 0;
        for(ll j: cur) sum += j;
        maximize(ans[i.second], sum);
    }


    pair<ll, ll> ma = {0, 0};
    for(pair<int,int> v: graph[u]){
        ll val = depth[v.first] + v.second;
        if (ma.first < val){
            ma.second = ma.first;
            ma.first = val;
        }
        else maximize(ma.second, val);
    }

    for(pair<int, int> v: graph[u]) if (v.first != p){
        ll tmp1 = depth[u], tmp2 = depth[v.first];

        if (depth[v.first] + v.second == ma.first) depth[u] = ma.second;
        else depth[u] = ma.first;
        maximize(depth[v.first], depth[u] + v.second);

        dfs(v.first, u);

        depth[u] = tmp1, depth[v.first] = tmp2;
    }

}


