double dp[1 << 18];

double ar[18][18];

int get_cnt(int mask) {

	int ans = 0;

	while (mask) {

		if (mask & 1)

			++ans;

		mask >>= 1;

	}

	return ans;

}

inline void push(int mask, int n) {

	double d = dp[mask];

	int cnt = get_cnt(mask);

	if (cnt == 1)

		return;

	double p = 2.0 / (double)(cnt * (cnt - 1));

	for (int i = 0; i < n; ++i) {

		if (!(mask & (1 << i)))

			continue;

		for (int j = i + 1; j < n; ++j) {

			if (!(mask & (1 << j)))

				continue;

			dp[mask ^ (1 << j)] += d * ar[i][j] * p;

			dp[mask ^ (1 << i)] += d * ar[j][i] * p;

		}

	}

	return;

}



