int comp (const void *a_, const void *b_)
{
 const char *a = (const char*) a_;
 const char *b = (const char*) b_;

 return *b - *a;
}

void reorder(char * num)
{
 qsort(num, strlen(num), sizeof(char), comp);
}

int step(char * num_a, char num_b0)
{
 if (num_a[0] > num_b0){
  for (int i = 1; num_a[i] != 0; i++)
  {
   if (num_b0 >= num_a[i])
   {
    char temp = num_a[0];
    num_a[0] = num_a[i];
    num_a[i] = temp;
    reorder(num_a+1);
    if (num_a[0] < num_b0)
     return 0;
    else
     return 1;
   }
  }
  return -1;
 }else{
  return 0;
 }
}



void work (char * num_a, char * num_b)
{
 while (*num_a){
  reorder(num_a);

  int r = step(num_a, num_b[0]);
  if (num_a[0] < num_b[0])
   break;
  if ( r == -1)
  {
up:
   num_a--; num_b--;
   char v = num_a[0] - 1;
   reorder(num_a);
   r = step(num_a, v);

   if (num_a[0] < num_b[0])
    break;
   if (r == -1)
    goto up;
  }
  num_a++; num_b++;
 }
}

