vll getPrimeFacs(ll n)

{

    vll p;

    while (n % 2 == 0)

    {

        p.push_back(2);

        n /= 2;

    }

    for (int i = 3; i * i <= n; i += 2)

    {

        while (n % i == 0)

        {

            p.push_back(i);

            n /= i;

        }

        if (n == 1)

        {

            break;

        }

    }

    if (n > 1)

    {

        p.push_back(n);

    }

    return p;

}



ll fast_pow(ll a, ll b, ll m)

{

    ll ret = 1;

    while (b)

    {

        if (b & 1)

        {

            ret *= a;

            ret %= m;

        }

        a *= a;

        a %= m;

        b >>= 1;

    }

    return ret;

}



ll gcd(ll a, ll b)

{

    return a ? gcd(b % a, a) : b;

}



ll lcm(ll a, ll b)

{

    return (a * b) / gcd(a, b);

}



