class EAPerfectProblem {
 public:
  void solveOne() {
    int n, modulo;
    cin >> n >> modulo;
    mint::set_mod(modulo);
    mint res;
    vector<mint> invs(n + 2);
    vector<mint> facts(n + 2);
    facts[0] = 1;
    vector<mint> invfacts(n + 2);
    invfacts[0] = 1;
    for (int i = 1; i < invs.size(); ++i) {
      invs[i] = mint(i).inv();
      facts[i] = i * facts[i - 1];
      invfacts[i] = invs[i] * invfacts[i - 1];
    }
    if (n == 1) {
      res = n + 1;
    } else {
      for (int a = 1; a <= n + 1; ++a) {
        vector<unordered_map<int, mint>> ways(n);
        ways[n - 1][n * (n + 1)] = 1;
        for (int v = n + 1; v > a; --v) {
          for (int old = 1; old < n; ++old) {
            int rsum = v * a;
            for (auto p : ways[old]) {
              int nsum = min(rsum, p.first);
              for (int cnt = 1; cnt <= old; ++cnt) {
                nsum -= v;
                if (nsum < (old - cnt + 1) * a) {
                  break;
                }
                ways[old - cnt][nsum] += p.second * invfacts[cnt];
              }
            }
          }
        }

        for (int old = 0; old < n; ++old) {
          if (old > 0) {
            int rsum = a * a;
            if (rsum < a * (old + 1)) continue;
          }
          for (auto p : ways[old]) {
            res += p.second * invfacts[old + 1];
          }
        }
      }
      res *= facts[n];
    }
    cout << res.val() << "\n";
  }

  void solve() {
    int nt = 1;
    for (int it = 0; it < nt; ++it) {
      solveOne();
    }
  }
};


int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);
    EAPerfectProblem solver;


    solver.solve();
    return 0;
}

