{
	if (l==a && r==b)
	{
		t[x]+=v; return;
	}
	int mid=l+r>>1;
	if (b<=mid) insert(l,mid,a,b,t,v,x<<1);
	else if (a>mid) insert(mid+1,r,a,b,t,v,x<<1|1);
	else
	{
